      "path": "packages/docker/src/index.ts",
      "content": "/**\n * @hyzyn/dsh-docker — DSH Web GUI 的 Docker 容器面板（host 半体）。\n *\n * 与 dsh-tty 的关系（方案 A：独立插件，tty 零改动）：\n *   - **连接簿**：只读复用 tty 的 entry settings（DSH ≥0.1.7 的\n *     `settings.describe()`，经 kit 的 `readSettingsEntry(ctx, 'tty')`）的\n *     `sshHosts`。tty 未安装时退化为「只支持本机 / 内联 SSH 字段」。\n *   - **主机指纹**：本插件自持一份 `hostKeys`（TOFU），并优先读取 tty 已记录\n *     的指纹作为种子，避免同一主机在两处重复确认。\n *   - **执行通道**：自持池化 SSH exec（src/ssh-exec.ts），与 tty 的 PTY 会话\n *     完全独立；本机目标直接 spawn docker CLI。\n *\n * 信任模型（与 tty 不同，必须强调）：\n *   docker socket ≈ 该主机的 root 权限。因此**默认只读**：\n *   `allowMutations` 未开启时 start/stop/restart/remove 一律拒绝，\n *   `allowExec` 未开启时 `docker exec` 一律拒绝；两个开关都需用户在设置卡片\n *   显式打开。agent 工具同样受这两个开关约束（未开启时连工具都不注册）。\n */\nimport type { Context } from '@deepseek-ai/cordis'\nimport { accessSync, constants } from 'node:fs'\nimport { delimiter, basename, join } from 'node:path'\nimport z from '@deepseek-ai/schemastery'\nimport { definePlugin, hasSameOriginProof, isLoopbackRequestStrict, originProofHint, plainConfig, readSettingsEntry, registerLiteralSection, settingsEntryScope, suppressAutoSettingsPage } from '@hyzyn/dsh-kit'\nimport type { SettingsEntryScope } from '@hyzyn/dsh-kit'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport { auditCapabilityUse, audited } from './audit.js'\nimport type { CapabilityUseFields } from './audit.js'\nimport {\n  DockerApi,\n  MAX_RESULT_LINES,\n  assertBin,\n  assertImageRef,\n  assertName,\n  assertRef,\n  assertSince,\n  createRunner,\n  parseImageHistoryJson,\n  parseImageHistoryText,\n  parseContainerEvent,\n  parseEventsJson,\n  parseImageInspectJson,\n  parseInspectJson,\n  parsePsJson,\n  parseStatsJson,\n  suggestContainerNames,\n} from './docker.js'\nimport type { Diagnosis, DiagnosisEvidence } from './diagnose.js'\nimport { historyTrend, sampleFromDiagnosis } from './history.js'\nimport type { DiagnosisSample, HistoryTrend } from './history.js'\nimport { DiagnosisHistoryStore, HISTORY_SCHEMA_VERSION, diagnosisHistoryPaths } from './history-store.js'\nimport type { DiskUsageTotals } from './docker.js'\nimport type {\n  AttentionItem,\n  ContainerDetail,\n  ContainerEvent,\n  ContainerStats,\n  ContainerSummary,\n  DockerTarget,\n  ImageDetail,\n  ImageHistoryEntry,\n  ImageSummary,\n  NetworkDetail,\n  NetworkSummary,\n  ResolvedTarget,\n  StreamHandlers,\n  VolumeDetail,\n  VolumeSummary,\n} from './docker.js'\nimport { RemoteExec, sanitizeJumpSpec, sanitizeProxyCommand, setCredentialResolver, sshTarget } from './ssh-exec.js'\nimport {\n  auditLoadedGrants,\n  attachTierGate,\n  attachTierRestrict,\n  bindCapabilitySources,\n  capabilityDeniedMessage,\n  capabilityGrantAt,\n  capabilityGranted,\n  capabilityGrantVia,\n  capabilityPaths,\n  createElevationManager,\n  dshHome,\n  sharedGrantStore,\n} from '@hyzyn/dsh-kit'\nimport type { TierClass } from '@hyzyn/dsh-kit'\nimport type { CredentialResolver, ExecLogger, HostKeyRecord, HostKeyStore, SshSpec } from './ssh-exec.js'\n\nexport type { HostKeyRecord } from './ssh-exec.js'\nexport type { ContainerSummary, ContainerDetail, ContainerStats, ContainerEvent, ImageSummary, NetworkSummary, NetworkDetail, VolumeSummary, VolumeDetail, DockerTarget } from './docker.js'\n\n/*\n * 档位闸的分类表（docs/permission-tier-plan.md §2.1）：`read` 纯读 / 固定二进制探测\n * （docker_connect_local 不在能力开关里，见 connectLocal 的注释）；`write` 容器与镜像的变更\n * （docker_image_pull 是拉取非破坏，但改本地状态，且本就注册在 allowMutations 组里）；\n * `exec` 容器内一次性命令。名单必须与 refreshTools 里 add() 注册的工集一一对应——对账由\n * test/tier-gate.test.ts 从 add() 调用处现算（漏分类 → 红）。与 allowMutations / allowExec\n * 的关系是**双层并存**：静态开关管注册（宿主级、持久授权），档位闸管已注册调用的放行\n * （逐调用、会话级），谁也不取代谁。\n */\nexport const DOCKER_TIER_CLASS: Record<string, TierClass> = {\n  docker_targets: 'read',\n  docker_connect_local: 'read',\n  docker_ps: 'read',\n  docker_attention: 'read',\n  docker_inspect: 'read',\n  docker_logs: 'read',\n  docker_logs_grep: 'read',\n  docker_stats: 'read',\n  docker_events: 'read',\n  // 批一的两条诊断工具：四路采集全是只读（inspect / logs / events / stats + top），\n  // 对账由 test/tier-gate.test.ts 从 add() 调用处现算——漏分类会让档位闸静默放行\n  docker_top: 'read',\n  docker_diagnose: 'read',\n  // 批二：磁盘汇总（system df）与等价 docker run 推导——都是只读采集/纯文本生成\n  docker_disk_usage: 'read',\n  docker_run_command: 'read',\n  docker_images: 'read',\n  docker_image_inspect: 'read',\n  docker_networks: 'read',\n  docker_volumes: 'read',\n  docker_action: 'write',\n  docker_image_remove: 'write',\n  docker_image_prune: 'write',\n  docker_image_pull: 'write',\n  docker_exec: 'exec',\n}\n\n/** 本插件 agent 工具的名单前缀（档位闸只听这些名字）。 */\nexport const DOCKER_TIER_PREFIXES = ['docker_'] as const\n\n/* ------------------------------------------------------------------ *\n * 配置\n * ------------------------------------------------------------------ */\n\nexport interface Config {\n  /** 关闭整个插件。默认开。 */\n  enabled?: boolean\n  /** 是否向 agent 注入插件能力公告。默认开。 */\n  announceToAgent?: boolean\n  /** docker CLI 可执行文件名 / 路径（podman 可填 podman）。默认 docker。 */\n  dockerBin?: string\n  /** 允许 start/stop/restart/remove（含对应 agent 工具）。默认关。 */\n  allowMutations?: boolean\n  /** 允许一次性 docker exec（含对应 agent 工具）。默认关。 */\n  allowExec?: boolean\n  /** exec 默认超时秒数（1~120）。默认 30。 */\n  execTimeoutSec?: number\n  /** 面板统计刷新间隔秒数（1~60）。默认 5。 */\n  pollIntervalSec?: number\n  /** 日志默认尾部行数（1~5000）。默认 200。 */\n  logTailDefault?: number\n  /** 单次命令输出上限（KB，1~8192）。默认 512。 */\n  maxOutputKb?: number\n  /** 目标列表（本机 / SSH）。 */\n  targets?: DockerTarget[]\n  /** SSH 主机指纹记录（TOFU，随 settings 落盘）。 */\n  hostKeys?: HostKeyRecord[]\n}\n\nconst TARGET_SCHEMA = z.object({\n  name: z.string().required(),\n  kind: z.union([z.const('local'), z.const('ssh')]).default('local'),\n  /** kind=ssh：引用 tty 连接簿条目名（可留空，改用下方内联字段）。 */\n  book: z.string().default(''),\n  host: z.string().default(''),\n  port: z.natural().max(65535).default(22),\n  username: z.string().default(''),\n  auth: z.union([z.const('agent'), z.const('key'), z.const('password')]).default('agent'),\n  keyPath: z.string().default(''),\n  /** 建议写 `env:NAME` 凭据引用（官方凭据层解析），避免明文落盘。 */\n  password: z.string().default(''),\n  passphrase: z.string().default(''),\n  agentForward: z.boolean().default(false),\n})\n\nconst HOST_KEY_SCHEMA = z.object({\n  host: z.string().required(),\n  port: z.natural().max(65535).default(22),\n  /** 同一 host:port 的全部主机密钥指纹（rsa / ed25519 等各一条）。 */\n  fingerprints: z.array(z.string()).default([]),\n  /** 旧版单指纹字段：仅作迁移输入（sanitizeHostKeys 会并进 fingerprints）。 */\n  fingerprint: z.string().default(''),\n})\n\n/**\n * 运行时 Config schema——DSH ≥0.1.7 起同时就是本插件的 settings 存储。\n *\n * 全部字段都标 `.volatile()`：它们都是卡片可改项（见 KNOWN_CONFIG_KEYS），而\n * `settings.update(entryId, patch)` 只接受 volatile 路径；loader 对 volatile-only\n * 变更原地更新引用并发 `loader/volatile-update`，不重挂插件——插件订阅后走\n * `applySection` 热应用（见 kit 的 settingsEntryScope）。\n */\nexport const Config: z = z.object({\n  enabled: z.boolean().default(true).volatile(),\n  announceToAgent: z.boolean().default(true).volatile(),\n  dockerBin: z.string().default('docker').volatile(),\n  allowMutations: z.boolean().default(false).volatile(),\n  allowExec: z.boolean().default(false).volatile(),\n  execTimeoutSec: z.natural().max(120).default(30).volatile(),\n  pollIntervalSec: z.natural().max(60).default(5).volatile(),\n  logTailDefault: z.natural().max(5000).default(200).volatile(),\n  maxOutputKb: z.natural().max(8192).default(512).volatile(),\n  targets: z.array(TARGET_SCHEMA).default([]).volatile(),\n  hostKeys: z.array(HOST_KEY_SCHEMA).default([]).volatile(),\n})\n\n/** 可经 HTTP POST 写入的配置键（白名单）。 */\nconst KNOWN_CONFIG_KEYS = new Set([\n  'enabled',\n  'announceToAgent',\n  'dockerBin',\n  'allowMutations',\n  'allowExec',\n  'execTimeoutSec',\n  'pollIntervalSec',\n  'logTailDefault',\n  'maxOutputKb',\n  'targets',\n  'hostKeys',\n  /** 显式清空全部目标的确认位（见 POST /config 的空数组防丢保护）。 */\n  'clearTargets',\n  /** 显式删除 SSH 主机密钥记录：[{host, port}]（hostKeys 是并集合并，删除必须显式）。 */\n  'hostKeysRemove',\n])\n\n/** 解析后的运行期配置（settings 与 composition 两条来源统一到这一形状）。 */\ninterface LiveConfig {\n  enabled: boolean\n  announceToAgent: boolean\n  dockerBin: string\n  allowMutations: boolean\n  allowExec: boolean\n  execTimeoutSec: number\n  pollIntervalSec: number\n  logTailDefault: number\n  maxOutputKb: number\n  targets: DockerTarget[]\n  hostKeys: HostKeyRecord[]\n}\n\n/** 工具返回值形状（与 defineTool 的 output.schema 推断结果一致）。 */\ninterface ToolTargetRow {\n  name: string\n  kind: string\n  label: string\n  ok?: boolean\n  error?: string\n}\n\n/**\n * 「连接本机」的结果（面板按钮 / `POST /connect-local` / `docker_connect_local` 三条入口共用同一份）。\n *\n * `saved` 与 `reachable` 刻意分开：配置写入（本次真正的副作用）与**只读探测**（daemon 现在通不通）\n * 是两件事——探测失败不该把「目标已添加」说成失败（用户下次启动 daemon 后就能用），\n * 但也绝不能只说「已连接」而把 daemon 没起来这件事瞒过去（那正是「面板空的、不知道为啥」的来源）。\n */\ninterface ConnectLocalResult {\n  name: string\n  kind: 'local'\n  created: boolean\n  saved: boolean\n  reachable: boolean\n  serverVersion?: string\n  message: string\n}\n\n/**\n * `describeLocalProbeFailure` 的额外上下文（都只能由调用方探测得到，所以外挂进来——\n * 那个函数刻意保持**纯文本进、纯文本出**，好让它能被单测直接驱动）。\n */\ninterface LocalProbeHint {\n  /** 失败是不是超时（来自 `ProbeResult.timedOut`）。 */\n  timedOut?: boolean\n  /** CLI 缺失时，PATH 里找到的别的容器 CLI（见 findAlternativeLocalCli），如 `podman`。 */\n  alternativeCli?: string\n}\n\ninterface ToolAttentionRow {\n  id: string\n  name: string\n  image: string\n  state: string\n  health?: string\n  reasons: string[]\n  exitCode?: number\n  oomKilled: boolean\n  restartCount?: number\n}\n\ninterface ToolPsRow {\n  id: string\n  name: string\n  image: string\n  state: string\n  status: string\n  health?: string\n  ports?: string\n  composeProject?: string\n  composeService?: string\n}\n\ninterface ToolLogRow {\n  target: string\n  id: string\n  text: string\n  truncated?: boolean\n}\n\ninterface ToolStatRow {\n  id: string\n  name: string\n  cpuPercent?: number\n  memUsage: string\n  memPercent?: number\n  netIO: string\n  blockIO: string\n  pids?: number\n}\n\ninterface ToolEventRow {\n  action: string\n  name: string\n  image: string\n  composeProject?: string\n  time?: number\n  exitCode?: number\n}\n\n/** `docker_top` 的一行进程（字段全 string 的 schema 形状）。 */\ninterface ToolTopProcess {\n  pid: string\n  ppid: string\n  user: string\n  stat: string\n  elapsed: string\n  cpu: string\n  mem: string\n  command: string\n}\n\ninterface ToolTopRow {\n  target: string\n  id: string\n  name: string\n  processes: ToolTopProcess[]\n  truncated: boolean\n}\n\n/**\n * `docker_diagnose` 的证据块：**可缺字段是「省略」而不是 null**。\n *\n * 与 HTTP 响应（`DiagnosisEvidence`）刻意不同：`output.schema` 没有 null 类型，\n * 往 `{type:'string'}` 里塞 null 会被宿主校验挡掉整条结果（本包既有工具一律用\n * 「缺了就不写这个键」的写法）。业务语义不变——缺席 = 没采到 / 不适用，渲染时给 `—`。\n */\ninterface ToolDiagnosisEvidence {\n  state?: string\n  status?: string\n  health?: string\n  healthLastOutput?: string\n  exitCode?: number\n  oomKilled?: boolean\n  restartCount?: number\n  startedAt?: string\n  finishedAt?: string\n  memoryLimitBytes?: number\n  cpuQuota?: number\n  logLines?: number\n  errorLines?: number\n  eventCount?: number\n  cpuPercent?: number\n  memBytes?: number\n  memPercent?: number\n}\n\ninterface ToolDiagnosisTimelineEntry {\n  at?: string\n  kind: string\n  text: string\n}\n\n/**\n * 工具侧的历史样本：**可缺字段省略而不是 null**。\n *\n * `defineTool` 的输出 schema 没有 null 类型（写 null 会被宿主校验挡掉**整条**结果），\n * 所以 `restartCount` / `memPercent` / `errorLines` 为 null 时**不出现**——与\n * `toToolEvidence` 同一条规矩（那条注释里记着踩过的现场）。\n */\ninterface ToolDiagnosisHistorySample {\n  at: string\n  severity: string\n  code: string\n  findings: string[]\n  restartCount?: number\n  memPercent?: number\n  errorLines?: number\n}\n\n/** 工具侧的趋势：`window` 在样本 <2 时**不出现**（schema 没有 null 类型）。 */\ninterface ToolHistoryTrend {\n  count: number\n  window?: { from: string; to: string }\n  verdict: HistoryTrend['verdict']\n  numbers: HistoryTrend['numbers']\n  newFindings: string[]\n  resolvedFindings: string[]\n  aggravating: boolean\n}\n\ninterface ToolDiagnosisHistory {\n  samples: ToolDiagnosisHistorySample[]\n  trend: ToolHistoryTrend\n  recorded: boolean\n}\n\ninterface ToolDiagnosisRow {\n  target: string\n  id: string\n  name: string\n  verdict: { severity: string; code: string; summary: string }\n  findings: Array<{ code: string; severity: string; title: string; detail: string }>\n  evidence: ToolDiagnosisEvidence\n  timeline: ToolDiagnosisTimelineEntry[]\n  suggestions: string[]\n  logTail: string\n  /** 最近 N 条历史样本 + 趋势（批三）。写盘 / 读盘失败时是空样本 + `recorded: false`。 */\n  history: ToolDiagnosisHistory\n}\n\n/**\n * 诊断历史视图（HTTP 与 agent 工具共用的一份形状）：最近 N 条样本 + 趋势 + 本次是否真的记了一条。\n *\n * `samples` 里**没有日志原文**，这是刻意的（见 src/history.ts 文件头）：历史只记结论与数字，\n * 日志原文可能带凭证。客户端在历史块下方也会把这句话写给用户看。\n */\nexport interface DiagnosisHistoryView {\n  samples: DiagnosisSample[]\n  trend: HistoryTrend\n  /** 本次调用是否真的追加了一条（去重命中时为 false）。 */\n  recorded: boolean\n}\n\n/** `docker_disk_usage` 的一行汇总（`type` 是 docker 的英文分类，原样给）。 */\ninterface ToolDiskSummary {\n  type: string\n  totalCount: number\n  active: number\n  size: string\n  reclaimable: string\n}\n\ninterface ToolDiskImage {\n  id: string\n  repository: string\n  tag: string\n  size: string\n  sharedSize: string\n  uniqueSize: string\n  /** 「谁在用」：用这个镜像的容器数（0 = 未使用，可回收）。 */\n  containers: number\n}\n\ninterface ToolDiskVolume {\n  name: string\n  driver: string\n  size: string\n  /** 「谁在用」：挂载这个卷的容器数。 */\n  links: number\n}\n\ninterface ToolDiskBuildCache {\n  id: string\n  type: string\n  size: string\n  inUse: boolean\n}\n\n/** 磁盘工具每类明细回多少行（契约 §2.2）：模型要的是「有没有可回收的」，不是迁移清单。 */\nconst DISK_TOOL_ROWS = 20\n\ninterface ToolDiskRow {\n  target: string\n  summary: ToolDiskSummary[]\n  images: ToolDiskImage[]\n  volumes: ToolDiskVolume[]\n  buildCache: ToolDiskBuildCache[]\n  /** 截断前的真实条数（每类）——工具只回 20 行，这个数字让模型知道还有多少。 */\n  totals: DiskUsageTotals\n  truncated: { images: boolean; volumes: boolean; buildCache: boolean }\n  degraded: boolean\n  degradedReason?: string\n}\n\n/** `docker_run_command` 的返回（纯文本生成，没有任何副作用）。 */\ninterface ToolRunCommandRow {\n  target: string\n  id: string\n  name: string\n  command: string\n  warnings: string[]\n  secretKeys: string[]\n  omitted: string[]\n}\n\n/** HTTP 契约（null 到齐）→ 工具 schema 形状（null 变「省略」）。 */\nfunction toToolEvidence(evidence: DiagnosisEvidence): ToolDiagnosisEvidence {\n  return {\n    state: evidence.state,\n    status: evidence.status,\n    oomKilled: evidence.oomKilled,\n    ...(evidence.health === null ? {} : { health: evidence.health }),\n    ...(evidence.healthLastOutput === null ? {} : { healthLastOutput: evidence.healthLastOutput }),\n    ...(evidence.exitCode === null ? {} : { exitCode: evidence.exitCode }),\n    ...(evidence.restartCount === null ? {} : { restartCount: evidence.restartCount }),\n    ...(evidence.startedAt === null ? {} : { startedAt: evidence.startedAt }),\n    ...(evidence.finishedAt === null ? {} : { finishedAt: evidence.finishedAt }),\n    ...(evidence.memoryLimitBytes === null ? {} : { memoryLimitBytes: evidence.memoryLimitBytes }),\n    ...(evidence.cpuQuota === null ? {} : { cpuQuota: evidence.cpuQuota }),\n    ...(evidence.logLines === null ? {} : { logLines: evidence.logLines }),\n    ...(evidence.errorLines === null ? {} : { errorLines: evidence.errorLines }),\n    ...(evidence.eventCount === null ? {} : { eventCount: evidence.eventCount }),\n    ...(evidence.cpuPercent === null ? {} : { cpuPercent: evidence.cpuPercent }),\n    ...(evidence.memBytes === null ? {} : { memBytes: evidence.memBytes }),\n    ...(evidence.memPercent === null ? {} : { memPercent: evidence.memPercent }),\n  }\n}\n\n/**\n * 历史视图 → 工具输出形状。\n *\n * 两处压缩都是**有意的**：\n *   - 样本最多 10 条（再多模型也读不动，而 `trend` 已经把结论给出来了）；\n *   - `null` 字段省略（工具 schema 没有 null 类型，见 `toToolEvidence` 的同款说明）。\n */\nfunction toToolHistory(history: DiagnosisHistoryView): ToolDiagnosisHistory {\n  return {\n    samples: history.samples.slice(-10).map((sample) => ({\n      at: sample.at,\n      severity: sample.severity,\n      code: sample.code,\n      findings: sample.findings,\n      ...(sample.restartCount === null ? {} : { restartCount: sample.restartCount }),\n      ...(sample.memPercent === null ? {} : { memPercent: sample.memPercent }),\n      ...(sample.errorLines === null ? {} : { errorLines: sample.errorLines }),\n    })),\n    trend: {\n      count: history.trend.count,\n      ...(history.trend.window === null ? {} : { window: history.trend.window }),\n      verdict: history.trend.verdict,\n      numbers: history.trend.numbers,\n      newFindings: history.trend.newFindings,\n      resolvedFindings: history.trend.resolvedFindings,\n      aggravating: history.trend.aggravating,\n    },\n    recorded: history.recorded,\n  }\n}\n\ninterface ToolImageRow {\n  reference: string\n  sizeText: string\n  createdSince?: string\n  id: string\n}\n\ninterface ToolNetworkRow {\n  name: string\n  driver: string\n  scope: string\n  internal?: boolean\n  id: string\n}\n\ninterface ToolVolumeRow {\n  name: string\n  driver: string\n  scope: string\n  mountpoint?: string\n}\n\ninterface ToolImageDetailRow {\n  target: string\n  ref: string\n  detail: string\n}\n\ninterface ToolImagePullRow {\n  target: string\n  ref: string\n  code?: number\n  text: string\n  truncated?: boolean\n}\n\ninterface ToolExecRow {\n  target: string\n  id: string\n  code?: number\n  stdout: string\n  stderr: string\n  truncated?: boolean\n}\n\n/* ------------------------------------------------------------------ *\n * 列表分页（docker_ps / docker_images / docker_networks / docker_volumes 共用口径）\n * ------------------------------------------------------------------ */\n\n/**\n * 一页的默认条数与上限。与 `docker_attention` 的 `limit` **同口径**（1~500 / 默认 100）：\n * 「一页多少条」跨工具必须是同一个数，否则模型每换一个列表工具都要重新试一遍。\n *\n * 为什么在**插件侧**切而不是交给 docker CLI 的 `-n` / `--filter`：`listContainers` /\n * `images` / `networks` / `volumes` 的返回契约是「该目标的完整列表」（面板、详情页、公告\n * 都依赖它），在这里切不改那条契约。也**不解决**单条命令 512KB（`maxOutputKb`）的物理\n * 上限——超了照旧抛错（见 `assertComplete`）；分页解决的是「结果长到模型读不下去」。\n */\nconst PAGE_DEFAULT_LIMIT = 100\nconst PAGE_MAX_LIMIT = 500\n\n/** 归一化后的分页窗口（`limit` 夹在 1~PAGE_MAX_LIMIT，`offset` 非负）。 */\ninterface PageWindow {\n  limit: number\n  offset: number\n}\n\n/**\n * 分页参数的**唯一**归一化点：缺省 / 非整数落到默认值，越界**夹紧**而不是报错\n * （参数 DSL 没有 minimum/maximum，夹紧是这里唯一能保证的语义）。\n */\nfunction pageWindow(input: { limit?: unknown; offset?: unknown }): PageWindow {\n  const limit = typeof input.limit === 'number' && Number.isInteger(input.limit)\n    ? Math.min(Math.max(input.limit, 1), PAGE_MAX_LIMIT)\n    : PAGE_DEFAULT_LIMIT\n  const offset = typeof input.offset === 'number' && Number.isInteger(input.offset) && input.offset > 0\n    ? input.offset\n    : 0\n  return { limit, offset }\n}\n\n/** 切页结果：`total` 是**切之前**的总数，`truncated` 表示后面还有没返回的条目。 */\ninterface PagedRows<T> {\n  rows: T[]\n  total: number\n  truncated: boolean\n}\n\n/** 切页的**唯一**实现：`total > offset + limit` 就是「还有下一页」（与 render 的提示同源）。 */\nfunction paginate<T>(rows: T[], window: PageWindow): PagedRows<T> {\n  const total = rows.length\n  return {\n    rows: rows.slice(window.offset, window.offset + window.limit),\n    total,\n    truncated: total > window.offset + window.limit,\n  }\n}\n\n/** 分页参数的注册表（四条列表共用；与 `docker_attention` 的 limit 描述同款口径）。 */\nconst pageParams = {\n  limit: { type: 'number', description: '本页最多返回多少条（1~500，默认 100）' },\n  offset: { type: 'number', description: '跳过前多少条（默认 0）；翻页时传上一页提示里给出的 offset' },\n} as const\n\n/** render 侧的分页上下文：头部「共 N / 本页 M」、空页成因、下一跳 offset 都从这里取。 */\ninterface ListPage {\n  total: number\n  offset: number\n  truncated: boolean\n}\n\n/**\n * 由返回值 + **入参**拼出 render 用的分页上下文。\n *\n * offset 读的是入参（`execute` 已经用同一个 `pageWindow` 归一化过一遍）——这里只读不写，\n * 也不新增第二个「当前页从哪开始」的真相源。\n */\nfunction listPage(args: unknown, total: number | undefined, truncated: boolean): ListPage | undefined {\n  if (total === undefined) return undefined\n  const { offset } = pageWindow((args ?? {}) as { limit?: unknown; offset?: unknown })\n  return { total, offset, truncated }\n}\n\n/**\n * 「怎么拿更多」的**唯一**话术（四条列表 render 共用）：只在真的还有下一页时出现。\n *\n * 给的是调用方**下一次调用就能用**的参数。不要写成「请调大 maxOutputKb」——agent 改不了\n * 插件设置，这种话术等于把问题丢回给它自己（D105 的判据在这里同样成立）。\n */\nfunction pagingNote(page: ListPage | undefined, shown: number): string {\n  if (page === undefined || page.truncated !== true || page.total <= shown) return ''\n  return `\\n\\n共 ${String(page.total)} 条，本页显示 ${String(shown)} 条：继续用 \\`offset=${String(page.offset + shown)}\\`，或加 \\`limit\\`（上限 ${String(PAGE_MAX_LIMIT)}）`\n}\n\n/** 列表头：分页时同时给「共 N 个」与「本页 M 个」——只报一页的条数会被当成全部。 */\nfunction listHead(noun: string, target: string, page: ListPage | undefined, shown: number): string {\n  return page !== undefined && page.total !== shown\n    ? `目标 ${target} 的${noun}（共 ${String(page.total)} 个，本页 ${String(shown)} 个）：`\n    : `目标 ${target} 的${noun}（${String(shown)} 个）：`\n}\n\n/**\n * 空页的两种成因必须分得开：真的没有条目，还是 `offset` 越过了末页。\n * 后者不说清楚，模型会把「翻过头了」当成「这台机器上没有镜像」——D12/D42 那类假阴性。\n */\nfunction emptyListText(noun: string, target: string, page: ListPage | undefined): string {\n  if (page !== undefined && page.total > 0 && page.offset > 0) {\n    return `目标 ${target} 的${noun}共 ${String(page.total)} 个，offset=${String(page.offset)} 已越过末页（改用更小的 offset 重试）。`\n  }\n  return `目标 ${target}：没有${noun}。`\n}\n\n/* ------------------------------------------------------------------ *\n * 常量\n * ------------------------------------------------------------------ */\n\nconst ROUTE_PREFIX = '/api/dsh-docker'\nconst BODY_LIMIT = 1024 * 1024\n\n/** 变更类子路由（D32）：要求同源证明（Origin 或 Sec-Fetch-Site: same-origin）。 */\nconst MUTATION_SUBROUTES = new Set([\n  '/action',\n  '/images/remove',\n  '/images/prune',\n  '/networks/remove',\n  '/networks/prune',\n  '/volumes/remove',\n  '/volumes/prune',\n  '/exec',\n  /*\n   * 就地提权三条（判定条件是**精确子路径** + POST，所以必须逐条列；只写 '/elevate' 的话\n   * /elevate/status 与 /elevate/revoke 就是裸奔的——跨站页面能撤销授权、能对着确认码试错）。\n   */\n  '/elevate',\n  '/elevate/status',\n  '/elevate/revoke',\n  /*\n   * 一键连接本机（POST /connect-local）：它**会写插件配置**（加一个本机目标），\n   * 与其它写路径同一档，必须带同源证明——跨站页面不该有权替用户改目标列表。\n   * 注意它**不**在能力开关（allowMutations / allowExec）里：见 connectLocal 的注释。\n   * 客户端只在「一个目标都没有」的空态里给入口，但路由本身与调用方无关（agent 工具\n   * 在任何时候都能调），所以这条守卫不能省。\n   */\n  '/connect-local',\n])\n\n/** 「这条错误来自目标侧」的标记（见 guardTargetFailures）。 */\nconst TARGET_FAILURE = Symbol('dsh-docker.target-failure')\n\n/**\n * 给 `DockerApi` 包一层：**只有**从目标 API 抛出的错误才打上 `TARGET_FAILURE` 标记。\n *\n * 为什么需要这个标记：单目标数据路由原来是「api 抛什么，外层 catch 就统一回 500」。\n * 而 SSH 连不上 / 私钥读不到 / docker 不在 PATH 这些都是**运维状况**，不是插件 bug——\n * 多目标聚合路径对同一件事早就回 200 + `ok:false`（`aggregateAcrossTargets` 把 `run()`\n * 的抛错收成每个目标一条 `ok:false`）。于是同一句 `EPERM: open '…id_ed25519'` 在\n * `target='*'` 下是「可读原因」、在单目标下是「不透明 500」：面板点一个连不上的目标就长这样。\n *\n * 为什么不逐个调用点包 try/catch：那要改 20 处，而且**必然漏几个**——本仓「修到一半」\n * 的老毛病（D80–D125 那批 29 条）。包一次就没有漏网之鱼。\n *\n * 为什么不是「把外层 catch 全改成 200 + ok:false」：那会把我们自己的 bug（比如某天\n * 解析写错抛的 TypeError）也伪装成「目标不可达」，正是本仓最忌讳的**静默错误结果**。\n * 打标记之后，没标记的错误仍旧 500。\n */\nfunction guardTargetFailures<T extends object>(api: T): T {\n  return new Proxy(api, {\n    get(target, prop, receiver) {\n      const value: unknown = Reflect.get(target, prop, receiver)\n      if (typeof value !== 'function') return value\n      return async (...args: unknown[]): Promise<unknown> => {\n        try {\n          return await (value as (...rest: unknown[]) => Promise<unknown>).apply(target, args)\n        } catch (error) {\n          if (error !== null && typeof error === 'object') {\n            Object.defineProperty(error, TARGET_FAILURE, { value: true, configurable: true })\n          }\n          throw error\n        }\n      }\n    },\n  })\n}\n\n/** 这条错误是不是从目标 API 抛出来的（见 guardTargetFailures）。 */\nfunction isTargetFailure(error: unknown): boolean {\n  return error !== null && typeof error === 'object' && (error as Record<symbol, unknown>)[TARGET_FAILURE] === true\n}\n\n/**\n * agent 公告：只留**能力索引 + 安全契约**（空态出路 / 能力开关 / 两条 exec 通道的边界 /\n * root 权限警示）。\n *\n * 剩下的事实在别处各有一份，**不要再写回来**（2026-10-25 从 562 压到 250 字符时删的三段）：\n *   - 「`*`（全部目标）只有 `docker_ps` / `docker_attention` 支持」——两条工具自己的\n *     `description` 里各写了一遍（`docker_ps`「target 传 `*` = 一次列出所有目标」、\n *     `docker_attention`「target 传 `*` 时跨所有目标聚合」）；`targetParam` 与运行期报错\n *     也各有一份。\n *   - 排障顺序（`docker_attention` → `docker_ps` → `docker_logs` → 尾部看不到成因再\n *     `docker_logs_grep` → `docker_inspect` / `docker_stats`）——散在各工具 `description` 里\n *     （「排障入口」/「排障第一步」/「改用 docker_logs_grep」），挨着要用的那个工具读才有用。\n *   - 网络 / 卷的增删只在面板——插件压根没有给这两个工具，模型做不了，写了也只是噪音。\n *   这三条的「仍在别处」由 `test/announcement.test.ts` 反向钉住：工具描述被精简掉就红。\n *   长度预算归 `scripts/test/announcement-budget.test.ts` 那份名单（docker 公告并入其中），\n *   本文件不再自带一条长度判据。\n *\n * ⚠️ **「允许 exec」只管本插件的一次性通道**（D163）。面板「终端」按钮跑的是\n * `docker exec -it` 交互式 shell——它经 tty 的 `ttyTerminal` 承载、**不检查 `allowExec`**\n * （`client-src/index.js` 的 `openExec` 里没有任何该判断，只读模式下也照常可用），所以这句话\n * 一旦退回「…docker exec，都需要…才有对应工具与按钮」的笼统说法，就是在**声称一条不成立的\n * 安全性质**（2026-10-07 用户正是照着旧措辞问「这算是漏洞吗」）。守卫：\n * `scripts/test/exec-terminal-scope.test.ts`（含「退回旧措辞必须变红」的反例）。\n *\n * ⚠️ **零目标时注册面只剩两条工具**（`ZERO_TARGET_TOOLS`），公告必须给出那条出路：\n * 否则 `docker_targets` 描述里「其他 docker_* 工具的 target 参数取自这里」指向的是一批\n * **此刻并不存在**的工具，模型只能原地打转。守卫：`test/announcement.test.ts`\n * （含「删掉那句必须变红」的反例）。\n */\nconst DOCKER_GUIDANCE =\n  '本机装有 dsh-docker 插件（侧栏「容器」）。**默认只读**：启停删容器、镜像删除/清理/拉取、**一次性** docker exec（本插件），都需要用户在设置里打开「允许变更操作」「允许 exec」；「允许 exec」只管这条一次性通道——面板「终端」按钮的 exec -it 由 tty 承载、**不受它门控**。**一个目标都没有时先 `docker_connect_local` 加上本机目标**。docker socket 等价目标主机 root 权限，用户没明确要求别做变更。'\n\n/* ------------------------------------------------------------------ *\n * 工具函数\n * ------------------------------------------------------------------ */\n\ninterface ReqLike {\n  method?: string\n  url?: string\n  headers: Record<string, string | string[] | undefined>\n  socket: { remoteAddress?: string | undefined }\n}\n\ninterface ResLike {\n  writeHead(status: number, headers?: Record<string, string>): void\n  end(body?: string | Uint8Array): void\n  /*\n   * SSE 长连接的最小扩展面（结构化类型，不 import node:http）：宿主 webServer\n   * 直接把原生 ServerResponse 交给 handler，这些方法天然存在；可选是为了让\n   * 既有 JSON 路由与离线冒烟的极简假 res 不必全部实现。\n   */\n  write?(chunk: string): boolean | void\n  flushHeaders?(): void\n  on?(event: 'close' | 'drain', listener: () => void): void\n}\n\n/**\n * SSE 帧封装：data 一律 `JSON.stringify` 成**单行**——换行 / 引号被转义，\n * 多字节字符也不会被 SSE 的 `\\n` 行边界截断（客户端 JSON.parse 还原）。\n */\nexport function sseFrame(event: string, data: unknown): string {\n  return `event: ${event}\\ndata: ${JSON.stringify(data)}\\n\\n`\n}\n\n/** SSE 心跳间隔（毫秒）：注释帧只保活，客户端 EventSource 会忽略。 */\nconst SSE_HEARTBEAT_MS = 15_000\n\n/** 日志 / 拉取流的分片合帧窗口（毫秒）。低一个数量级的渲染合帧是 150ms，用户看不见。 */\nconst SSE_COALESCE_MS = 50\n/** 单个通道攒到这个字节数就立刻推一帧：不让一个大 chunk 在窗口里多等一个周期。 */\nconst SSE_COALESCE_MAX_BYTES = 256 * 1024\n\n/**\n * 一条日志流最多能带多少个源（`ids=` 的**防御性上限**）。\n *\n * 每个源都是**一条真的 `docker logs -f`**：本机一个子进程、SSH 一条 channel，外加\n * 各自的合帧缓冲。而 `ids` 来自 URL，是客户端可控的量——不设上限时拼一千个条目就能\n * 让宿主一口气起一千个进程（这条流是只读能力，不该成为放大攻击的入口）。32 远高于\n * 「一个 Compose 项目全选」的实际需要，正常视图碰不到它。\n */\nconst MAX_LOGS_SOURCES = 32\n\n/** 合帧器句柄（生命周期：`flush()` 收尾、`dispose()` 停表）。 */\nexport interface SseCoalescer {\n  /** 追加一个分片：窗口到点（或攒满 maxBytes）时按通道合并成一帧推出去。 */\n  push(channel: 'd' | 'e', text: string): void\n  /** 立刻把两个通道里攒着的分片推出去（顺序：stdout 先、stderr 后）。 */\n  flush(): void\n  /** 停掉定时器并丢掉残帧（客户端已走 / 流已收尾，再推只会写进关掉的响应）。 */\n  dispose(): void\n}\n\n/**\n * SSE 分片合帧器（D151）：把「一个 stdout chunk 一帧」压成「一个窗口一帧」。\n *\n * 为什么要有它：`docker logs -f` / `docker pull` 的分片大小由上游决定，话痨容器\n * （未缓冲 stdout、逐行 flush 的应用）能到每秒几千个 chunk，而每个 chunk 在链路上\n * 的固定成本并不小——服务端一次 `JSON.stringify` + 一次 `res.write`，客户端一次\n * SSE 事件派发 + 一次 `JSON.parse` + 一次 `pushChunk`（字符串拼接 + 扫描换行）。\n * 这些成本与「一行日志多少个字节」无关，只与**事件个数**成正比。\n *\n * 实测（scripts/log-perf.mjs 的事件洪泛剖面，同一行速率 6.2k 行/秒）：每事件 1 行\n * 时事件循环最大延迟 53ms、出现 1 个 >50ms 的长帧；每事件 50 行时 37ms、0 个。\n * 差距在事件率再高一个数量级时会继续放大（浏览器真实 SSE 解析比冒烟桩更贵）。\n *\n * 语义约束（客户端按到达序落行，合帧不能改变「看到的内容」）：\n *   - 同一通道内部**严格保序**（就是字符串拼接）；\n *   - 两个通道各攒各的，一帧最多推 `d` 一条 + `e` 一条——`docker logs` 的 stdout /\n *     stderr 本就是两路，跨通道的先后从来不由单帧保证；\n *   - 收尾前调用方必须 `flush()`：`end` 帧得排在这些 `line` 帧之后（见调用点）。\n */\nexport function createSseCoalescer(options: {\n  emit: (channel: 'd' | 'e', text: string) => void\n  windowMs?: number\n  maxBytes?: number\n}): SseCoalescer {\n  const windowMs = typeof options.windowMs === 'number' && options.windowMs > 0 ? options.windowMs : SSE_COALESCE_MS\n  const maxBytes = typeof options.maxBytes === 'number' && options.maxBytes > 0 ? options.maxBytes : SSE_COALESCE_MAX_BYTES\n  let stdout = ''\n  let stderr = ''\n  let timer: NodeJS.Timeout | null = null\n\n  const stopTimer = (): void => {\n    if (timer === null) return\n    clearTimeout(timer)\n    timer = null\n  }\n\n  const flush = (): void => {\n    stopTimer()\n    if (stdout !== '') {\n      const text = stdout\n      stdout = ''\n      options.emit('d', text)\n    }\n    if (stderr !== '') {\n      const text = stderr\n      stderr = ''\n      options.emit('e', text)\n    }\n  }\n\n  return {\n    push(channel, text) {\n      if (typeof text !== 'string' || text === '') return\n      if (channel === 'd') stdout += text\n      else stderr += text\n      // 攒满一个上限就立刻推：超大 chunk（整段 JSON / base64）不该在窗口里多等一拍\n      if ((channel === 'd' ? stdout : stderr).length >= maxBytes) {\n        flush()\n        return\n      }\n      if (timer === null) timer = setTimeout(flush, windowMs)\n    },\n    flush,\n    dispose() {\n      stopTimer()\n      stdout = ''\n      stderr = ''\n    },\n  }\n}\n\n/*\n * 回环围栏与同源证明：**实现已收敛到 `@hyzyn/dsh-kit`**（2026-09-25，项目级 ROADMAP\n * 第 1 项）。本包是那段加固档的来源，行为一字未改；D31 / D32 / D80 / D110 / D139 五条\n * 的成因、时序约束与桌面版例外随实现一起搬到了 `packages/kit/src/http.ts`——**那边的\n * 注释是唯一归宿**，这里只留指针（否则又是「三处各写一份必然漂」）。\n */\n\n\nfunction writeJson(res: ResLike, status: number, body: unknown): void {\n  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'referrer-policy': 'no-referrer' })\n  res.end(JSON.stringify(body))\n}\n\n/** 读取并解析 JSON 请求体；超限/非对象/非法 JSON 返回 undefined。 */\nasync function readJsonBody(req: AsyncIterable<Uint8Array>): Promise<Record<string, unknown> | undefined> {\n  const chunks: Buffer[] = []\n  let size = 0\n  for await (const chunk of req) {\n    size += chunk.byteLength\n    if (size > BODY_LIMIT) return undefined\n    chunks.push(Buffer.from(chunk))\n  }\n  if (size === 0) return {}\n  try {\n    const parsed: unknown = JSON.parse(Buffer.concat(chunks).toString('utf8'))\n    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) return undefined\n    return parsed as Record<string, unknown>\n  } catch {\n    return undefined\n  }\n}\n\n/** 清洗一份 targets 输入（settings 存储 / 热更新路径共用）。 */\nexport function sanitizeTargets(input: unknown): DockerTarget[] | undefined {\n  if (!Array.isArray(input)) return undefined\n  const out: DockerTarget[] = []\n  const seen = new Set<string>()\n  for (const raw of input) {\n    if (typeof raw !== 'object' || raw === null) continue\n    const item = raw as Record<string, unknown>\n    const name = typeof item.name === 'string' ? item.name.trim() : ''\n    if (name === '' || name.length > 64 || seen.has(name)) continue\n    const kind = item.kind === 'ssh' ? 'ssh' : 'local'\n    const port = typeof item.port === 'number' && Number.isInteger(item.port) && item.port >= 1 && item.port <= 65535 ? item.port : 22\n    const auth = item.auth === 'key' || item.auth === 'password' ? item.auth : 'agent'\n    seen.add(name)\n    out.push({\n      name,\n      kind,\n      book: typeof item.book === 'string' ? item.book.trim() : '',\n      host: typeof item.host === 'string' ? item.host.trim() : '',\n      port,\n      username: typeof item.username === 'string' ? item.username.trim() : '',\n      auth,\n      keyPath: typeof item.keyPath === 'string' ? item.keyPath.trim() : '',\n      password: typeof item.password === 'string' ? item.password : '',\n      passphrase: typeof item.passphrase === 'string' ? item.passphrase : '',\n      agentForward: item.agentForward === true,\n    })\n  }\n  return out\n}\n\n/** 一键连接本机时新建目标的基准名。刻意用稳定的小写 `local`（不是 `本机`）：它是可预测的 id，重名时另起 `local-2`…。 */\nexport const LOCAL_TARGET_NAME = 'local'\n\n/** 目标列表里第一个 `kind=local` 的名称（没有则 undefined）——「连接本机」靠它判断该新建还是复用。 */\nexport function findLocalTargetName(targets: readonly DockerTarget[]): string | undefined {\n  return targets.find((item) => item.kind === 'local')?.name\n}\n\n/**\n * 新建本机目标时挑一个**确定性无冲突**的名称：`local` 被占就顺着 `local-2`、`local-3`… 找第一个空位。\n *\n * 为什么不做随机 / 时间戳后缀：同一个工作区里重复点「连接本机」应当**幂等**（第二次复用第一次那条），\n * 而重名只可能来自用户自己配的其它 `local*`；顺序探测既确定又与用户已有的名字不冲突（不覆盖、不改名）。\n * 上界 1000 是防御性截断（真到那时说明列表已经病态，宁可失败也不能无限循环）。\n */\nexport function nextLocalTargetName(taken: readonly string[]): string | undefined {\n  const used = new Set(taken)\n  if (!used.has(LOCAL_TARGET_NAME)) return LOCAL_TARGET_NAME\n  for (let index = 2; index <= 1000; index += 1) {\n    const candidate = `${LOCAL_TARGET_NAME}-${String(index)}`\n    if (!used.has(candidate)) return candidate\n  }\n  return undefined\n}\n\n/**\n * 「探不到 CLI」的判据（`runLocal` 的 ENOENT 抛错形态）。\n *\n * 抽出来当单一来源：文案分档与「要不要去找 podman」都用它，两处各写一遍正则\n * 迟早会漂移——那时会出现「文案说 CLI 缺失、但不去找候选」或反过来。\n */\nexport function isLocalCliMissing(raw: string): boolean {\n  return /ENOENT|not recognized as an internal|command not found/i.test(raw)\n}\n\n/** 本机容器 CLI 的候选（除 `dockerBin` 自己之外）：按这个顺序找第一个存在的。 */\nconst LOCAL_CLI_ALTERNATIVES = ['docker', 'podman', 'nerdctl'] as const\n\n/**\n * 在 PATH 里找**别的**容器 CLI（`dockerBin` 缺失时的候选），返回名字数组（可能为空）。\n *\n * 只读探测，**绝不改配置**：返回的候选交给文案去说「你可以把 docker CLI 改成它」，\n * 改不改由用户在设置卡片决定。静默改写 `dockerBin` 会违背本插件「不替用户决定」的\n * 一贯取向（何况 podman 与本插件的输出格式兼容性并未逐项验证，见 README）。\n *\n * `env` 可注入（测试用）；Windows 按 PATHEXT 补扩展名——本插件明确支持 Windows\n * 盘符路径，不能只认无扩展名的 POSIX 查找。\n */\nexport function findAlternativeLocalCli(bin: string, env: NodeJS.ProcessEnv = process.env): string[] {\n  const dirs = (env.PATH ?? '').split(delimiter).filter((item) => item !== '')\n  const win = process.platform === 'win32'\n  const exts = win ? (env.PATHEXT ?? '.COM;.EXE;.BAT;.CMD').split(';').filter((item) => item !== '') : ['']\n  /*\n   * 比的是**工具名**（basename，Windows 再去掉扩展名），不是配置里的原字符串：\n   * `dockerBin` 常写成绝对路径（`/usr/local/bin/docker`），拿它直接比对候选名会\n   * 把「同一个 docker」当成可切换的候选，给出「把 docker CLI 改成 docker」这种废话。\n   */\n  const stem = (value: string): string => {\n    const base = basename(value).toLowerCase()\n    return win ? base.replace(/\\.[^.]+$/, '') : base\n  }\n  const self = stem(bin)\n  const found: string[] = []\n  for (const candidate of LOCAL_CLI_ALTERNATIVES) {\n    if (candidate === self) continue\n    const dir = dirs.find((item) => exts.some((ext) => {\n      try {\n        accessSync(join(item, candidate + ext), constants.X_OK)\n        return true\n      } catch {\n        return false\n      }\n    }))\n    if (dir !== undefined) found.push(candidate)\n  }\n  return found\n}\n\n/**\n * 只读探测失败 → 用户能照着做的一句话。按**成因**分档（而不是原样甩 `exit status 1`）：\n * CLI 不在（装 Docker / 改 `dockerBin`）、超时（daemon 卡死 / context 指错）、\n * daemon 不可达、socket 无权、其它（原样透出）。\n *\n * `probe()` 的两条失败路径形状不同：`runLocal` 对 ENOENT 是**抛错**（`无法执行 docker：spawn docker ENOENT`），\n * 而 daemon 连不上是 docker CLI 自己以非零退出 + stderr 文案返回；两条都要认得出。\n */\nexport function describeLocalProbeFailure(raw: string, bin = 'docker', hint: LocalProbeHint = {}): string {\n  const text = raw.trim()\n  if (isLocalCliMissing(text)) {\n    const head = `宿主上找不到 docker CLI（${bin}）：请先安装 Docker，或在设置卡片把「docker CLI」改成正确的可执行文件路径`\n    // 有候选就点出来——只说「请先安装 Docker」会让 podman 用户以为要装一整套 Docker。\n    // 同时写明**面板不会替你改**：这是提示，不是自动切换（见 findAlternativeLocalCli）。\n    return hint.alternativeCli === undefined || hint.alternativeCli === ''\n      ? head\n      : `${head}。这台机器上装了 ${hint.alternativeCli}：把「docker CLI」填成 ${hint.alternativeCli} 就能用（面板不会替你改）`\n  }\n  /*\n   * 超时单独一档（D159）：它和「daemon 没起」的可修动作完全不同，也不能落进下面\n   * 那句「退出码 null」。判据来自 `ProbeResult.timedOut` 而不是解析文案——CLI 的\n   * 超时输出里根本没有可认的字样。\n   */\n  if (hint.timedOut === true) {\n    return `${bin} version 15 秒没返回：daemon 可能卡死，或 docker context 指向了连不上的远端（用 docker context ls 看当前指向；Docker Desktop 卡死时重启它）`\n  }\n  if (/ECONNREFUSED|ENOENT.*\\.sock|\\.sock.*(no such file|不是目录|No such)/i.test(text)) {\n    return `docker CLI 可用，但连不上 docker daemon：请确认 daemon 已启动（Linux: systemctl start docker；macOS/Windows: 启动 Docker Desktop）`\n  }\n  if (/permission denied/i.test(text)) {\n    return `docker CLI 可用，但当前账号无权访问 docker socket：把运行宿主的账号加入 docker 组，或改用允许的 socket`\n  }\n  if (/Is the docker daemon running|Cannot connect to the Docker daemon|error during connect/i.test(text)) {\n    return `docker CLI 可用，但连不上 docker daemon：请确认 daemon 已启动（Linux: systemctl start docker；macOS/Windows: 启动 Docker Desktop）`\n  }\n  return `docker daemon 探测失败：${text === '' ? 'docker version 没有返回任何信息' : text}`\n}\n\n/**\n * 清洗一份 hostKeys 输入（settings 存储 / 热更新 / 种子复制共用）。\n *\n * 同时接受两种形状（D03）：\n *   - tty 0.19.0+ 的 `{host, port, fingerprints: [...]}`（多指纹集合）；\n *   - docker 0.6.x 自己落盘的 `{host, port, fingerprint}`（迁移输入）。\n * host 统一 trim + 小写（与 tty 的落盘口径一致，否则种子命中与否取决于大小写），\n * 同一 host:port 的多条记录合并成一组指纹。\n */\nexport function sanitizeHostKeys(input: unknown): HostKeyRecord[] | undefined {\n  if (!Array.isArray(input)) return undefined\n  const byKey = new Map<string, HostKeyRecord>()\n  for (const raw of input) {\n    if (typeof raw !== 'object' || raw === null) continue\n    const item = raw as Record<string, unknown>\n    const host = typeof item.host === 'string' ? item.host.trim().toLowerCase() : ''\n    const port = typeof item.port === 'number' && Number.isInteger(item.port) && item.port >= 1 && item.port <= 65535 ? item.port : 22\n    const list = Array.isArray(item.fingerprints) ? item.fingerprints : []\n    const single = typeof item.fingerprint === 'string' && item.fingerprint.trim() !== '' ? [item.fingerprint.trim()] : []\n    const fingerprints = [...new Set([\n      ...list.filter((fp): fp is string => typeof fp === 'string' && fp.trim() !== '').map((fp) => fp.trim()),\n      ...single,\n    ])]\n    if (host === '' || fingerprints.length === 0) continue\n    const key = `${host}:${String(port)}`\n    const existing = byKey.get(key)\n    if (existing !== undefined) {\n      existing.fingerprints = [...new Set([...existing.fingerprints, ...fingerprints])]\n      continue\n    }\n    byKey.set(key, { host, port, fingerprints })\n  }\n  return [...byKey.values()]\n}\n\n/**\n * hostKeys **并集**合并（D10）：客户端表单快照回传的表不得整表覆盖 TOFU 运行期\n * 新增的记录——面板一次无关保存就把钉扎回退掉，指纹变更检测随之失效。按\n * host:port 合并指纹集合；删除某条记录走显式的 `hostKeysRemove`。\n */\nexport function mergeHostKeys(base: HostKeyRecord[], incoming: unknown): HostKeyRecord[] {\n  const byKey = new Map<string, HostKeyRecord>()\n  for (const record of base) {\n    byKey.set(`${record.host}:${String(record.port)}`, { host: record.host, port: record.port, fingerprints: [...record.fingerprints] })\n  }\n  for (const record of sanitizeHostKeys(incoming) ?? []) {\n    const key = `${record.host}:${String(record.port)}`\n    const existing = byKey.get(key)\n    if (existing === undefined) {\n      byKey.set(key, { host: record.host, port: record.port, fingerprints: [...record.fingerprints] })\n      continue\n    }\n    existing.fingerprints = [...new Set([...existing.fingerprints, ...record.fingerprints])]\n  }\n  return [...byKey.values()]\n}\n\n/**\n * 合并凭证：配置卡片从不回显密码 / 口令（只回 passwordSet），因此浏览器提交的\n * targets 里往往**没有** password/passphrase 字段。按目标名把已有值补回来，\n * 避免「改个名字就把密码清了」。（显式传空字符串仍然按清空处理。）\n *\n * 改名的目标按**连接身份**（book / host / port / username / auth / keyPath）认领\n * 旧凭证（D15）：只按名字找的话，改名 = 凭证凭空消失。身份对不上就不继承——\n * 「删一个目标、另建一个无关目标」不应该串密码，宁缺勿错。\n */\nexport function mergeTargetSecrets(prev: DockerTarget[], incoming: unknown): unknown {\n  if (!Array.isArray(incoming)) return incoming\n  const incomingNames = new Set<string>()\n  for (const raw of incoming) {\n    if (typeof raw !== 'object' || raw === null) continue\n    const name = (raw as Record<string, unknown>).name\n    if (typeof name === 'string' && name.trim() !== '') incomingNames.add(name.trim())\n  }\n  // 名字没出现在新表里的旧目标 = 改名 / 删除的候选\n  const renamed = prev.filter((target) => !incomingNames.has(target.name))\n  return incoming.map((raw) => {\n    if (typeof raw !== 'object' || raw === null) return raw\n    const item = raw as Record<string, unknown>\n    const name = typeof item.name === 'string' ? item.name.trim() : ''\n    let before = prev.find((target) => target.name === name)\n    if (before === undefined && renamed.length > 0) {\n      const book = typeof item.book === 'string' ? item.book.trim() : ''\n      const host = typeof item.host === 'string' ? item.host.trim() : ''\n      const username = typeof item.username === 'string' ? item.username.trim() : ''\n      const keyPath = typeof item.keyPath === 'string' ? item.keyPath.trim() : ''\n      const auth = item.auth === 'key' || item.auth === 'password' ? item.auth : 'agent'\n      const port = typeof item.port === 'number' && Number.isInteger(item.port) ? item.port : 22\n      before = renamed.find((target) =>\n        (target.book ?? '') === book\n        && target.host === host\n        && (target.port ?? 22) === port\n        && target.username === username\n        && (target.auth ?? 'agent') === auth\n        && target.keyPath === keyPath)\n    }\n    if (before === undefined) return item\n    const next: Record<string, unknown> = { ...item }\n    if (typeof next.password !== 'string') next.password = before.password ?? ''\n    if (typeof next.passphrase !== 'string') next.passphrase = before.passphrase ?? ''\n    return next\n  })\n}\n\n/**\n * 两条能力开关的宿主侧授权（见 kit 的 capability.js 与 docs/architecture.md）。\n *\n * 两条提权通道：**启动环境变量**（最严，见 kit 的 capability.ts）与**就地提权**（页内点开关 →\n * 在宿主上落地一个随机名文件 → 免重启生效，见 kit 的 elevation.ts）。HTTP 侧不能凭空打开它们——\n * 回环围栏与同源证明都拦不住跨站页面与页内脚本（它们能自己填 `Sec-Fetch-Site: same-origin`，\n * 那是请求头不是凭据），而 docker socket 等价目标主机 root。\n */\nconst CAP_MUTATIONS = { env: 'DSH_DOCKER_ALLOW_MUTATIONS', label: '变更操作' } as const\nconst CAP_EXEC = { env: 'DSH_DOCKER_ALLOW_EXEC', label: 'exec' } as const\n\n/**\n * 客户端/HTTP 用的能力名 → 授权说明。**白名单**：不在表里的一律 400。\n *\n * 为什么要这张表：路由收到的 `capability` 是外部字符串，直接拿它当环境变量名去查授权存储，等于让\n * 请求方决定「查哪个键」——今天查不出问题（存储里只有这两个键），明天就是一类越权。\n */\nconst CAPABILITIES = new Map<string, { env: string; label: string }>([\n  ['allowMutations', CAP_MUTATIONS],\n  ['allowExec', CAP_EXEC],\n])\n\n/**\n * 零目标时仍然注册的工具——**空态的唯一出路**。\n *\n * 其余每个工具都必须寻址到一个目标（省略 `target` 时回落「唯一目标」，多目标则必填），\n * 一条目标都没有时它们注册了也只会让模型白试一次、拿到「尚未配置任何 Docker 目标」再\n * 回头调 `docker_targets`；而这两条正是让空态可解释、可自救的入口：一条看有哪些目标，\n * 一条一键加本机。名单之外的 `add()` 在 `live.targets` 为空时直接跳过（见 refreshTools），\n * 配好目标后由 applySection 按目标变化**补注册**，不需要重启。\n */\nconst ZERO_TARGET_TOOLS: ReadonlySet<string> = new Set(['docker_targets', 'docker_connect_local'])\n\n/** 未启用时的文案：没授权要说清「怎么授权」，授权了只是没开就说「去开开关」。 */\nfunction mutationsOffMessage(): string {\n  return capabilityGranted(CAP_MUTATIONS)\n    ? '变更操作未启用（插件配置 → Docker 容器面板 → 允许变更操作）'\n    : capabilityDeniedMessage(CAP_MUTATIONS, { inPlace: true })\n}\n\n/** `exec` 那一档的同款文案。 */\nfunction execOffMessage(): string {\n  return capabilityGranted(CAP_EXEC)\n    ? 'exec 未启用（插件配置 → Docker 容器面板 → 允许 exec）'\n    : capabilityDeniedMessage(CAP_EXEC, { inPlace: true })\n}\n\n/** 把一份任意来源的配置归一成 LiveConfig。 */\nexport function normalizeConfig(section: Record<string, unknown>): LiveConfig {\n  const targets = sanitizeTargets(section.targets)\n  const hostKeys = sanitizeHostKeys(section.hostKeys)\n  return {\n    enabled: section.enabled !== false,\n    announceToAgent: section.announceToAgent !== false,\n    dockerBin: assertBin(section.dockerBin),\n    /*\n     * **有效值 = 配置值 && 宿主授权**。折叠在这一处（而不是每个使用点各判一次）的理由：本包\n     * 有二十多处按 `live.allowMutations` 决定「工具注册 / 路由放行 / 面板渲染」，散着判必然\n     * 漏一处——漏掉的那处就是「没授权也能执行」。配置里的 true 不算授权：它与 HTTP 写进去的\n     * 值存在同一个存储里，分不出来源，只认环境变量才是能说清的规则（升级影响见 README）。\n     */\n    allowMutations: section.allowMutations === true && capabilityGranted(CAP_MUTATIONS),\n    allowExec: section.allowExec === true && capabilityGranted(CAP_EXEC),\n    execTimeoutSec: clampInt(section.execTimeoutSec, 1, 120, 30),\n    pollIntervalSec: clampInt(section.pollIntervalSec, 1, 60, 5),\n    logTailDefault: clampInt(section.logTailDefault, 1, 5000, 200),\n    maxOutputKb: clampInt(section.maxOutputKb, 1, 8192, 512),\n    targets: targets ?? [],\n    hostKeys: hostKeys ?? [],\n  }\n}\n\nfunction clampInt(value: unknown, min: number, max: number, fallback: number): number {\n  if (typeof value !== 'number' || !Number.isInteger(value)) return fallback\n  return Math.min(Math.max(value, min), max)\n}\n\n/**\n * 事件时间（Unix 秒）→ 本机时区的 HH:MM:SS（agent 文本输出用）。\n * 只回时间不回日期：事件快照窗口最多几小时，日期对排障没有信息量；\n * 浏览器侧不用这个——那里用 Date 按用户本地时区现算。\n */\nexport function formatEventTime(seconds: number): string {\n  const date = new Date(seconds * 1000)\n  if (Number.isNaN(date.getTime())) return '--:--:--'\n  const pad = (value: number): string => String(value).padStart(2, '0')\n  return `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`\n}\n\n/** 字节 → docker 风格的人类可读大小（十进制单位，与 `docker images` 的 SIZE 一致）。 */\nexport function formatBytes(value: number): string {\n  if (!Number.isFinite(value) || value < 0) return '—'\n  const units = ['B', 'kB', 'MB', 'GB', 'TB']\n  let size = value\n  let unit = 0\n  while (size >= 1000 && unit < units.length - 1) {\n    size /= 1000\n    unit += 1\n  }\n  const text = unit === 0 ? String(Math.round(size)) : size.toFixed(size >= 100 ? 0 : 1)\n  return `${text} ${units[unit] ?? 'B'}`\n}\n\n/** 从 tty 的 entry settings 读取连接簿（只读；tty 未安装时为空表）。 */\n/**\n * 读 tty 连接簿 → 本包的连接规格。**导出仅供单测**（连接簿 → 规格这一跳是「一处配置、两处\n * 生效」的落地处：漏带 jump / proxyCommand 就是「tty 能连、docker 连不上」那种半吊子状态）。\n */\nexport function readTtyBooks(settings: SettingsLookup | undefined): Map<string, SshSpec> {\n  const out = new Map<string, SshSpec>()\n  if (settings === undefined) return out\n  let raw: unknown\n  try {\n    raw = settings.get('tty')\n  } catch {\n    return out\n  }\n  if (typeof raw !== 'object' || raw === null) return out\n  const hosts = (raw as { sshHosts?: unknown }).sshHosts\n  if (!Array.isArray(hosts)) return out\n  for (const entry of hosts) {\n    if (typeof entry !== 'object' || entry === null) continue\n    const item = entry as Record<string, unknown>\n    const name = typeof item.name === 'string' ? item.name.trim() : ''\n    const host = typeof item.host === 'string' ? item.host.trim() : ''\n    const username = typeof item.username === 'string' ? item.username.trim() : ''\n    if (name === '' || host === '' || username === '') continue\n    const spec: SshSpec = {\n      host,\n      port: typeof item.port === 'number' && Number.isInteger(item.port) ? item.port : 22,\n      username,\n      auth: item.auth === 'key' || item.auth === 'password' ? item.auth : 'agent',\n      keyPath: typeof item.keyPath === 'string' ? item.keyPath : '',\n      password: typeof item.password === 'string' ? item.password : '',\n      passphrase: typeof item.passphrase === 'string' ? item.passphrase : '',\n      agentForward: item.agentForward === true,\n    }\n    /*\n     * 跳板机跟着连接簿一起走（本包**不自建跳板机界面**：目标是「一处配置、两处生效」）。\n     * 漏了这一段就是「终端能连、docker 目标连不上」——本项立项时点名的半吊子状态。\n     */\n    const jump = sanitizeJumpSpec(item.jump)\n    if (jump !== undefined) spec.jump = jump\n    /*\n     * 代理命令同理跟着连接簿走（本包**不自建界面**）。闸门不在这里判：它归 tty settings 的\n     * `allowProxyCommand`，由 `readTtyProxyCommandAllowed()` 现读、在**每次拨号**时求值\n     * （见 RemoteExec 的 options.proxyCommandAllowed）——这样用户一关开关就立刻生效。\n     */\n    const proxyCommand = sanitizeProxyCommand(item.proxyCommand)\n    if (proxyCommand !== undefined) spec.proxyCommand = proxyCommand\n    out.set(name, spec)\n  }\n  return out\n}\n\n/**\n * tty 的 ProxyCommand 能力（**与 tty 包同一份规格**，环境变量名必须逐字相同）。\n *\n * 为什么 docker 也要声明它：本包通过连接簿条目拨号时会执行那条 `proxyCommand`，\n * 而「能不能执行代理命令」的闸门只有一处——tty 的能力开关。两包各写一份 env 名会\n * 悄悄分叉（改名只红一侧），所以这里与 `packages/tty/src/index.ts` 的 `CAP_PROXY_COMMAND`\n * 保持一致，由 `packages/docker/test/ssh-proxy-command.test.ts` 钉住。\n */\nconst CAP_PROXY_COMMAND = { env: 'DSH_TTY_ALLOW_PROXY_COMMAND', label: '代理命令（ProxyCommand）' } as const\n\n/**\n * 读 tty settings 里的 ProxyCommand 闸门（`allowProxyCommand`，默认关）。\n *\n * 为什么本包要用 **tty 的**开关而不是自己再加一个：连接簿只有一处（tty），代理命令也只有\n * 一处能填；两个开关会让「连接簿配了、这个面板不认」变成说不清的状态。代价是本包多依赖一个\n * 只读 settings 字段——settings 句柄缺失（启动早期）时恒 false，即**关**（失败方向安全）。\n *\n * **但配置值不等于授权**（2026-10-19 外部测评 issue #13 第 4 条）：tty 侧的闸门是\n * `granted && enabled`（`packages/tty/src/index.ts` 的 `setProxyCommandPolicy`），\n * 而这里原先只读配置值。于是「点过撤销宿主授权 / 升级前在界面里开过 / 手改 settings.yaml」\n * 的机器上，tty 自己拒绝执行，docker 引用同一连接簿条目却照样 `spawn(cmd, {shell:true})`\n * ——同一份连接簿在两个面板里得到两种安全结论，而弱的那一侧能执行任意命令。\n *\n * 现在两边同口径：**宿主授权 && 配置开关**，缺一即关。\n */\nexport function readTtyProxyCommandAllowed(settings: SettingsLookup | undefined): boolean {\n  if (settings === undefined) return false\n  let raw: unknown\n  try {\n    raw = settings.get('tty')\n  } catch {\n    return false\n  }\n  if (typeof raw !== 'object' || raw === null) return false\n  if ((raw as { allowProxyCommand?: unknown }).allowProxyCommand !== true) return false\n  // 配置说开还不够：宿主没授权就是没授权（与 tty 的 granted && enabled 同一判据）\n  return capabilityGranted(CAP_PROXY_COMMAND)\n}\n\n/** 从 tty 的 hostKeys 读取已钉扎指纹（作为本插件 TOFU 的种子）。 */\nfunction readTtyHostKeys(settings: SettingsLookup | undefined): HostKeyRecord[] {\n  if (settings === undefined) return []\n  let raw: unknown\n  try {\n    raw = settings.get('tty')\n  } catch {\n    return []\n  }\n  if (typeof raw !== 'object' || raw === null) return []\n  const keys = (raw as { hostKeys?: unknown }).hostKeys\n  return sanitizeHostKeys(keys) ?? []\n}\n\n/** 把一个配置目标解析成可连接的规格（连接簿查找在此完成）。 */\nexport function resolveTarget(target: DockerTarget, books: Map<string, SshSpec>): { resolved?: ResolvedTarget; error?: string } {\n  if (target.kind === 'local') return { resolved: { name: target.name, kind: 'local' } }\n  if (target.book !== undefined && target.book !== '') {\n    const spec = books.get(target.book)\n    if (spec === undefined) {\n      /*\n       * 指引必须指向**用户真能做的动作**。旧文案说\"请在 tty 终端面板的设置卡片里添加\"——\n       * 但那张卡片管的是 tty 自己的连接簿条目，改不了 docker 目标引用的名字：用户照着找\n       * 只会扑空（实测：目标引用 HS-248、连接簿里只有 HS_248_ADMIN，进 tty 卡片什么也改不了）。\n       * 真正要改的字段是**本卡片这条目标的「连接簿」下拉**，所以先把这里说清楚，再说备选。\n       *\n       * 末句是给「只能经跳板机 / 代理命令访问」那类情况留的出口（项目级 ROADMAP 第 2 项）：\n       * tty 的 ~/.ssh/config 导入会**自动带上 ProxyJump**、但**永不带上 ProxyCommand**，所以\n       * 后者的条目要么不存在、要么存在却没配代理命令——用户看到「条目不存在」时的第一反应\n       * 是「我明明配过」。\n       */\n      return { error: `目标「${target.name}」引用的连接簿条目不存在：${target.book}（在本卡片这条目标的「连接簿」下拉里改选一个已有条目；或把 tty 终端面板的连接簿补一个同名条目；也可清空下拉改为手填 host/username。若该主机在 ~/.ssh/config 里只配了 ProxyCommand，导入会跳过它——那种条目要在 tty 连接簿里手动建，并打开「允许 ProxyCommand」，见项目级 ROADMAP 第 2 项）` }\n    }\n    return { resolved: { name: target.name, kind: 'ssh', spec } }\n  }\n  const host = target.host ?? ''\n  const username = target.username ?? ''\n  if (host === '' || username === '') {\n    return { error: `目标「${target.name}」缺少 SSH 信息：需要 book（连接簿条目名）或 host + username` }\n  }\n  const spec: SshSpec = {\n    host,\n    port: target.port ?? 22,\n    username,\n    auth: target.auth ?? 'agent',\n    keyPath: target.keyPath ?? '',\n    password: target.password ?? '',\n    passphrase: target.passphrase ?? '',\n    agentForward: target.agentForward === true,\n  }\n  return { resolved: { name: target.name, kind: 'ssh', spec } }\n}\n\n/* ------------------------------------------------------------------ *\n * 宿主服务的最小类型面（避免把 DSH 内部类型写进本包）\n * ------------------------------------------------------------------ */\n\n/** 只读其它插件 entry 的 settings（旧 `settings.get(ns)` 的替代）。 */\ninterface SettingsLookup {\n  get(ns: string): unknown\n}\n\ninterface SettingsFormsLike {\n  describe(): Array<{ ns: string; value?: Record<string, unknown>; revision?: number }>\n  update(ns: string, patch: Record<string, unknown>, expectedRevision?: number): Promise<void>\n}\n\ninterface ToolsLike {\n  register(definition: unknown): () => void\n}\n\ninterface WebServerLike {\n  register(route: unknown): () => void\n}\n\ninterface SystemPromptLike {\n  section(options: { name: string; order?: number; text: string }): () => void\n}\n\n/* ------------------------------------------------------------------ *\n * 插件\n * ------------------------------------------------------------------ */\n\nconst plugin = definePlugin<Config>({\n  name: 'docker',\n  apply(ctx: Context, rawConfig?: Config) {\n    /*\n     * 授权来源必须在**第一次 capabilityGranted 之前**绑定（下面的 normalizeConfig 就会查它）：\n     * 环境变量那一半取宿主的启动快照，就地提权那一半取带外授权存储。详见 kit 的 capability.ts /\n     * grant-store.ts。存储每次 apply 新建一个实例 —— 这就是「宿主重启后重新读盘」的语义。\n     *\n     * 落点全部来自 kit 的 `capabilityPaths`（`<DSH home>/dsh-kit/`）：路径只在那里拼一次，\n     * 插件不再自己 join（kit D08：平铺在 DSH 主目录的 `capability-grants.json` / `grant-confirm/`\n     * 不带归属，容易与官方或别的插件撞名）。\n     */\n    const paths = capabilityPaths(dshHome())\n    // **共享实例**（kit D11）：docker 与 tty 同装时各 new 一个会各自缓存一份文件快照，\n    // 后绑定的那个看不到另一个后来写进去的授权（实测：tty 授权成功后自己的快照仍是 false）\n    const grantStore = sharedGrantStore(paths.dir)\n    bindCapabilitySources(ctx, grantStore)\n    /*\n     * 启动期审计：盘上已有的带外授权是**持久**的（重启后直接生效、不再有任何一次确认），所以那次\n     * 「静默继承」必须在日志里留下痕迹——否则「三周前授权的能力今天一开机就开着」无可追溯（kit D09）。\n     * 只报本插件的两条能力；环境变量通道由启动环境本身表达，不在这里重复。\n     *\n     * 刻意放在 `enabled` 判定**之前**：授权是宿主级的、与插件这次是否启用无关；插件这次是禁用态时\n     * 反而更该说一句（「盘上有授权，但插件没开」与「点了没反应」是两回事）。\n     */\n    auditLoadedGrants(\n      grantStore,\n      [CAP_MUTATIONS.env, CAP_EXEC.env],\n      '[dsh-docker]',\n    )\n    // volatile 字段解析后是 `{ get() }` 引用，先还原成纯数据（见 @hyzyn/dsh-kit 的 plainConfig）。\n    const config = plainConfig((rawConfig ?? {}) as Config)\n    /*\n     * 配置里**写着的**能力开关值（**没和授权折叠**）。\n     *\n     * 为什么必须单独留一份：`live.allowMutations` 是「配置值 && 已授权」折叠后的**有效值**，一旦\n     * 用户在没授权时打开过开关，它就成了 false——此后「重算」再拿它当输入，永远回不到 true\n     * （授权到了、工具却不注册，就是那个半个状态）。重算必须从**配置值**出发：\n     *   - `applySection` 把这一份塞回合并结果里（见那里的注释）；\n     *   - 快照里的 `*Configured` 字段也用它，界面靠它把开关画成「开着但未生效」。\n     *\n     * （D141/D142：折叠后的有效值当输入 = 授权到了也回不来；快照缺配置值/来源 = 界面说不出\n     * 「配置开着但没授权」。）\n     */\n    let configuredCapabilities = {\n      allowMutations: config.allowMutations === true,\n      allowExec: config.allowExec === true,\n    }\n    let live = normalizeConfig(config as Record<string, unknown>)\n    if (!live.enabled) return\n\n    const logger: ExecLogger = {\n      info: (msg) => ctx.logger.info(msg),\n      warn: (msg) => ctx.logger.warn(msg),\n    }\n\n    /*\n     * 诊断历史（批三）：把「一次诊断」变成时间序列，回答「它在慢慢变坏吗」。\n     *\n     * **为什么历史不是新工具 / 新路由**：它不是新的采集面，只是同一份 diagnosis 的第二种视图。\n     * `docker_logs` 与 `docker_logs_grep` 之所以拆成两条，是因为预算模型不同（前者「返回 = 收到」、\n     * 后者「扫得多、返回少」）；这里预算完全相同，多拆一条只会让模型多试一次。\n     *\n     * **写盘失败绝不能让诊断失败**：历史是辅助信息，读不到只是没有趋势，而诊断本身仍然有价值。\n     * 所以整段 catch 住、记一行日志、回空历史（`recorded: false`）——「加了个新功能，结果老功能\n     * 因为磁盘满了不能用了」是本仓最不能接受的那类回归。\n     *\n     * 落点只在 `diagnosisHistoryPaths()` 里拼一次（见 history-store.ts 文件头）；store 构造**不碰磁盘**。\n     */\n    const historyStore = new DiagnosisHistoryStore(diagnosisHistoryPaths(dshHome()).dir)\n    const HISTORY_DEFAULT = 10\n    const HISTORY_LIMIT_MAX = 50\n    /** `history` 参数：非有限数回落默认、越界夹紧——与 `tail` / `logTail` 的既有风格一致（不报错）。 */\n    const clampHistoryCount = (value: unknown): number => {\n      if (typeof value !== 'number' || !Number.isFinite(value)) return HISTORY_DEFAULT\n      return Math.min(Math.max(Math.trunc(value), 0), HISTORY_LIMIT_MAX)\n    }\n    /**\n     * 采集 → 压缩成样本 → 落盘（受去重窗口约束）→ 读回最近 N 条 → 趋势。\n     *\n     * 索引键用**容器名**（`target + container`）：改名会开一段新历史。这是可见的行为变化，\n     * 但比「改名后把两个容器的历史混在一起」好——混起来会让趋势说出根本没发生过的变化。\n     */\n    const diagnoseWithHistory = async (\n      api: DockerApi,\n      target: string,\n      id: string,\n      options: { logTail?: unknown; since?: unknown; history?: unknown },\n    ): Promise<{ diagnosis: Diagnosis; history: DiagnosisHistoryView }> => {\n      const since = typeof options.since === 'string' && options.since.trim() !== '' ? assertSince(options.since) : undefined\n      const result = await api.diagnose(id, {\n        ...(typeof options.logTail === 'number' ? { logTail: options.logTail } : {}),\n        ...(since === undefined ? {} : { since }),\n      })\n      const diagnosis = result.diagnosis\n      const limit = clampHistoryCount(options.history)\n      const container = diagnosis.name === '' ? diagnosis.id : diagnosis.name\n      let recorded = false\n      try {\n        recorded = historyStore.append({\n          v: HISTORY_SCHEMA_VERSION,\n          target,\n          container,\n          id: diagnosis.id,\n          // 时钟在**这里**读（history.ts 是纯逻辑，时钟由调用方注入，同 diagnose.ts）\n          sample: sampleFromDiagnosis(diagnosis, Date.now()),\n        })\n      } catch (error) {\n        logger.warn(`[dsh-docker] 诊断历史写入失败（本次只回空历史）：${error instanceof Error ? error.message : String(error)}`)\n        return { diagnosis, history: { samples: [], trend: historyTrend([]), recorded: false } }\n      }\n      let samples: DiagnosisSample[] = []\n      // `history: 0` = 明确不要历史（但**仍然记录**：记录是默认行为，读不读是调用方的选择）\n      if (limit > 0) {\n        try {\n          samples = historyStore.read(target, container).slice(-limit)\n        } catch (error) {\n          logger.warn(`[dsh-docker] 诊断历史读取失败（趋势本次不可用）：${error instanceof Error ? error.message : String(error)}`)\n        }\n      }\n      return { diagnosis, history: { samples, trend: historyTrend(samples), recorded } }\n    }\n\n    /* ---------- 主机指纹（TOFU，本插件自持；tty 记录作种子） ---------- */\n\n    let settingsScope: SettingsEntryScope | undefined\n    let settingsForms: SettingsFormsLike | undefined\n    /**\n     * 只读他人 entry（如 tty 的连接簿）：旧 `settings.get(ns)` 在新宿主已不存在，\n     * 改走 `settings.describe()` 的 entry 查找（kit 的 readSettingsEntry）。settings\n     * 子上下文就绪前保持 undefined，调用方当空表处理——与旧行为一致。\n     */\n    let settingsApi: SettingsLookup | undefined\n    const ttySeed = (): Map<string, string[]> => {\n      const map = new Map<string, string[]>()\n      for (const record of readTtyHostKeys(settingsApi)) map.set(`${record.host}:${String(record.port)}`, record.fingerprints)\n      return map\n    }\n    const persistHostKeys = (records: HostKeyRecord[]): void => {\n      const scope = settingsScope\n      if (scope === undefined) return\n      void Promise.resolve(scope.update({ hostKeys: records })).catch((error: unknown) => {\n        console.warn('[dsh-docker] 主机密钥记录持久化失败: ' + (error instanceof Error ? error.message : String(error)))\n      })\n    }\n    const hostKeyStore: HostKeyStore = {\n      get(host, port) {\n        // host 键统一 trim + 小写（D03）：tty 落盘时把 host 小写化，比较口径必须一致\n        const key = host.trim().toLowerCase()\n        const own = live.hostKeys.find((record) => record.host === key && record.port === port)\n        if (own !== undefined && own.fingerprints.length > 0) return own.fingerprints\n        // tty 已确认过的主机不再重复确认：种子命中即视为可信，并**整组**复制进本插件的\n        // 记录（D03）——此前只认单数 fingerprint 字段，tty 0.19.0 改存 fingerprints[] 后\n        // 种子恒为空，对 tty 钉扎过的主机会静默重新 TOFU（指纹变更不再拒绝）。\n        const seeded = ttySeed().get(`${key}:${String(port)}`)\n        if (seeded !== undefined && seeded.length > 0) {\n          live.hostKeys = [...live.hostKeys, { host: key, port, fingerprints: [...seeded] }]\n          persistHostKeys(live.hostKeys)\n          return seeded\n        }\n        return own?.fingerprints\n      },\n      record(host, port, fingerprint) {\n        const key = host.trim().toLowerCase()\n        const existing = live.hostKeys.find((record) => record.host === key && record.port === port)\n        if (existing !== undefined) {\n          // 同一主机的第二把主机密钥（rsa + ed25519）：并入集合而不是覆盖（D03）\n          if (!existing.fingerprints.includes(fingerprint)) {\n            existing.fingerprints = [...existing.fingerprints, fingerprint]\n            persistHostKeys(live.hostKeys)\n          }\n          return\n        }\n        const next = live.hostKeys.filter((record) => !(record.host === key && record.port === port))\n        next.push({ host: key, port, fingerprints: [fingerprint] })\n        live.hostKeys = next\n        persistHostKeys(next)\n      },\n    }\n\n    /*\n     * ProxyCommand 闸门：**每次拨号现读** tty settings（回调只做一次对象属性读取，无 IO）。\n     * 不缓存成布尔值：用户随时可能关掉它，缓存意味着「关了还能用」——这一档最不能出的错。\n     * settingsApi 在 settings 子上下文就绪前是 undefined，那时恒 false（= 关，安全方向）。\n     */\n    const remote = new RemoteExec(logger, hostKeyStore, { proxyCommandAllowed: () => readTtyProxyCommandAllowed(settingsApi) })\n\n    /**\n     * 当前生效的 targets：**以 settings 解析值为准**。\n     * 为什么不能只读内存里的 live：settings 解析是异步的（服务就绪后才读一次），存在一个\n     * 窗口期内 live 仍是 composition 配置（targets 为空）。若此时 GET /config 被\n     * 调用，卡片会拿到空目标列表，用户随后保存就把空数组写回 → 目标被清空。\n     */\n    const targetsNow = (): DockerTarget[] => {\n      const scope = settingsScope\n      if (scope !== undefined) {\n        try {\n          const resolved = scope.get()\n          if (typeof resolved === 'object' && resolved !== null) {\n            const fromScope = sanitizeTargets((resolved as Record<string, unknown>).targets)\n            if (fromScope !== undefined) return fromScope\n          }\n        } catch {\n          /* 回落到内存值 */\n        }\n      }\n      return live.targets\n    }\n\n    /* ---------- 目标解析与 DockerApi ---------- */\n\n    /** 目标名 → 解析结果（每次现算，连接簿热改立即生效）。 */\n    const resolveByName = (name: string): { resolved?: ResolvedTarget; error?: string } => {\n      const target = targetsNow().find((item) => item.name === name)\n      if (target === undefined) {\n        const names = targetsNow().map((item) => item.name).join('、')\n        return { error: `未知目标：${name}${names === '' ? '（尚未配置任何目标）' : `（已配置：${names}）`}` }\n      }\n      return resolveTarget(target, readTtyBooks(settingsApi))\n    }\n\n    /**\n     * 取某个目标上的 DockerApi（Runner 每次新建，连接由 RemoteExec 池化）。\n     *\n     * `signal`（D161）只有**跨目标聚合**会传：它把「这一格的预算到点了」串到该目标\n     * **底层每一条命令**上（`createRunner` 绑到 Runner 上，见那边的注释）。其余调用点\n     * 不传，行为与之前完全一致。\n     */\n    const apiFor = (name: string, signal?: AbortSignal): { api?: DockerApi; resolved?: ResolvedTarget; error?: string } => {\n      const { resolved, error } = resolveByName(name)\n      if (resolved === undefined) return { error }\n      try {\n        const runner = createRunner({ target: resolved, remote, logger, ...(signal === undefined ? {} : { signal }) })\n        return { api: new DockerApi(runner, live.dockerBin, { timeoutMs: 30_000, maxBytes: live.maxOutputKb * 1024 }), resolved }\n      } catch (error_) {\n        return { error: error_ instanceof Error ? error_.message : String(error_) }\n      }\n    }\n\n    /** 单目标省略 target 参数时的默认目标。 */\n    const defaultTargetName = (): string | undefined => {\n      const list = targetsNow()\n      return list.length === 1 ? list[0]?.name : undefined\n    }\n\n    /** 解析工具/路由里的 target 参数。 */\n    const pickTarget = (input: unknown): { name?: string; error?: string } => {\n      if (typeof input === 'string' && input.trim() !== '') {\n        const name = input.trim()\n        // `*` 聚合只有 docker_ps / docker_attention 支持（D46）：到这里说明是单目标\n        // 工具传了 `*`——给专门文案，而不是一句「未知目标：*」\n        if (name === '*') return { error: '`*`（全部目标）只有 docker_ps / docker_attention 支持；请传具体目标名（docker_targets 列出）' }\n        return { name }\n      }\n      // 类型不对（数字 / 数组 / 对象）必须报错（D34）：静默回落到默认目标会让\n      // 破坏性操作打错主机的最后一道防线失效\n      if (input !== undefined && input !== null && typeof input !== 'string') {\n        return { error: 'target 必须是字符串（目标名见 docker_targets）' }\n      }\n      const fallback = defaultTargetName()\n      if (fallback !== undefined) return { name: fallback }\n      const list = targetsNow()\n      if (list.length === 0) return { error: '尚未配置任何 Docker 目标：可调 docker_connect_local 一键加上本机目标，或到 插件配置 → Docker 容器面板 添加' }\n      return { error: 'target 必填（已配置多个目标：' + list.map((item) => item.name).join('、') + '）' }\n    }\n\n    /* ---------- 一键连接本机（面板按钮 / HTTP 路由 / agent 工具共用这一份实现） ---------- */\n\n    /**\n     * 探测失败 → 给用户的一句话（这次探测的 bin 以**配置里的 `dockerBin`** 为准）。\n     *\n     * 只有「CLI 缺失」这一档才去 PATH 里找候选：那要 accessSync 若干次，其余档位全是\n     * 纯文本判断，不该无谓地跑文件系统。\n     */\n    const localProbeReason = (raw: string, timedOut = false): string => {\n      const alternative = isLocalCliMissing(raw) ? findAlternativeLocalCli(live.dockerBin)[0] : undefined\n      return describeLocalProbeFailure(raw, live.dockerBin, {\n        timedOut,\n        ...(alternative === undefined ? {} : { alternativeCli: alternative }),\n      })\n    }\n\n    /**\n     * 显式加一个本机目标并选中它，然后把只读探测结果一并回报。\n     *\n     * 四条不变量（缺任何一条都会变成另一种东西）：\n     *   - **幂等**：已有 `kind=local` 就复用它（`created:false`），绝不重复创建；重复点、并发点都落到同一条。\n     *   - **不改别人的**：SSH / 自定义目标原样保留，`targets` 顺序也只追加（`[...existing, 新建]`）——\n     *     不排序、不重写已存在的条目（重写会丢掉 `mergeTargetSecrets` 才补得回的密码）。\n     *   - **没有隐式默认目标**：只有本函数被显式调用才动 `targets`；空数组 / `clearTargets` 的既有语义一字不改。\n     *   - **落盘成功才算数**：settings 不可用或保存失败一律**明确报错且不改内存配置**（no-op），\n     *     绝不出现「界面显示已加上了、刷新就没了」。\n     *\n     * 权限：这条路径只写**本插件自己的配置**（加一个指向宿主自身的本机目标）+ 只读探测，\n     * 与服务端 root 等价的那两档能力（`allowMutations` / `exec`）无关，因此不要求任何授权；\n     * 也绝不自动装 Docker、起 daemon、切 docker context 或改 env。\n     */\n    const connectLocalOnce = async (): Promise<\n      { ok: true; result: ConnectLocalResult } | { ok: false; code: number; error: string }\n    > => {\n      if (!live.enabled) return { ok: false, code: 403, error: 'Docker 插件已禁用' }\n      const existing = targetsNow()\n      const found = findLocalTargetName(existing)\n      // Reusing an existing local target only probes it; it does not need a settings write.\n      if (found === undefined && settingsScope === undefined) {\n        return { ok: false, code: 503, error: '设置存储不可用（宿主未提供 settings 服务），无法保存本机目标；请稍后重试' }\n      }\n      const name = found ?? nextLocalTargetName(existing.map((item) => item.name))\n      if (name === undefined) {\n        return { ok: false, code: 400, error: `本机目标名冲突：已有 1000 个 local* 目标，请先删掉一些再试` }\n      }\n      let created = false\n      if (found === undefined) {\n        /* 新条目只写展示名与 kind：其余字段交给 normalizeConfig / sanitizeTargets 的默认值（单一来源）。 */\n        const scope = settingsScope!\n        let entry: { value?: Record<string, unknown>; revision?: number } | undefined\n        try {\n          entry = settingsForms?.describe().find((item) => item.ns === scope.ns)\n        } catch {\n          return { ok: false, code: 503, error: '无法读取当前目标配置，请稍后重试' }\n        }\n        if (entry === undefined) return { ok: false, code: 503, error: '当前设置条目不可用，请稍后重试' }\n        const rawTargets = entry.value?.targets\n        const nextTargets = [...(Array.isArray(rawTargets) ? rawTargets : existing), { name, kind: 'local' as const }]\n        try {\n          await settingsForms!.update(scope.ns, { targets: nextTargets }, entry.revision)\n        } catch (error) {\n          return { ok: false, code: 500, error: '保存本机目标失败：' + (error instanceof Error ? error.message : String(error)) }\n        }\n        created = true\n        /*\n         * `scope.update` 之后必须自己应用一次：真实 loader 会发 `loader/volatile-update` 触发\n         * applySection，但那个事件是**异步**的，单测 / 老宿主还可能完全不发。这里同步应用是幂等的\n         * （applySection 用同一份 settings 值再归一化一次），而**不应用**的后果是「刚加上的目标\n         * 在探测那一步还解析不到」。\n         */\n        try {\n          applySection({ targets: nextTargets })\n        } catch (error) {\n          return {\n            ok: false,\n            code: 500,\n            error: '本机目标已保存但应用失败：' + (error instanceof Error ? error.message : String(error)),\n          }\n        }\n      }\n      // 探测失败一律降级为 message（见 ConnectLocalResult 的注释），不是这次操作的失败\n      const built = apiFor(name)\n      if (built.api === undefined) {\n        return {\n          ok: true,\n          result: {\n            name,\n            kind: 'local',\n            created,\n            saved: true,\n            reachable: false,\n            message: `已${created ? '添加并选中' : '选中'}本机目标「${name}」，但无法构造执行通道：${built.error ?? '未知错误'}`,\n          },\n        }\n      }\n      let reachable = false\n      let serverVersion: string | undefined\n      let reason = ''\n      try {\n        const probe = await built.api.probe()\n        reachable = probe.ok\n        if (probe.serverVersion !== null) serverVersion = probe.serverVersion\n        if (!probe.ok) reason = localProbeReason(probe.error ?? '', probe.timedOut)\n      } catch (error) {\n        reason = localProbeReason(error instanceof Error ? error.message : String(error))\n      }\n      const head = `已${created ? '添加并选中' : '选中'}本机目标「${name}」`\n      return {\n        ok: true,\n        result: {\n          name,\n          kind: 'local',\n          created,\n          saved: true,\n          reachable,\n          ...(serverVersion === undefined ? {} : { serverVersion }),\n          message: reachable\n            ? `${head}：docker daemon 可达${serverVersion === undefined ? '' : `（${serverVersion}）`}`\n            // 连接失败必须说清**为什么**：daemon 没起 / CLI 缺失 / socket 权限，而不是只报「没有容器」\n            : `${head}，但本机 docker 不可用——${reason === '' ? 'docker version 未返回可用信息' : reason}`,\n        },\n      }\n    }\n\n    // Serialize this read-modify-write across HTTP and tool callers. Rejections never poison the queue.\n    let localConnectQueue: Promise<unknown> = Promise.resolve()\n    const connectLocal = (): ReturnType<typeof connectLocalOnce> => {\n      const pending = localConnectQueue.then(connectLocalOnce)\n      localConnectQueue = pending.catch(() => {})\n      return pending\n    }\n\n    /**\n     * 跨目标聚合（0.15.0）：所有目标的容器 / 需关注列表在面板与 agent 工具里共用同\n     * 一套逻辑。三个必须的性质：\n     *   - **并发上限**：ssh exec 扇出太多会互相挤（远端 sshd MaxStartups / 本机 fd）；\n     *   - **单目标超时**：一台网络不通不能把整个聚合页拖住；\n     *   - **错误隔离**：失败的组带上 error 照常返回，其余目标的结果照常可用。\n     *\n     * 第四个性质是 **D161 补上的**：单个目标超时的那一刻，**它底下正在跑的命令必须真的被\n     * 停掉**。旧写法只 `Promise.race` 出一个 `ok:false`，底层那条 SSH channel 继续跑完——\n     * 而它占着的正是 `MaxSessions` 的 session 槽（sshd 在子进程活着时不释放，见 D150）。\n     */\n    const AGG_CONCURRENCY = 4\n\n    /**\n     * 单目标上**每一条**命令的内层预算（30s，DockerApi 构造时传下去的那一个）。\n     *\n     * 单独取个名字是为了让「外层兜底」与「内层真相」共用一个来源：D161 之前这里是\n     * `apiFor` 里的裸字面量 `30_000`，而外层是另一个裸字面量 `45_000`——两个数字各写各的，\n     * 谁也不知道它们的关系，于是 45s 那个到底会不会打断一条健康命令，没人说得清。\n     */\n    const AGG_CMD_TIMEOUT_MS = 30_000\n\n    /**\n     * 单个目标那一格的**兜底**预算（D161）。\n     *\n     * 取舍（两种做法里选了后者）：\n     *   - ①「把外层提到大于单目标最坏序列耗时」——`attention()` 是 `listContainers` +\n     *     最多约 9 批 `inspect` 的**串行**序列（`ATTENTION_INSPECT_CAP 300 + 补捞 50`，\n     *     每批 ≤ 40），最坏 10 × 30s ≈ 300s。真按这个上界设，总览页等一台卡住的机器要\n     *     等五分钟，等于没有预算；\n     *   - ②**内层超时是唯一真相源，外层只做兜底** ← 选这个。30s/命令已经给每条命令兜了底，\n     *     外层存在的意义只是「内层没兜住时（连接获取 / 闸门排队 / 某个实现没遵守\n     *     timeoutMs）别把整页拖死」。所以它取 3 倍单条预算（90s）：大于 `attention` 的\n     *     典型两段（ps + 首批 inspect ≈ 60s），不会被健康命令序列撞上；又给异常留了一档\n     *     天花板。到点即 `abort()`——**这是这次修复的实质**，配置数字只是顺带对齐。\n     *\n     * `DSH_DOCKER_AGG_TIMEOUT_MS` 可覆盖，**只为测试与排障**（同 `DSH_DOCKER_SHORT_CHANNELS`\n     * 的口径）：90s 这条路径没法在单测里等，而「超时后底层有没有真的被取消」恰恰是本轮\n     * 的验收点——没有这个口子就只能测到「返回了 ok:false」，那正是修复前就恒绿的那条。\n     */\n    function aggTimeoutMs(): number {\n      const raw = Number(process.env.DSH_DOCKER_AGG_TIMEOUT_MS)\n      return Number.isFinite(raw) && raw > 0 ? raw : AGG_CMD_TIMEOUT_MS * 3\n    }\n\n    async function mapLimit<T, R>(items: readonly T[], limit: number, run: (item: T, index: number) => Promise<R>): Promise<R[]> {\n      const results = new Array<R>(items.length)\n      let cursor = 0\n      const workers = new Array(Math.min(Math.max(limit, 1), Math.max(items.length, 1))).fill(null).map(async () => {\n        for (;;) {\n          const index = cursor\n          cursor += 1\n          if (index >= items.length) return\n          results[index] = await run(items[index] as T, index)\n        }\n      })\n      await Promise.all(workers)\n      return results\n    }\n\n    interface TargetGroup<T> {\n      target: string\n      label: string\n      ok: boolean\n      error?: string\n      /** 该目标上聚合出来的数据（形状由调用方决定：容器数组 / 需关注数组）。 */\n      data?: T\n    }\n\n    /** 在所有（或指定）目标上跑同一件事，返回按目标分组的「部分成功」结果。 */\n    const aggregateAcrossTargets = async <T>(\n      names: readonly string[],\n      run: (api: DockerApi, name: string) => Promise<T>,\n    ): Promise<Array<TargetGroup<T>>> => {\n      return await mapLimit(names, AGG_CONCURRENCY, async (name): Promise<TargetGroup<T>> => {\n        /*\n         * 控制器必须建在 `run()` **之前**（D161）：Runner 是在 `apiFor` 里构造的，signal\n         * 当场绑到 Runner 上（见 createRunner）。先跑再建的话，abort 时底层根本不知道\n         * 自己被取消——那正是修复前的行为。\n         */\n        const controller = new AbortController()\n        const budget = aggTimeoutMs()\n        const built = apiFor(name, controller.signal)\n        const resolved = built.resolved\n        const label = resolved === undefined\n          ? name\n          : (resolved.kind === 'local' ? '本机' : sshTarget(resolved.spec as SshSpec))\n        if (built.api === undefined) {\n          controller.abort()\n          return { target: name, label, ok: false, error: built.error ?? '无法构造执行通道' }\n        }\n        const api = built.api\n        let timer: NodeJS.Timeout | null = null\n        try {\n          const timeout = new Promise<never>((_resolve, reject) => {\n            timer = setTimeout(() => {\n              /*\n               * 顺序是**先取消、后拒绝**（D161）：反过来的话调用方在 reject 的那一刻就拿到\n               * `ok:false` 返回了，而底层（本地子进程 / SSH channel）还在跑——用户看到的是\n               * 「这一格失败了」，实际那条 inspect 还占着远端的 session 槽，后续短命令被拒。\n               */\n              controller.abort()\n              reject(new Error(`聚合超时（>${String(budget / 1000)}s）`))\n            }, budget)\n            timer.unref?.()\n          })\n          const data = await Promise.race([run(api, name), timeout])\n          return { target: name, label, ok: true, data }\n        } catch (error) {\n          return { target: name, label, ok: false, error: error instanceof Error ? error.message : String(error) }\n        } finally {\n          if (timer !== null) clearTimeout(timer)\n          /*\n           * race 另一侧赢（命令正常跑完 / 抛错）时也要兜底取消：`abort()` 是幂等的，命令\n           * 已 settle 时它是**无害的空操作**（监听器在收尾时已摘掉），但漏了这一句就会留下\n           * 「signal 永不 abort、挂在它上面的闭包链不放」的尾巴。\n           */\n          controller.abort()\n        }\n      })\n    }\n\n    /** 目标名列表：'*' / 空 表示全部（保持配置顺序）。 */\n    const targetsFor = (input: unknown): string[] => {\n      if (typeof input === 'string' && input.trim() !== '' && input.trim() !== '*') return [input.trim()]\n      return targetsNow().map((item) => item.name)\n    }\n\n    /* ---------- 配置快照（凭证不外泄） ---------- */\n\n    const snapshotTarget = (target: DockerTarget): Record<string, unknown> => ({\n      name: target.name,\n      kind: target.kind,\n      book: target.book ?? '',\n      host: target.host ?? '',\n      port: target.port ?? 22,\n      username: target.username ?? '',\n      auth: target.auth ?? 'agent',\n      keyPath: target.keyPath ?? '',\n      agentForward: target.agentForward === true,\n      // 密码 / 口令只回「是否已设置」，值永不回传浏览器\n      passwordSet: typeof target.password === 'string' && target.password !== '',\n      passphraseSet: typeof target.passphrase === 'string' && target.passphrase !== '',\n    })\n\n    const snapshot = (): Record<string, unknown> => {\n      const books = readTtyBooks(settingsApi)\n      return {\n        enabled: live.enabled,\n        announceToAgent: live.announceToAgent,\n        dockerBin: live.dockerBin,\n        allowMutations: live.allowMutations,\n        allowExec: live.allowExec,\n        /*\n         * 配置里**写着的**值（未与授权折叠）：开关的视觉状态用它，有效值用上面那两个。\n         * 两张都要给客户端，否则「配置开着但没授权」这个状态在界面上无法表达——那正是本仓最忌讳的\n         * 「配了没反应」：开关看着是开的、什么都不会发生，却没有任何东西说明原因。\n         */\n        allowMutationsConfigured: configuredCapabilities.allowMutations,\n        allowExecConfigured: configuredCapabilities.allowExec,\n        // 宿主侧授权（只读）：客户端用它把开关渲染成「点不动 + 说明怎么开」\n        allowMutationsGranted: capabilityGranted(CAP_MUTATIONS),\n        allowExecGranted: capabilityGranted(CAP_EXEC),\n        /*\n         * 授权来源：'env' = 启动环境变量（界面不给「撤销」按钮，因为它只能靠改启动环境撤销）、\n         * 'file' = 就地确认写下的带外授权（界面可撤销）、null = 没授权。\n         * 客户端据此决定显示「撤销宿主授权」还是「去启动环境里去掉它」，两者完全不同。\n         */\n        allowMutationsGrantSource: capabilityGrantVia(CAP_MUTATIONS) ?? null,\n        allowExecGrantSource: capabilityGrantVia(CAP_EXEC) ?? null,\n        /*\n         * 授权时刻（Unix 秒；只有 file 通道有值，环境变量通道与未授权都是 null）。授权是**持久**\n         * 的：重启后它直接生效、不再确认，所以界面至少要能说出「它是什么时候来的」（D09）。\n         */\n        allowMutationsGrantedAt: capabilityGrantAt(CAP_MUTATIONS) ?? null,\n        allowExecGrantedAt: capabilityGrantAt(CAP_EXEC) ?? null,\n        execTimeoutSec: live.execTimeoutSec,\n        pollIntervalSec: live.pollIntervalSec,\n        logTailDefault: live.logTailDefault,\n        maxOutputKb: live.maxOutputKb,\n        targets: targetsNow().map(snapshotTarget),\n        hostKeys: live.hostKeys,\n        // 只读复用 tty 连接簿：卡片用它渲染「从连接簿选择」下拉\n        ttyBooks: [...books.keys()],\n        /*\n         * 连接簿条目 → 解析后的 host:port（**只 name/host/port，凭据永不出宿主**）。\n         *\n         * 客户端「当前会话主机 ↔ 目标」的匹配要在**连接之前**就能判定：从连接簿打开的\n         * SSH 标签，spec 里只有条目名；宿主回显的 `tab.target` 只在**连接成功**后才\n         * 有值，而连不上（握手超时 / 主机没开机）恰恰是最需要面板的时候。少了这张表，\n         * 面板只能判成「该主机没配目标」，然后沿用上一次选的目标——把另一台主机的容器\n         * 显示出来。有了它，按主机配的目标（如目标绑 lab-a 条目、会话走\n         * 192.0.2.10 条目）在连接失败时也能对上。\n         */\n        ttyBookHosts: [...books.entries()].map(([name, spec]) => ({ name, host: spec.host, port: spec.port })),\n        ttyAvailable: books.size > 0,\n        toolsRegistered: registeredNames,\n        /*\n         * SSE 帧协议版本（客户端据此决定「怎样才算已就绪」）。\n         *\n         * 2 = 四条流在**执行管道真的起来**时先发一帧 `ready`（见 readyOnStart）。客户端半体\n         * 与宿主半体同包同版本，正常不会错位；但开发档里「宿主进程还是旧代码（模块已在内存\n         * 里）、浏览器却从磁盘读到新的 client.js」这种组合会让新客户端死等一帧永远不来的\n         * `ready`，把界面钉在「正在连接事件流…」上（2026-10-11 用户在 test profile 上实测到）。\n         * 所以把版本放在这里：客户端读到 <2 就退回旧判据（响应头就算连上），读到 2 才只认\n         * `ready`。字段缺失（更老的宿主）由客户端按「发 ready」以外的规则兜底，见\n         * client-src/index.js 的 hostSendsReadyFrame。\n         *\n         * 3 = `/logs/stream` 支持多容器单连接（`ids=` + 带 `id` 的分源帧 + source-end /\n         * source-error）。为什么必须再升一版：聚合视图要据此决定「一条连接带全部容器」还是\n         * 「每个容器各开一条 EventSource」——判定错了，新客户端会去解析老宿主永远不发的事件，\n         * 而老客户端拿到多源帧也认不出 `id`（它只读 `d` / `e`，会把几个容器的行混成一本账）。\n         * **≥2 的 ready 语义不变**，新增的是同一条流里的源维度。\n         */\n        streamProtocol: 3,\n      }\n    }\n\n    /* ---------- 活跃 SSE 长流清点 ---------- */\n\n    /**\n     * 活跃的 SSE 长流句柄（日志 / 统计 / 拉取三条流共用）。流本身由 HTTP handler\n     * 持有并自清理；这里登记一份，供插件禁用 / 配置热更新 / 卸载时统一收尾\n     * （end + abort 执行器）。句柄是每个插件实例一份（不共享模块级集合），\n     * 多实例挂载时不会互相误杀。\n     */\n    const activeStreams = new Set<{ end(): void }>()\n\n    const closeAllStreams = (): void => {\n      for (const stream of [...activeStreams]) {\n        try {\n          stream.end()\n        } catch {\n          /* 连接已断开 */\n        }\n      }\n      activeStreams.clear()\n    }\n\n    /* ---------- 通用 SSE 长连接（三条流共用一份基建） ---------- */\n\n    /**\n     * 「执行管道真的起来了」→ 一帧 `ready`（配合 {@link StreamHandlers.onStart}）。\n     *\n     * 为什么必须有这一帧：SSE 的 `onopen` **只证明响应头到了**——`openSseStream` 是先把\n     * 200 + `text/event-stream` flush 出去、再去起 `docker ...`。目标不可达 / SSH 正在\n     * 重连时 `acquire()` 可能卡十几秒，浏览器却已经「连上」了；客户端据此把活动条点亮成\n     * 绿色的「实时接收中（docker events）」，而那条流一个字都还没收到（2026-10-11 用户现场）。\n     * 现在客户端的 `open` 只认这帧，响应头不再算数。\n     */\n    const readyOnStart = (sendEvent: (event: string, data: unknown) => void): (() => void) => () => sendEvent('ready', {})\n\n    /**\n     * 通用 SSE 长连接。日志流（`docker logs -f`）、统计流（`docker stats`）、\n     * 拉取流（`docker pull`）三者只差「执行器 + 结束原因 + end 附加字段」，\n     * 其余全部共用这一份实现：\n     *\n     *   - 响应头（text/event-stream / no-cache / keep-alive / x-accel-buffering）\n     *     统一在这里写，写完立即 flushHeaders（宿主 gzip 对 SSE 显式跳过）；\n     *   - 每 15s 一帧 `: ping` 注释心跳（SSE 规范里客户端忽略）；\n     *   - 活跃流登记：插件禁用 / 配置热更新 / 卸载时由 closeAllStreams 统一收尾；\n     *   - 客户端断开 → 静默清理（不写任何帧）+ abort 执行器；\n     *   - 执行器正常退出 → `end` 帧（带 reason / code / 附加字段）后关闭响应；\n     *   - 执行器抛错 → `error` 帧后关闭响应。\n     *\n     * 调用方负责「参数校验」——校验失败时写常规 JSON（4xx）并直接返回，不建流。\n     * 管道起来后要发的那帧 `ready` 见 {@link readyOnStart}（由调用方挂在 `onStart` 上）。\n     */\n    const openSseStream = async (\n      res: ResLike,\n      options: {\n        /** `end` 帧的 reason（执行器自然退出时发）。 */\n        reason: string\n        /** 执行器：sendEvent 发帧，signal 中止；resolve 得到 docker 退出码。 */\n        run: (sendEvent: (event: string, data: unknown) => void, signal: AbortSignal) => Promise<number | null>\n        /** `end` 帧的附加字段（如 ref / ids）。 */\n        endData?: (code: number | null) => Record<string, unknown>\n        /**\n         * 背压队列溢出时的策略（D153，见下）：`'end'`（默认）补一条 end 收尾；\n         * `'drop'` 丢最旧的整帧、保留最新并推一条 `skip` 通知——\n         * 日志 / 拉取这类**文本尾部流**用它（丢的是本来就会被客户端环形缓冲丢掉的历史）。\n         */\n        overflow?: 'end' | 'drop'\n      },\n    ): Promise<void> => {\n      const write = res.write?.bind(res)\n      const flushHeaders = res.flushHeaders?.bind(res)\n      if (write === undefined || flushHeaders === undefined) {\n        writeJson(res, 500, { error: '宿主响应不支持 SSE 长连接' })\n        return\n      }\n\n      res.writeHead(200, {\n        'content-type': 'text/event-stream; charset=utf-8',\n        'cache-control': 'no-cache',\n        connection: 'keep-alive',\n        'referrer-policy': 'no-referrer',\n        // 反代（nginx 等）默认缓冲响应体：不关掉的话流要等缓冲区满才到浏览器\n        'x-accel-buffering': 'no',\n      })\n      flushHeaders()\n\n      const controller = new AbortController()\n      let done = false\n      let heartbeat: NodeJS.Timeout | null = null\n\n      /*\n       * 背压（D04）：write() 返回 false = socket 写缓冲越过高水位。**注意 Node 的语义**：\n       * 返回 false 时数据**已经被收下**（只是缓冲满了，等 drain），所以这里不能把它再排一次\n       * 队列——老代码 `writeFrame` 把 false 当失败、随后又 push 进队列，drain 时会重写同一帧\n       * （客户端收到重复日志行、pendingBytes 也虚高）。现在的契约：写一次就是写一次，false\n       * 只表示「先别再直写」，等 drain 继续。\n       *\n       * 队列上限仍是每条流 ≤ MAX_PENDING_BYTES（宿主内存有界）。**溢出怎么办**由调用方选：\n       *   - `overflow: 'end'`（默认，结构化流）：补一条 `end{reason:'output-limit'}` 收尾，\n       *     客户端重连（少一帧事件语义上比缺一个事件好）；\n       *   - `overflow: 'drop'`（日志 / 拉取这类**文本尾部流**，D153）：丢掉最旧的整帧、只留\n       *     最新的，并推一条 `skip` 帧告诉客户端「中间断了一截」。丢掉的这些行本来也会被\n       *     客户端的环形缓冲（5000 行 / 4MB）丢掉——为它们把整条流掐掉，代价远大于收益\n       *     （用户现场：话痨容器一冲，面板就变成「连接中断 + 空白正文」在重连里打转）。\n       */\n      const MAX_PENDING_BYTES = 8 * 1024 * 1024\n      /** 溢出后丢到这个水位为止：一次多丢一点，给 drain 留出喘息空间。 */\n      const DROP_TARGET_BYTES = MAX_PENDING_BYTES / 2\n      const overflow = options.overflow ?? 'end'\n      let pendingFrames: string[] = []\n      let pendingBytes = 0\n      /** 高水位标记：true 时新帧一律进队列，等 drain 再续写。 */\n      let waitingDrain = false\n      /** 已被丢掉的帧数与字节数（尚未告知客户端）；skip 通知发出后清零。 */\n      let droppedFrames = 0\n      let droppedBytes = 0\n      let skipQueued = false\n\n      const isSkipFrame = (frame: string): boolean => frame.startsWith('event: skip\\n')\n\n      const stopHeartbeat = (): void => {\n        if (heartbeat === null) return\n        clearInterval(heartbeat)\n        heartbeat = null\n      }\n      /** 客户端断开 / 写失败：静默清理（不写帧），中止执行器。 */\n      const clientGone = (): void => {\n        if (done) return\n        done = true\n        stopHeartbeat()\n        pendingFrames = []\n        pendingBytes = 0\n        activeStreams.delete(handle)\n        controller.abort()\n      }\n      /** 服务端主动收尾（正常结束 / 出错 / 插件禁用 / 卸载）：关响应。 */\n      const finish = (): void => {\n        if (done) return\n        done = true\n        stopHeartbeat()\n        activeStreams.delete(handle)\n        controller.abort()\n        /*\n         * 收尾前把没写完的帧交给 res.end 落地（D83）：直接清空队列会把已经入队、还没进\n         * socket 的帧（含 end / error 帧）一起丢掉。客户端凭「连接关了但没有 end 帧」\n         * 判定异常 → EventSource 自动重连 → **拉取流会把 docker pull 再跑一遍**。\n         * 队列本身有 8MB 上限，这里一次 append 不会放大内存。\n         */\n        const tail = pendingFrames.join('')\n        pendingFrames = []\n        pendingBytes = 0\n        try {\n          res.end(tail === '' ? undefined : tail)\n        } catch {\n          /* 连接已断开 */\n        }\n      }\n      /**\n       * 写一帧。\n       * @returns `'ok'` 直写完成（可继续直写）｜`'pressure'` 已写入但越过高水位（等 drain）\n       *   ｜`'gone'` 连接已断（已走 clientGone）\n       */\n      const tryWrite = (frame: string): 'ok' | 'pressure' | 'gone' => {\n        try {\n          const result = write(frame)\n          if (isSkipFrame(frame)) {\n            // skip 通知真的落到 socket 了：这一轮的丢弃账目清零，下次再丢再报一次\n            droppedFrames = 0\n            droppedBytes = 0\n            skipQueued = false\n          }\n          return result === false ? 'pressure' : 'ok'\n        } catch {\n          // 写失败 = 连接已断：与 res close 同一收尾路径\n          clientGone()\n          return 'gone'\n        }\n      }\n      /**\n       * 溢出策略 `'drop'`：丢最旧的整帧保留最新，并保证队列里恰有一条 `skip` 通知。\n       * `skip` 帧自己**永不参与丢弃**——它是「这里断了一截」的唯一凭据。\n       */\n      const dropOldestFrames = (): void => {\n        while (pendingBytes > DROP_TARGET_BYTES && pendingFrames.length > 0) {\n          const index = pendingFrames.findIndex((frame) => !isSkipFrame(frame))\n          if (index === -1) break\n          const [frame] = pendingFrames.splice(index, 1)\n          pendingBytes -= frame.length\n          droppedFrames += 1\n          droppedBytes += frame.length\n        }\n        if (droppedFrames > 0 && !skipQueued) {\n          const notice = sseFrame('skip', { frames: droppedFrames, bytes: droppedBytes })\n          pendingFrames.push(notice)\n          pendingBytes += notice.length\n          skipQueued = true\n          return\n        }\n        /*\n         * 队列里已有一条 skip 还没写到 socket，而这期间**又发生了丢弃**：原地更新那条\n         * skip 的账目（D156）。旧实现只把首次丢弃的数排进队，之后（skip 落地前）再发生\n         * 的丢弃虽然记了账，却在 skip 真正写出时被清零一起吞掉——客户端看到的第一段\n         * 缺口永远偏小，第二段缺口则完全不可见。skip 还在队列里，改它正合适；账目清零\n         * 仍由 `tryWrite` 在它真正写出去时做，时序不变。\n         */\n        if (droppedFrames > 0) {\n          const notice = sseFrame('skip', { frames: droppedFrames, bytes: droppedBytes })\n          const index = pendingFrames.findIndex((frame) => isSkipFrame(frame))\n          if (index !== -1) {\n            pendingBytes += notice.length - (pendingFrames[index] as string).length\n            pendingFrames[index] = notice\n          } else {\n            // 防御：skipQueued 为 true 却找不到帧（不该发生）——退回「新排一条」\n            pendingFrames.push(notice)\n            pendingBytes += notice.length\n          }\n        }\n      }\n      /** drain 后续写暂存的帧；中途再遇高水位就停手等下一次 drain。 */\n      const flushPending = (): void => {\n        while (!done && pendingFrames.length > 0) {\n          const frame = pendingFrames[0] as string\n          const result = tryWrite(frame)\n          if (result === 'gone') return\n          pendingBytes -= frame.length\n          pendingFrames.shift()\n          if (result === 'pressure') {\n            waitingDrain = true\n            return\n          }\n        }\n        waitingDrain = false\n      }\n      const send = (frame: string): void => {\n        if (done) return\n        if (!waitingDrain && pendingFrames.length === 0) {\n          const result = tryWrite(frame)\n          // 已写入（含「越过高水位」这一种）：**不许再排一遍**，否则 drain 时会重写\n          if (result === 'pressure') waitingDrain = true\n          return\n        }\n        pendingFrames.push(frame)\n        pendingBytes += frame.length\n        if (pendingBytes > MAX_PENDING_BYTES) {\n          if (overflow === 'drop') {\n            dropOldestFrames()\n            return\n          }\n          /*\n           * 队列溢出 = 客户端消费速度跟不上产出（D133）：收尾前补一条 end，\n           * 让客户端知道「是主机侧积压」而不是把它当成正常结束。静默 res.end()\n           * 会被 EventSource 判为流正常结束并自动重连——而自动重连复用带 tail\n           * 的 URL，服务端就会把历史整段重推一遍（重复回填）。\n           */\n          pendingFrames.push(sseFrame('end', { reason: 'output-limit', code: null }))\n          finish()\n        }\n      }\n      const sendEvent = (event: string, data: unknown): void => send(sseFrame(event, data))\n\n      const handle = { end: finish }\n      activeStreams.add(handle)\n      res.on?.('close', clientGone)\n      res.on?.('drain', flushPending)\n\n      heartbeat = setInterval(() => send(': ping\\n\\n'), SSE_HEARTBEAT_MS)\n      heartbeat.unref?.()\n\n      try {\n        const code = await options.run(sendEvent, controller.signal)\n        if (done) return\n        sendEvent('end', { reason: options.reason, code, ...(options.endData?.(code) ?? {}) })\n        finish()\n      } catch (error) {\n        if (done) return\n        sendEvent('error', { message: error instanceof Error ? error.message : String(error) })\n        finish()\n      }\n    }\n\n    /* ---------- 配置热应用 ---------- */\n\n    /**\n     * 逐字段比较目标列表（含凭证）：凭证变了，已开的流按旧凭据在跑，也要收尾。\n     * **顺序无关**（D108）：面板上重排一次目标不该被当成「目标变了」而收流 —— 那会把\n     * 在途的 docker pull 一起 abort 掉（正是 D09 要消除的「一次白拉」）。\n     */\n    const sameTargets = (a: DockerTarget[], b: DockerTarget[]): boolean => {\n      if (a.length !== b.length) return false\n      const byName = new Map(b.map((item) => [item.name, item]))\n      return a.every((item) => {\n        const other = byName.get(item.name)\n        if (other === undefined) return false\n        return item.kind === other.kind\n          && item.book === other.book\n          && item.host === other.host\n          && item.port === other.port\n          && item.username === other.username\n          && item.auth === other.auth\n          && item.keyPath === other.keyPath\n          && item.password === other.password\n          && item.passphrase === other.passphrase\n          && item.agentForward === other.agentForward\n      })\n    }\n\n    const applySection = (section: Record<string, unknown>, options?: { forceRefreshTools?: boolean }): void => {\n      const before = live\n      // 能力开关的**配置值**单独记（D141）：section 里没提到它就保持原样（`{}` = 只重算、不改配置）\n      if (section.allowMutations !== undefined) configuredCapabilities.allowMutations = section.allowMutations === true\n      if (section.allowExec !== undefined) configuredCapabilities.allowExec = section.allowExec === true\n      // hostKeys 只在显式传入时覆盖（避免把 TOFU 运行期新增的记录冲掉）\n      // 能力两项用**配置值**覆盖折叠后的 live：否则重算的输入就是折叠后的 false（见 configuredCapabilities）\n      const merged: Record<string, unknown> = { ...live, ...section, ...configuredCapabilities }\n      if (section.hostKeys === undefined) merged.hostKeys = live.hostKeys\n      live = normalizeConfig(merged)\n      /*\n       * 执行通道相关的键**变了**才收流（D09）：TOFU 落盘会走到这里（hostKeys 变化、\n       * 其余不变），此前无差别 closeAllStreams 会把刚开的日志 FOLLOW 掐断、把在途的\n       * docker pull abort 掉——一次白拉。浏览器侧 EventSource 虽会自动重连，但拉取\n       * 不会自己重来。\n       */\n      // 能力开关被**撤销**时也必须收流（D84）：在途的 /images/pull/stream 是写操作，\n      // 关掉「允许变更操作」就该立刻停手（旧代码无条件收流，D09 收窄条件时漏了这条）。\n      const mutationsRevoked = before.allowMutations && !live.allowMutations\n      if (before.enabled !== live.enabled || before.dockerBin !== live.dockerBin || !sameTargets(before.targets, live.targets) || mutationsRevoked) {\n        closeAllStreams()\n      }\n      // 工具注册面受启用态 / 能力开关 / **目标列表**影响；dockerBin 不改变工具清单但影响执行，\n      // 一起重注册是幂等的，保守带上。forceRefreshTools 给「保存路径」用：上一次注册\n      // 可能只成功了一部分，重存同一份配置也要能重试（D107）。\n      // 目标列表必须算进来：零目标时只注册两条空态工具（见 ZERO_TARGET_TOOLS），配好目标后\n      // 不在这里补注册，就得等重启——那正是「配了目标、工具却没有」的那个半吊子状态。\n      if (options?.forceRefreshTools === true\n        || before.enabled !== live.enabled\n        || before.dockerBin !== live.dockerBin\n        || before.allowMutations !== live.allowMutations\n        || before.allowExec !== live.allowExec\n        || !sameTargets(before.targets, live.targets)) {\n        refreshTools()\n      }\n      if (before.enabled !== live.enabled || before.announceToAgent !== live.announceToAgent) {\n        refreshAnnouncement()\n      }\n      console.log(`[dsh-docker] config applied (enabled=${String(live.enabled)}, bin=${live.dockerBin}, targets=${String(live.targets.length)}, allowMutations=${String(live.allowMutations)}, allowExec=${String(live.allowExec)})`)\n    }\n\n    /*\n     * 就地提权（见 kit 的 elevation.ts）：页内点开关 → 在宿主上落地一个随机名确认文件 → 授权。\n     *\n     * `onGrantChange` 是这一整段里**最容易漏、也最要紧**的一下：授权到达与撤销都必须重算 live。\n     *   - 授权侧：配置开关可能**早就**是 true（用户先打开过、当时没授权，于是 live.allowMutations\n     *     被折叠成 false），授权到了却不重算，症状就是「开关亮着、工具却没注册」；\n     *   - 撤销侧：不重算会留下「记录没了、工具还开着」，还要收掉在途的写流（D84）。\n     * `applySection({})` 用当前 live 兜底再归一化一次即可（normalizeConfig 会重新问 capabilityGranted）。\n     */\n    const elevation = createElevationManager({\n      confirmDir: paths.confirmDir,\n      store: grantStore,\n      logger,\n      logPrefix: '[dsh-docker]',\n      onGrantChange: () => {\n        applySection({}, { forceRefreshTools: true })\n      },\n    })\n    ctx.effect(() => {\n      return () => {\n        elevation.dispose()\n      }\n    }, 'dsh-docker: elevation cleanup')\n\n    /* ---------- agent 工具 ---------- */\n\n    let toolsApi: ToolsLike | undefined\n    let toolDisposers: Array<() => void> = []\n    let registeredNames: string[] = []\n\n    /*\n     * `docker_targets` 的一行。**render 与 execute 共用这一份形状**：两处各写一遍时，\n     * 加字段只改到一侧——render 读不到（或 schema 漏声明，被宿主 `additionalProperties: false`\n     * 挡掉整条结果）。D170 的 `book` 就是这么加上来的，所以先把它抽成类型。\n     */\n    type ToolTargetRow = {\n      name: string\n      kind: string\n      label: string\n      /**\n       * SSH 目标引用的 tty 连接簿条目名（D170）。**仅当配置里真的引用了条目才出现**：\n       * 内联 host/username 的目标没有名字可报，不能凭空编一个；本机目标同样没有。\n       */\n      book?: string\n      ok?: boolean\n      error?: string\n      serverVersion?: string\n    }\n\n    const renderTargets = (rows: ToolTargetRow[]): string => {\n      if (rows.length === 0) return '尚未配置任何 Docker 目标（插件配置 → Docker 容器面板 → 目标）。'\n      return 'Docker 目标：' + rows.map((row) => {\n        const state = row.ok === undefined ? '' : row.ok ? ' [可达]' : ` [不可用：${row.error ?? '未知'}]`\n        const version = row.serverVersion === undefined ? '' : ` docker ${row.serverVersion}`\n        // 连接簿条目名紧跟在 `user@host` 之后：它就是「同一台主机在 tty 那边叫什么」（D170）\n        const book = row.book === undefined ? '' : `（连接簿 ${row.book}）`\n        return `\\n- ${row.name} (${row.kind}) ${row.label}${book}${version}${state}`\n      }).join('')\n    }\n\n    /**\n     * 容器行 → 一行文本。入参是**工具 schema 的扁平形状**（不是领域类型 `ContainerSummary`）：\n     * `ports` 已经是拼好的字符串、id 在 `id` 上、可省字段用 `undefined` 表示「无」。\n     *\n     * 这里踩过一次：渲染器按领域类型写（`row.ports.map(...)` / `row.shortId` /\n     * `row.health === null`），而工具返回的是扁平形状——于是 `ports.map is not a function`\n     * 直接崩、`id=undefined`。render 的入参是 `unknown` + 一个不受检查的 `as` 断言，\n     * 所以 tsc 抓不到。现在两侧共用下面这些 Tool*Row 类型，形状一变就编译报错。\n     */\n    const renderPsRow = (row: ToolPsRow): string => {\n      const ports = row.ports === undefined || row.ports === '' ? '' : ' ports=' + row.ports\n      const health = row.health === undefined ? '' : ` health=${row.health}`\n      const compose = row.composeProject === undefined ? '' : ` compose=${row.composeProject}/${row.composeService ?? '-'}`\n      return `\\n- ${row.name} [${row.state}]${health} image=${row.image}${ports}${compose} id=${row.id}`\n    }\n\n    /** 跨目标容器渲染：按目标分组，失败的目标单独一行说明（部分成功也要可读）。 */\n    const renderAggregatedContainers = (\n      groups: Array<{ target: string; label: string; ok: boolean; error?: string; containers?: ToolPsRow[]; total?: number; truncated?: boolean }>,\n      args?: unknown,\n    ): string => {\n      if (groups.length === 0) return '尚未配置任何 Docker 目标（插件配置 → Docker 容器面板）。'\n      // 「共 N 个容器」要说总数而不是本页条数：分页后两者不是一回事，混用会把一页当全部\n      const total = groups.reduce((sum, group) => sum + (group.total ?? group.containers?.length ?? 0), 0)\n      const failed = groups.filter((group) => !group.ok)\n      const head = `所有目标共 ${String(total)} 个容器（${String(groups.length)} 个目标${failed.length > 0 ? `，${String(failed.length)} 个不可达` : ''}）：`\n      return head + groups.map((group) => {\n        if (!group.ok) return `\\n\\n■ ${group.target}（${group.label}）— 不可用：${group.error ?? '未知错误'}`\n        const rows = group.containers ?? []\n        /*\n         * 空页的两种成因同样要分开（与单目标的 `emptyListText` 同口径）：offset 翻过头时\n         * 若照抄「— 0 个容器」，模型会当成「这台主机上没有容器」——正是 D12/D42 那类假阴性。\n         */\n        if (rows.length === 0 && (group.total ?? 0) > 0) {\n          return `\\n\\n■ ${group.target}（${group.label}）— 本页没有条目（共 ${String(group.total)} 个，offset 已越过末页，改用更小的 offset 重试）`\n        }\n        // 每组的截断信号单独给（组数不变、组内切页）：某台主机还有下一页时要说出来\n        const note = pagingNote(listPage(args, group.total, group.truncated === true), rows.length)\n        return `\\n\\n■ ${group.target}（${group.label}）— ${String(rows.length)} 个容器${note}` + rows.map(renderPsRow).join('')\n      }).join('')\n    }\n\n    const ATTENTION_LABEL: Record<string, string> = {\n      unhealthy: '不健康',\n      restarting: '反复重启',\n      oom: '被 OOM 杀',\n      'exit-nonzero': '非零退出',\n      dead: '僵死',\n    }\n\n    /** 需关注列表渲染（单目标 / 跨目标共用）。入参同样是**工具扁平形状**，不是 AttentionItem。 */\n    const renderAttention = (\n      groups: Array<{ target: string; label: string; ok: boolean; error?: string; items?: ToolAttentionRow[]; total?: number; truncated?: boolean; degraded?: boolean }>,\n    ): string => {\n      // 零目标不是「一切正常」（D53）：排障入口给出假阴性比报错更糟——与 docker_ps\n      // 的「尚未配置任何 Docker 目标」兜底同款\n      if (groups.length === 0) return '尚未配置任何 Docker 目标（插件配置 → Docker 容器面板）。'\n      const total = groups.reduce((sum, group) => sum + (group.items?.length ?? 0), 0)\n      if (total === 0 && groups.every((group) => group.ok)) return '所有目标上没有需要关注的容器（无 unhealthy / 反复重启 / OOM / 非零退出 / 僵死）。'\n      return `需关注容器共 ${String(total)} 个：` + groups.map((group) => {\n        if (!group.ok) return `\\n\\n■ ${group.target}（${group.label}）— 不可用：${group.error ?? '未知错误'}`\n        const items = group.items ?? []\n        if (items.length === 0) return `\\n\\n■ ${group.target}（${group.label}）— 无异常`\n        // 降级信号的措辞要覆盖全部三种成因（D42/D85）：inspect 整体失败、候选超出检查预算、\n        // 补捞预算被吃满 —— 都是「权威字段按摘要口径」，而不是单纯的 inspect 失败\n        const warn = group.degraded === true ? '（部分条目未取到权威详情：inspect 失败或候选超出检查预算，OOM / 重启次数等按摘要口径）' : ''\n        // 截断信号（D12）：名额按严重度排序后切，超出的不静默\n        const cut = group.truncated === true && group.total !== undefined && group.total > items.length\n          ? `（该目标实际共 ${String(group.total)} 条，已按严重度截断为 ${String(items.length)} 条，可传更大的 limit）`\n          : ''\n        const notes = [warn, cut].filter((part) => part !== '').join(' ')\n        return `\\n\\n■ ${group.target}（${group.label}）${notes === '' ? '' : '\\n' + notes}` + items.map((item) => {\n          const reasons = item.reasons.map((reason) => ATTENTION_LABEL[reason] ?? reason).join(' + ')\n          const extra = [\n            item.exitCode === undefined ? '' : `exit=${String(item.exitCode)}`,\n            item.restartCount === undefined ? '' : `restarts=${String(item.restartCount)}`,\n            item.oomKilled ? 'OOMKilled=true' : '',\n          ].filter((part) => part !== '').join(' ')\n          const health = item.health === undefined ? '' : '/' + item.health\n          return `\\n- ${item.name} [${item.state}${health}] ${reasons} image=${item.image}${extra === '' ? '' : ' ' + extra} id=${item.id}`\n        }).join('')\n      }).join('')\n    }\n\n    const renderContainers = (target: string, rows: ToolPsRow[], page?: ListPage): string => {\n      if (rows.length === 0) return emptyListText('容器', target, page)\n      return listHead('容器', target, page, rows.length) + rows.map(renderPsRow).join('') + pagingNote(page, rows.length)\n    }\n\n    const renderStats = (target: string, rows: ToolStatRow[]): string => {\n      if (rows.length === 0) return `目标 ${target}：没有运行中的容器。`\n      return `目标 ${target} 的资源占用：` + rows.map((row) => `\\n- ${row.name} cpu=${row.cpuPercent === undefined ? '?' : String(row.cpuPercent) + '%'} mem=${row.memUsage} (${row.memPercent === undefined ? '?' : String(row.memPercent) + '%'}) net=${row.netIO} block=${row.blockIO} pids=${row.pids === undefined ? '?' : String(row.pids)}`).join('')\n    }\n\n    const renderEvents = (target: string, since: string, rows: ToolEventRow[]): string => {\n      if (rows.length === 0) return `目标 ${target}：最近 ${since} 没有容器事件。`\n      return `目标 ${target} 的容器事件（最近 ${since}，${String(rows.length)} 条）：` + rows.map((row) => {\n        const at = row.time === undefined ? '--:--:--' : formatEventTime(row.time)\n        const exit = row.exitCode === undefined ? '' : ` exit=${String(row.exitCode)}`\n        const compose = row.composeProject === undefined ? '' : ` compose=${row.composeProject}`\n        return `\\n- ${at} ${row.name} ${row.action}${exit}${compose} image=${row.image}`\n      }).join('')\n    }\n\n    /*\n     * 进程快照的渲染：表头 + 行。0 行时给一句「容器内没有进程」——注意 top 在容器没在\n     * 运行时是**抛错**的（docker 就是这么答的），所以走到这里 0 行只能是 docker 没打印\n     * 任何进程行（极少数运行时）；空列表本身不是错误。\n     */\n    const renderTop = (target: string, row: ToolTopRow): string => {\n      const head = `容器 ${row.name === '' ? row.id : row.name}（id=${row.id}，目标 ${target}）的进程`\n      const rows = row.processes ?? []\n      if (rows.length === 0) return `${head}：容器内没有进程（容器可能未运行）。`\n      const body = rows.map((proc) => {\n        const cell = (value: string | undefined): string => String(value ?? '')\n        return `\\n${cell(proc.pid).padStart(7)} ${cell(proc.ppid).padStart(7)} ${cell(proc.user).padEnd(8)} ${cell(proc.stat).padEnd(4)} ${cell(proc.elapsed).padStart(10)} ${cell(proc.cpu).padStart(5)} ${cell(proc.mem).padStart(5)} ${cell(proc.command)}`\n      }).join('')\n      const cut = row.truncated ? '\\n（进程数超过上限已截断：要全量请在容器内跑 ps）' : ''\n      return `${head}（${String(rows.length)} 个${row.truncated ? '，已截断' : ''}）：\\n     PID    PPID USER     STAT    ELAPSED  CPU%  MEM% COMMAND${body}${cut}`\n    }\n\n    /*\n     * 诊断的渲染：**只给结论**，不把 80 行日志灌进模型上下文（契约 §2）。\n     * 返回值里仍然带着 `logTail` 全量、`evidence` 全字段与 `timeline`，模型要细看可以\n     * 自己读；这里只显示 verdict + findings + 建议 + 日志行数（外加三路降级的提示，\n     * 那是「结论可不可信」的一部分，不能藏）。\n     */\n    /**\n     * 历史压成**一行**（不逐条铺样本）：模型要的是「它在变坏吗」的结论，不是 10 行时间戳。\n     *\n     * 时间只保留到分钟（`2026-11-03 07:12`）：秒对趋势判断没有意义，却会把这一行撑长两倍。\n     */\n    const historyLine = (history: ToolDiagnosisHistory | undefined): string => {\n      if (history === undefined || history.samples.length === 0) return ''\n      const trend = history.trend\n      const from = history.samples[0]?.at ?? ''\n      const to = history.samples[history.samples.length - 1]?.at ?? ''\n      const short = (iso: string): string => iso.replace('T', ' ').slice(0, 16)\n      const window = from === '' || to === '' ? '' : `（最早 ${short(from)} → 最近 ${short(to)}）`\n      const note = history.recorded ? '' : '；本次与上一条重复，未追加'\n      return `\\n历史 ${String(trend.count)} 次${window}：${trend.verdict.summary}${note}`\n    }\n\n    const renderDiagnosis = (target: string, row: ToolDiagnosisRow): string => {\n      const verdict = row.verdict ?? { severity: '?', code: '?', summary: '' }\n      // 标题里用短 id（与 docker_inspect 的 shortId 口径一致）：全量 64 位在返回值里，不占正文\n      const shortId = row.id.length > 12 ? row.id.slice(0, 12) : row.id\n      const head = `容器 ${row.name === '' ? shortId : row.name}（id=${shortId}，目标 ${target}）诊断结论：**[${verdict.severity}] ${verdict.summary}**（${verdict.code}）`\n      const findings = (row.findings ?? []).length === 0\n        ? '\\n判据：没有命中任何问题判据。'\n        : `\\n判据（${String(row.findings.length)} 条）：` + row.findings.map((finding) => `\\n- [${finding.severity}] ${finding.title}：${finding.detail}`).join('')\n      const suggestions = (row.suggestions ?? []).length === 0\n        ? ''\n        : '\\n建议：' + row.suggestions.map((item) => `\\n- ${item}`).join('')\n      const evidence = row.evidence ?? {}\n      const logLines = evidence.logLines === undefined ? '未取到' : `${String(evidence.logLines)} 行`\n      const errorLines = evidence.errorLines === undefined ? '未取到' : `${String(evidence.errorLines)} 行`\n      const foot = `\\n日志：抓取 ${logLines}（疑似报错 ${errorLines}），时间线 ${String((row.timeline ?? []).length)} 条；证据全字段与日志原文在返回值里（要更多日志 / 找关键词用 docker_logs_grep）。`\n      return head + findings + suggestions + historyLine(row.history) + foot\n    }\n\n    /*\n     * 磁盘占用：四行汇总 + 可回收最多的镜像（前 10）+ 一句判据。\n     *\n     * 「可回收」只算 `containers === 0` 的镜像——镜像的「独占大小」只有在没有容器使用时\n     * 才真的能回收；还在用的镜像删了会牵连容器。这句话必须写出来，否则模型看到一张\n     * 「大镜像」表就建议用户 `image prune`。\n     */\n    const renderDiskUsage = (target: string, row: ToolDiskRow): string => {\n      const lines = [`目标 ${target} 的磁盘占用（docker system df）：`]\n      for (const item of row.summary ?? []) {\n        lines.push(`- ${item.type}：${String(item.totalCount)} 个（活跃 ${String(item.active)}）占用 ${item.size}，可回收 ${item.reclaimable}`)\n      }\n      if (row.degraded) {\n        lines.push(`\\n明细未取到：${row.degradedReason ?? '未知原因'}（汇总仍可用）`)\n        return lines.join('\\n')\n      }\n      const unused = (row.images ?? []).filter((image) => image.containers === 0).slice(0, 10)\n      const used = (row.images ?? []).filter((image) => image.containers > 0).length\n      lines.push('\\n可回收最多的镜像（独占大小降序，只列没有被任何容器使用的）：')\n      if (unused.length === 0) {\n        lines.push(`- （没有未被使用的镜像；还有 ${String(used)} 个镜像在用）`)\n      } else {\n        lines.push(unused.map((image) => `- ${image.repository === '' ? image.id : `${image.repository}:${image.tag}`} 独占 ${image.uniqueSize}（大小 ${image.size}）`).join('\\n'))\n      }\n      lines.push('\\n删之前先看 `containers` 是不是 0：0 才是没人用，>0 的镜像删了会牵连容器。')\n      if (row.truncated.images || row.truncated.volumes || row.truncated.buildCache) {\n        lines.push(`明细已截断（镜像 ${String(row.images.length)}/${String(row.totals.images)}、卷 ${String(row.volumes.length)}/${String(row.totals.volumes)}、构建缓存 ${String(row.buildCache.length)}/${String(row.totals.buildCache)}）；面板的磁盘页可看全量。`)\n      }\n      return lines.join('\\n')\n    }\n\n    /*\n     * 等价 docker run：命令用**围栏块**原样给出（可直接复制），后面才列提醒。\n     *\n     * 为什么不折行或加省略：这条命令的全部价值就是「能复制粘贴后跑起来」，\n     * 任何为了排版做的改动都会让它变成一条错的命令。\n     */\n    const renderRunCommand = (target: string, row: ToolRunCommandRow): string => {\n      const head = `容器 ${row.name}（id=${row.id.slice(0, 12)}，目标 ${target}）的等价 docker run——**只生成命令，没有执行任何操作**：`\n      const body = '```sh\\n' + (row.command === '' ? '（命令生成失败）' : row.command) + '\\n```'\n      const warnings = (row.warnings ?? []).length === 0\n        ? ''\n        : '\\n提醒：' + row.warnings.map((item) => `\\n- ${item}`).join('')\n      const secrets = (row.secretKeys ?? []).length === 0\n        ? ''\n        : `\\n可能含凭证的环境变量键：${row.secretKeys.join('、')}（命令里是原值，贴出去前先确认）`\n      const omitted = (row.omitted ?? []).length === 0\n        ? ''\n        : '\\n故意没还原（需要你手动补）：' + row.omitted.map((item) => `\\n- ${item}`).join('')\n      return `${head}\\n${body}${warnings}${secrets}${omitted}`\n    }\n\n    const renderDetail = (detail: ContainerDetail): string => {\n      const lines = [\n        `容器 ${detail.name}（${detail.shortId}）`,\n        `- 状态：${detail.state}${detail.health === null ? '' : ' / ' + detail.health}${detail.status === '' ? '' : '（' + detail.status + '）'}`,\n        `- 镜像：${detail.image}`,\n        `- 启动：${detail.startedAt ?? '—'}  结束：${detail.finishedAt ?? '—'}`,\n        `- 退出码：${detail.exitCode === null ? '—' : String(detail.exitCode)}  重启次数：${detail.restartCount === null ? '—' : String(detail.restartCount)}  重启策略：${detail.restartPolicy ?? '—'}`,\n        `- 端口：${detail.ports.length === 0 ? '—' : detail.ports.map((p) => (p.hostPort === undefined ? `${String(p.containerPort)}/${p.protocol}` : `${p.hostIp ?? ''}:${String(p.hostPort)}→${String(p.containerPort)}/${p.protocol}`)).join(', ')}`,\n        `- 挂载：${detail.mounts.length === 0 ? '—' : detail.mounts.map((m) => `${m.source}→${m.destination}${m.readWrite ? '' : '(ro)'}`).join(', ')}`,\n        `- 网络：${detail.networks.length === 0 ? '—' : detail.networks.map((n) => `${n.name}${n.ip === null ? '' : '(' + n.ip + ')'}`).join(', ')}`,\n        `- 命令：${detail.entrypoint}${detail.command === '' ? '' : ' ' + detail.command}`,\n      ]\n      if (detail.healthLogTail !== null) lines.push(`- 最近健康检查：${detail.healthLogTail}`)\n      return lines.join('\\n')\n    }\n\n    const renderNetworks = (target: string, rows: ToolNetworkRow[], page?: ListPage): string => {\n      if (rows.length === 0) return emptyListText('网络', target, page)\n      return listHead('网络', target, page, rows.length) + rows.map((row) => {\n        const internal = row.internal === true ? ' internal=true' : ''\n        return `\\n- ${row.name} driver=${row.driver} scope=${row.scope}${internal} id=${row.id}`\n      }).join('') + pagingNote(page, rows.length)\n    }\n\n    const renderVolumes = (target: string, rows: ToolVolumeRow[], page?: ListPage): string => {\n      if (rows.length === 0) return emptyListText('卷', target, page)\n      return listHead('卷', target, page, rows.length) + rows.map((row) => {\n        const mount = row.mountpoint === undefined || row.mountpoint === '' ? '' : ` mount=${row.mountpoint}`\n        return `\\n- ${row.name} driver=${row.driver} scope=${row.scope}${mount}`\n      }).join('') + pagingNote(page, rows.length)\n    }\n\n    const renderImages = (target: string, rows: ToolImageRow[], page?: ListPage): string => {\n      if (rows.length === 0) return emptyListText('镜像', target, page)\n      return listHead('镜像', target, page, rows.length) + rows.map((row) => {\n        const created = row.createdSince === undefined || row.createdSince === '' ? '' : ' (' + row.createdSince + ')'\n        return `\\n- ${row.reference} ${row.sizeText}${created} id=${row.id}`\n      }).join('') + pagingNote(page, rows.length)\n    }\n\n    /** 镜像详情 + 构建历史（agent 工具 docker_image_inspect 的可读渲染）。 */\n    const renderImageDetail = (payload: { detail: ImageDetail; history: ImageHistoryEntry[]; historyError: string | null }): string => {\n      const d = payload.detail\n      const title = d.repoTags.length === 0 ? `<none>（${d.shortId}）` : d.repoTags.join(', ')\n      const lines = [\n        `镜像 ${title}`,\n        `- ID：${d.id}`,\n        `- 大小：${d.size === null ? '—' : formatBytes(d.size)}${d.virtualSize === null || d.virtualSize === d.size ? '' : `（含父层 ${formatBytes(d.virtualSize)}）`}`,\n        `- 创建：${d.created === '' ? '—' : d.created}`,\n        `- 平台：${d.os === '' && d.architecture === '' ? '—' : `${d.os}/${d.architecture}`}`,\n        `- 层：${String(d.layerCount)} 层`,\n        `- 入口：${(d.entrypoint + ' ' + d.command).trim() || '—'}`,\n        ...(d.exposedPorts.length === 0 ? [] : [`- 暴露端口：${d.exposedPorts.join(', ')}`]),\n        ...(d.repoDigests.length === 0 ? [] : [`- digest：${d.repoDigests.join(', ')}`]),\n      ]\n      if (payload.historyError !== null) lines.push(`- 构建历史：读取失败（${payload.historyError}）`)\n      else if (payload.history.length === 0) lines.push('- 构建历史：无')\n      else {\n        lines.push(`- 构建历史（${String(payload.history.length)} 步，从新到旧）：`)\n        for (const step of payload.history.slice(0, 30)) {\n          lines.push(`  · ${step.shortId} ${step.createdSince} ${step.sizeText} ${step.createdBy.slice(0, 160)}`)\n        }\n        if (payload.history.length > 30) lines.push(`  …（其余 ${String(payload.history.length - 30)} 步略）`)\n      }\n      return lines.join('\\n')\n    }\n\n    /** 重新注册 agent 工具（能力开关变化时调用；幂等）。 */\n    const refreshTools = (): void => {\n      for (const dispose of toolDisposers) {\n        try {\n          dispose()\n        } catch {\n          /* 工具已注销 */\n        }\n      }\n      toolDisposers = []\n      registeredNames = []\n      const tools = toolsApi\n      if (tools === undefined) return\n      // 插件禁用（设置卡片关掉「启用插件」）时不注册任何工具：运行期关掉也要立刻生效\n      if (!live.enabled) return\n      // 文案要跟语义一致（D46）：`*` 聚合只有 docker_ps / docker_attention 真支持，\n      // 其余 12 个单目标工具省略时只在「恰好一个目标」时回落、多目标则报 target 必填\n      const targetParam = { type: 'string', description: '目标名（docker_targets 列出；只有一个目标时可省略。`*` 仅 docker_ps / docker_attention 支持，其他工具请传具体目标名）' } as const\n\n      /*\n       * 单个工具注册失败不该把整批带下去（D107）：以前 add 直接抛，调用方（applySection）\n       * 也就抛了，结果是「旧工具已全拆 + 新工具只注册了一半」，而重存同一份配置又因为\n       * 差异判定不再触发 refreshTools —— 半套状态一直缺到重启。现在逐条兜住并汇总，\n       * 下次配置变更（或保存路径的 forceRefreshTools）会自然重试。\n       */\n      const failures: string[] = []\n      const add = (toolName: string, definition: unknown): void => {\n        /*\n         * 零目标闸（见 ZERO_TARGET_TOOLS）：其余工具没有可寻址的目标，注册了只会让模型\n         * 白试一次；放在 add 里过滤，是为了保住注册顺序、失败汇总与 registeredNames 的\n         * 实况语义（它们仍然是「这次真正注册了什么」的如实记录）。\n         */\n        if (live.targets.length === 0 && !ZERO_TARGET_TOOLS.has(toolName)) return\n        try {\n          toolDisposers.push(tools.register(definition))\n          registeredNames.push(toolName)\n        } catch (error) {\n          failures.push(`${toolName}: ${error instanceof Error ? error.message : String(error)}`)\n        }\n      }\n\n      add('docker_targets', defineTool({\n        name: 'docker_targets',\n        // 只读工具：与同轮其它工具并发执行（宿主默认把未声明的工具当独占，见项目级 ROADMAP 第 4 项）\n        isConcurrencySafe: () => true,\n        description: '列出已配置的 Docker 目标（本机 / SSH 主机），可选探测每个目标的 docker daemon 是否可达；SSH 目标会带出它引用的 tty 连接簿条目名（book，可直接用于 sftp_* 的 book）。其他 docker_* 工具的 target 参数取自这里。',\n        parameters: { probe: { type: 'boolean', description: 'true 时逐个探测 docker 版本与 daemon 可达性（SSH 目标会建连接，较慢）' } },\n        output: {\n          schema: {\n            type: 'object',\n            additionalProperties: false,\n            properties: {\n              targets: {\n                type: 'array',\n                required: true,\n                items: {\n                  type: 'object',\n                  additionalProperties: false,\n                  properties: {\n                    name: { type: 'string', required: true },\n                    kind: { type: 'string', required: true },\n                    label: { type: 'string', required: true },\n                    // D170：目标引用的 tty 连接簿条目名（内联 host/username 的目标没有这个字段）\n                    book: { type: 'string' },\n                    ok: { type: 'boolean' },\n                    error: { type: 'string' },\n                    serverVersion: { type: 'string' },\n                  },\n                },\n              },\n            },\n          },\n          render: (_args: unknown, value: unknown) => {\n            const rows = (value as { targets?: ToolTargetRow[] }).targets ?? []\n            return [{ type: 'text', text: renderTargets(rows) }]\n          },\n        },\n        async execute(args: unknown): Promise<{ targets: ToolTargetRow[] }> {\n          const input = (args ?? {}) as { probe?: unknown }\n          const books = readTtyBooks(settingsApi)\n          const rows: ToolTargetRow[] = []\n          for (const target of targetsNow()) {\n            /*\n             * `book` 只在目标**真的引用了连接簿条目**时带出（D170）：`resolveTarget` 内部靠它\n             * 查表，但工具输出里从来没有它——于是模型手里只剩 `user@host`，而 tty / sftp_* 认的\n             * 是**条目名**。两边不同名时（目标名 `host-a`、条目名 `KB_JUMP_01` 这种）猜不出来，\n             * 只能赌一次，赌错就是「连接簿中不存在」。本机目标与内联字段目标一律不带。\n             */\n            const book = target.book ?? ''\n            const bookField = target.kind === 'ssh' && book !== '' ? { book } : {}\n            const { resolved, error } = resolveTarget(target, books)\n            if (resolved === undefined) {\n              rows.push({ name: target.name, kind: target.kind, label: '解析失败', ...bookField, ok: false, error: error ?? '未知错误' })\n              continue\n            }\n            const label = resolved.kind === 'local' ? '本机' : sshTarget(resolved.spec as SshSpec)\n            if (input.probe !== true) {\n              rows.push({ name: target.name, kind: target.kind, label, ...bookField })\n              continue\n            }\n            const { api } = apiFor(target.name)\n            if (api === undefined) {\n              rows.push({ name: target.name, kind: target.kind, label, ...bookField, ok: false, error: '无法构造执行通道' })\n              continue\n            }\n            const probe = await api.probe()\n            // serverVersion 随 probe 回传（D48）：README 承诺「探测 docker 版本」，\n            // probe() 本来就返回了它，只是这里被丢掉了\n            rows.push({\n              name: target.name,\n              kind: target.kind,\n              label,\n              ...bookField,\n              ok: probe.ok,\n              ...(probe.ok ? { ...(probe.serverVersion === null ? {} : { serverVersion: probe.serverVersion }) } : { error: probe.error ?? '未知错误' }),\n            })\n          }\n          return { targets: rows }\n        },\n      }))\n\n      add('docker_connect_local', defineTool({\n        name: 'docker_connect_local',\n        // 只读之外的唯一副作用是**写本插件自己的配置**，没有别的写路径；并发调用被 connectLocal 的幂等语义收敛\n        isConcurrencySafe: () => true,\n        description: '添加或复用本机 Docker 目标并探测 daemon，返回目标名、是否新建和连接状态及失败原因。保留已有 SSH 配置；不启动或安装 Docker，不改变 context 或能力授权。随后将返回的 name 作为 docker_ps 等工具的 target。',\n        parameters: {},\n        output: {\n          schema: {\n            type: 'object',\n            additionalProperties: false,\n            properties: {\n              name: { type: 'string', required: true },\n              kind: { type: 'string', required: true },\n              created: { type: 'boolean', required: true },\n              saved: { type: 'boolean', required: true },\n              reachable: { type: 'boolean', required: true },\n              message: { type: 'string', required: true },\n              serverVersion: { type: 'string' },\n            },\n          },\n          render: (_args: unknown, value: unknown) => {\n            const row = value as ConnectLocalResult\n            return [{\n              type: 'text',\n              text: `${row.message}\\n后续查询请传 target: ${JSON.stringify(row.name)}`,\n            }]\n          },\n        },\n        async execute(): Promise<ConnectLocalResult> {\n          const outcome = await connectLocal()\n          if (!outcome.ok) throw new Error(outcome.error)\n          return outcome.result\n        },\n      }))\n\n      add('docker_ps', defineTool({\n        name: 'docker_ps',\n        // 只读工具：与同轮其它工具并发执行（宿主默认把未声明的工具当独占，见项目级 ROADMAP 第 4 项）\n        isConcurrencySafe: () => true,\n        description: '列出容器（默认只列运行中的；all:true 含已停止）。**target 传 `*` = 一次列出所有目标**（跨主机，按目标分组返回，单个目标不可达不影响其他目标）。排障第一步。注意：`ports` 为空**不等于**「没暴露端口」——host 网络容器的端口就是宿主机端口、ps 里没有映射，这种情况会给 `net` 字段（如 `net:\"host\"`），别为此再逐个 docker_inspect。',\n        parameters: {\n          target: { type: 'string', description: '目标名；传 `*` 或省略（仅一个目标时）表示当前目标/全部目标（docker_targets 列出）' },\n          all: { type: 'boolean', description: 'true 时包含已停止容器（默认 false）' },\n          limit: pageParams.limit,\n          offset: pageParams.offset,\n        },\n        output: {\n          schema: {\n            type: 'object',\n            additionalProperties: false,\n            properties: {\n              target: { type: 'string' },\n              total: { type: 'number' },\n              truncated: { type: 'boolean' },\n              containers: {\n                type: 'array',\n                items: {\n                  type: 'object',\n                  additionalProperties: false,\n                  properties: {\n                    id: { type: 'string', required: true },\n                    name: { type: 'string', required: true },\n                    image: { type: 'string', required: true },\n                    state: { type: 'string', required: true },\n                    status: { type: 'string', required: true },\n                    health: { type: 'string' },\n                    ports: { type: 'string' },\n                    net: { type: 'string' },\n                    composeProject: { type: 'string' },\n                    composeService: { type: 'string' },\n                  },\n                },\n              },\n              groups: {\n                type: 'array',\n                items: {\n                  type: 'object',\n                  additionalProperties: false,\n                  properties: {\n                    target: { type: 'string', required: true },\n                    label: { type: 'string', required: true },\n                    ok: { type: 'boolean', required: true },\n                    error: { type: 'string' },\n                    // 组内分页（T1）：组数不变、每组各自切，所以 total / truncated 也在组上\n                    total: { type: 'number' },\n                    truncated: { type: 'boolean' },\n                    containers: {\n                      type: 'array',\n                      items: {\n                        type: 'object',\n                        additionalProperties: false,\n                        properties: {\n                          id: { type: 'string', required: true },\n                          name: { type: 'string', required: true },\n                          image: { type: 'string', required: true },\n                          state: { type: 'string', required: true },\n                          status: { type: 'string', required: true },\n                          health: { type: 'string' },\n                          ports: { type: 'string' },\n                          net: { type: 'string' },\n                          composeProject: { type: 'string' },\n                          composeService: { type: 'string' },\n                        },\n                      },\n                    },\n                  },\n                },\n              },\n            },\n          },\n          render: (args: unknown, value: unknown) => {\n            const v = value as {\n              target?: string\n              containers?: ToolPsRow[]\n              total?: number\n              truncated?: boolean\n              groups?: Array<{ target: string; label: string; ok: boolean; error?: string; containers?: ToolPsRow[]; total?: number; truncated?: boolean }>\n            }\n            if (Array.isArray(v.groups)) return [{ type: 'text', text: renderAggregatedContainers(v.groups, args) }]\n            return [{ type: 'text', text: renderContainers(v.target ?? '?', v.containers ?? [], listPage(args, v.total, v.truncated === true)) }]\n          },\n        },\n        async execute(args: unknown): Promise<{\n          target?: string\n          containers?: ToolPsRow[]\n          total?: number\n          truncated?: boolean\n          groups?: Array<{ target: string; label: string; ok: boolean; error?: string; containers?: ToolPsRow[]; total?: number; truncated?: boolean }>\n        }> {\n          const input = (args ?? {}) as { target?: unknown; all?: unknown; limit?: unknown; offset?: unknown }\n          const window = pageWindow(input)\n          const isAll = typeof input.target === 'string' && input.target.trim() === '*'\n          const toRow = (row: ContainerSummary): ToolPsRow => ({\n            // 短 ID（D47）：docker_attention 已是 shortId，同一字段跨工具宽度要一致\n            //（ps 带 --no-trunc，完整 64 位既与 README 的「短 ID」矛盾也多烧 token）\n            id: row.shortId,\n            name: row.name,\n            image: row.image,\n            state: row.state,\n            status: row.status,\n            ...(row.health === null ? {} : { health: row.health }),\n            ports: row.ports.map((p) => (p.hostPort === undefined ? `${String(p.containerPort)}/${p.protocol}` : `${String(p.hostPort)}→${String(p.containerPort)}/${p.protocol}`)).join(','),\n            // 端口为空才补 net（D131）：host 网络容器的端口即宿主机端口、ps 没有映射，\n            // 空 ports 与「没暴露端口」否则无法区分。有映射时不加，避免每行都变长。\n            ...(row.ports.length === 0 && row.networks.length > 0 ? { net: row.networks.join(',') } : {}),\n            ...(row.composeProject === null ? {} : { composeProject: row.composeProject }),\n            ...(row.composeService === null ? {} : { composeService: row.composeService }),\n          })\n          if (isAll || (input.target === undefined && targetsNow().length > 1)) {\n            const names = targetsFor('*')\n            const collected = await aggregateAcrossTargets(names, (targetApi) => targetApi.listContainers(input.all === true))\n            // 跨目标分页在**组内**切（T1）：组数与「哪些目标不可达」都保持不变，\n            // 每组带自己的 total / truncated —— 否则一个目标 150 个容器会把别组挤没\n            return {\n              groups: collected.map((group) => {\n                const paged = group.data === undefined ? undefined : paginate(group.data, window)\n                return {\n                  target: group.target,\n                  label: group.label,\n                  ok: group.ok,\n                  ...(group.error === undefined ? {} : { error: group.error }),\n                  ...(paged === undefined ? {} : {\n                    containers: paged.rows.map(toRow),\n                    total: paged.total,\n                    truncated: paged.truncated,\n                  }),\n                }\n              }),\n            }\n          }\n          const picked = pickTarget(input.target)\n          if (picked.name === undefined) throw new Error(picked.error ?? '无效的 target')\n          const { api } = apiFor(picked.name)\n          if (api === undefined) throw new Error(resolveByName(picked.name).error ?? '无法构造执行通道')\n          const containers = await api.listContainers(input.all === true)\n          const paged = paginate(containers, window)\n          return { target: picked.name, containers: paged.rows.map(toRow), total: paged.total, truncated: paged.truncated }\n        },\n      }))\n\n      add('docker_attention', defineTool({\n        name: 'docker_attention',\n        // 只读工具：与同轮其它工具并发执行（宿主默认把未声明的工具当独占，见项目级 ROADMAP 第 4 项）\n        isConcurrencySafe: () => true,\n        description: '列出「需要关注」的容器：不健康（unhealthy）/ 反复重启 / 被 OOM 杀 / 非零退出 / 僵死。target 传 `*` 时**跨所有目标聚合**（单目标不可达不影响其他目标）。排障入口：不确定从哪台机器看起时先调它。',\n        parameters: {\n          target: { type: 'string', description: '目标名；传 `*` 表示全部目标（docker_targets 列出）' },\n          limit: { type: 'number', description: '每个目标最多返回多少条（1~500，默认 100）' },\n        },\n        output: {\n          schema: {\n            type: 'object',\n            additionalProperties: false,\n            properties: {\n              target: { type: 'string' },\n              total: { type: 'number' },\n              truncated: { type: 'boolean' },\n              degraded: { type: 'boolean' },\n              items: {\n                type: 'array',\n                items: {\n                  type: 'object',\n                  additionalProperties: false,\n                  properties: {\n                    id: { type: 'string', 