      "content": "/* eslint-disable */\n/**\n * @hyzyn/dsh-docker — 浏览器半体：侧边栏「容器」入口 + Docker 面板 + 设置卡片。\n * 由 scripts/build-client.mjs 用 esbuild 打包为单文件 IIFE，经\n * window.__ModuleLoader__.load 注册；React / ReactDOM 取自宿主（共用同一实例）。\n *\n * 能力：\n *   - 目标切换（本机 / SSH 主机，来自宿主 /api/dsh-docker/targets）\n *   - 容器卡片：状态徽章、镜像、compose 项目、端口；搜索 + 状态筛选 + 含已停止\n *   - 详情抽屉：概览（inspect）/ 日志（tail、时间戳、过滤、下载、FOLLOW 实时流）/ 统计（CPU/内存条）\n *   - 生命周期操作（启动 / 停止 / 重启 / 删除）——默认只读，需在设置里开开关\n *   - 一次性 exec（默认关闭，需在设置里开开关）\n *   - 镜像列表（仓库:标签 / 大小 / 创建时间）\n *   - 设置卡片：目标 CRUD、能力开关、参数、TOFU 主机指纹记录\n *\n * 安全约定：面板只渲染宿主返回的数据；破坏性操作一律二次确认；凭证永不回显\n * （宿主只回 passwordSet / passphraseSet 布尔）。\n */\nimport dockerCss from './docker.css'\nimport { bookSessionHost, pickTargetByHost, sessionHostPort, staleBookRef } from './session-target.js'\nimport { currentSessionIdOf } from './current-session.js'\nimport { createLogBuffer, splitLogLines } from './log-buffer.js'\nimport { createLogWindow, LOG_ROW_ESTIMATE_PX, LOG_WINDOW_OVERSCAN, LOG_HEIGHT_CACHE_LIMIT } from './log-window.js'\nimport { subscribeLogStream, reconnectTail, LOG_RECONNECT_BASE_MS, LOG_RECONNECT_MAX_MS } from './log-stream.js'\nimport { upsertElevationRecord, removeElevationRecord, markElevationGranted, pruneElevationRecords, buildMergedElevationText, mergeElevationCommands, joinElevationCommands, shouldOfferMerge } from './elevation.js'\n\n/**\n * 「复制全部」按钮的反馈归属哨兵键：能力名不会取这个值，所以它与单条按钮的反馈天然不串。\n * （`copiedKey` 逐能力隔离见卡片里那段注释。）\n */\nconst ELEVATION_COPY_ALL = '__all__'\n\n/* ================================ 国际化 ================================ */\n\n/*\n * 界面文案走宿主 `@deepseek-ai/dsh-client-locale` 的目录（方案见 docs/i18n.md）。\n * 目录**内联在本文件**（不是单独一个模块）：scripts/build-client.mjs 用 esbuild 打包单文件，\n * 目录另起文件只会多一处构建面；下面这一对目录由 `scripts/check-i18n.mjs` 静态校验——\n * **文案里不许出现字面 `**`**（D143）：浏览器半体没有 markdown 渲染器，用户看到的就是两个星号；\n * 强调用「」/ “” 或直接换行，`check-i18n.mjs` 不查这一条，只能靠人守。\n * zh/en 键集一致、`{name}` 占位符两边一致、代码里 `t('…')` 用到的键必须在这里有定义。\n *\n * 兄弟模块（log-stream.js 等）不 import 本文件（会成环），需要 `t` 时**当参数传进去**。\n *\n * **模块级常量里的 `t()` 必须走 getter / 函数**：`t()` 在模块加载时求值等于把当前语言冻住\n * （`installI18n(ctx)` 要等 apply 才跑，语言切换也不会重算）——PICK_PRESETS / ATTENTION_REASONS /\n * LOG_LEVEL_OPTIONS / 导出按钮文案都因此改成了 getter 或取值函数。\n *\n * 不翻的：`console.warn` 的诊断前缀、品牌与技术词（Docker / Compose / CPU / OOM / docker ps 输出）、\n * 路径与语法示例、宿主返回的错误正文，以及「问 Agent」拼给**模型**看的日志片段（agent 面向的文案，\n * 见 docs/i18n.md § 范围纪律）。\n */\n/* ==== dsh-i18n:begin ==== */\nconst I18N_NS = 'docker'\nconst I18N_ZH = {\n  'error.requestFailed': '请求失败',\n  'list.noPorts': '无端口映射',\n  'status.running': '运行中',\n  'status.stopped': '已停止',\n  'status.created': '已创建',\n  'status.paused': '已暂停',\n  'status.restarting': '重启中',\n  'status.removing': '删除中',\n  'status.unknown': '未知',\n  'hint.pickMaxLocal': '最多 {max} 个容器——再多一次读不清，宿主上也会多起几条 logs 进程',\n  'hint.pickMaxSsh': '最多 {max} 个容器——再多一次读不清，SSH 通道也会被占满',\n  'hint.pickMany': '已接近上限，再多就看不清了',\n  'hint.pickAtLeastTwo': '至少选择 2 个容器',\n  'hint.pickBudget': '聚合日志只占一条 SSE（所有选中容器共用一条连接），活动条的事件流另外只占一条',\n  'option.presetAll': '全部可见',\n  'status.unhealthy': '不健康',\n  'status.attention': '需关注',\n  'option.presetSameImage': '同镜像',\n  'option.presetSameProject': '同项目',\n  'status.oomKilled': '被 OOM 杀',\n  'status.dead': '僵死',\n  'status.restartingLoop': '反复重启',\n  'status.exitNonzero': '非零退出',\n  'hint.openDetail': '打开容器详情',\n  'meta.finishedAt': '结束于 ',\n  'meta.startedAt': '启动于 ',\n  'meta.restartCount': '重启次数 ',\n  'meta.exitCode': '退出码 ',\n  'error.unknown': '未知错误',\n  'hint.attentionTruncated': '需关注结果已截断：{targets} 个目标实际共 {total} 条，此处只列出前 {shown} 条',\n  'hint.attentionDegraded': '{count} 个目标的结果已降级（部分容器的详情没取到，OOM / 反复重启可能漏报）',\n  'msg.clauseSep': '；',\n  'list.noTargetsConfigured': '还没有配置 Docker 目标',\n  'hint.overviewNoTargets': '到 插件配置 → Docker 容器面板 添加目标后，总览会在这里一屏汇总全部主机。',\n  'list.loading': '读取中…',\n  'list.allGood': '一切正常',\n  'list.allGoodHint': '所有目标上都没有需要关注的容器（不健康 / 反复重启 / 被 OOM 杀 / 非零退出 / 僵死）。',\n  'field.containerName': '容器名',\n  'field.target': '目标',\n  'field.stat