 }, [tab, logAuto, logIntervalSec, loadLogs, follow])\n\n      /**\n       * 日志实时流生命周期：FOLLOW 打开且有 EventSource 时订阅 SSE。\n       * 切页 / 关面板 / 换容器 / 关 FOLLOW 都会走到 effect 清理（es.close()），\n       * 不留悬挂连接。\n       */\n      useEffect(() => {\n        // active=false = tab 被折叠（S3）：隐藏时不该继续挂着 SSE，白占 SSH 通道；\n        // 展开后这个 effect 会重跑，而建流本来就带 tail，历史自己补回来。\n        if (!active) return undefined\n        if (tab !== 'logs' || !follow) return undefined\n        if (typeof EventSource !== 'function') {\n          setFollowError(t('error.noEventSource'))\n          setFollow(false)\n          return undefined\n        }\n        // 每次重开流都从空缓冲开始，避免把上一次的行混进来\n        followBufRef.current = createLogBuffer({ maxLines: FOLLOW_LINE_LIMIT, maxBytes: FOLLOW_BYTE_LIMIT, maxPendingBytes: LOG_PENDING_MAX })\n        cancelFollowFlush()\n        setFollowLines([])\n        setFollowDropped(false)\n        setFollowError('')\n        setFollowNotice('')\n        // 重开流 = 内容清空重来：贴底状态一并复位（D92），新行到了仍然贴着底\n        logRows.scrollToBottom()\n        setFollowStatus('connecting')\n\n        /**\n         * 分片 → 完整行：docker 的 chunk 不按行切，末段残行留给下一片。\n         * 切分/淘汰都在缓冲里做，这里只负责「有新行 → 排一次合帧」。\n         */\n        const pushChunk = (text) => {\n          if (text === '') return\n          const result = followBufRef.current.pushChunk(text)\n          if (result.appended > 0) scheduleFollowFlush()\n        }\n\n        /** 订阅句柄：onEnd 里要能关掉自己，而它在 subscribeLogStream 返回之前就已定义。 */\n        let subscription = null\n        /*\n         * 断线重连交给 subscribeLogStream（D133）：首连带 tail 补历史，**重连带\n         * tail=0** 只补新行。EventSource 自带的自动重连会复用带 tail 的 URL —— 服务端\n         * 把最后 tail 行当新行再推一遍，客户端就会重复回填（还会挤掉真正的历史）。\n         */\n        subscription = subscribeLogStream({\n          t,\n          buildUrl: (tailNow) => streamUrl('/logs/stream', {\n            target: props.target,\n            id: item.id,\n            tail: String(tailNow),\n            ...(logOptions.timestamps ? { timestamps: '1' } : {}),\n    