addTarget = () => setForm((current) => ({\n        ...current,\n        targets: [...current.targets, { name: t('list.newTargetName', { index: current.targets.length + 1 }), kind: 'local', book: '', host: '', port: 22, username: '', auth: 'agent', keyPath: '', agentForward: false, passwordSet: false, passphraseSet: false }],\n      }))\n\n      const removeTarget = (index) => setForm((current) => ({ ...current, targets: current.targets.filter((_, i) => i !== index) }))\n\n      const removeHostKey = (record) => {\n        removedHostKeysRef.current = [...removedHostKeysRef.current, { host: record.host, port: record.port }]\n        setForm((current) => ({\n          ...current,\n          hostKeys: current.hostKeys.filter((item) => !(item.host === record.host && item.port === record.port)),\n        }))\n      }\n\n      /**\n       * 表单 → 保存 payload。**也是「脏不脏」的比较口径**：只有这些字段会被写进去，所以\n       * 快照里那些只读字段（`*Granted` / `*GrantSource` / `*GrantedAt`）变化不算用户改动——\n       * 否则授权一到，「表单变脏了」会让自动保存白白放弃。\n       */\n      const toPayload = (source) => ({\n        enabled: source.enabled,\n        announceToAgent: source.announceToAgent,\n        dockerBin: source.dockerBin,\n        allowMutations: source.allowMutations,\n        allowExec: source.allowExec,\n        execTimeoutSec: source.execTimeoutSec,\n        pollIntervalSec: source.pollIntervalSec,\n        logTailDefault: source.logTailDefault,\n        maxOutputKb: source.maxOutputKb,\n        targets: source.targets.map((item) => ({\n          name: item.name,\n          kind: item.kind,\n          book: item.book ?? '',\n          host: item.host ?? '',\n          port: Number(item.port) || 22,\n          username: item.username ?? '',\n          auth: item.auth ?? 'agent',\n          keyPath: item.keyPath ?? '',\n          // 空字符串 = 保留原有凭证（宿主按 undefined 处理会覆盖为空，这里显式跳过）\n          ...(item.password === undefined || item.password === '' ? {} : { password: item.password }),\n          ...(item.passphrase === undefined || item.passphrase === '' ? {} : { passphrase: item.passphrase }),\n          agentForward: item.agentForward === true,\n        })),\n        // hostKeys 不整表回传（D10）：服务端并集合并，运行期新增的钉扎不会被表单快照冲掉；\n        // 删除某条记录走显式 hostKeysRemove\n        ...(removedHostKeysRef.current.length > 0 ? { hostKeysRemove: removedHostKeysRef.current } : {}),\n        // 只有「加载到过非空目标、现在被用户删空」才算显式清空；否则宿主会拒绝写入空数组\n        ...(source.targets.length === 0 && loadedCountRef.current > 0 ? { clearTargets: true } : {}),\n      })\n\n      const save = () => {\n        setSaving(true)\n        setMessage({ kind: '', text: '' })\n        const formSnapshot = JSON.stringify(formRef.current)\n        /*\n         * 只记下「这一次真的发出去」的那批删除（D82）。removeHostKey 是**追加**入队的，\n         * 而保存请求飞行期间用户还能继续删——那些新入队的既进不了这次的 payload，也不\n         * 该被响应处理吞掉（hostKeysRemove 是唯一的删除通道，吞掉就等于服务端钉扎永远\n         * 删不掉，而界面因为 D22 的脏检查不回滚，看着像「已经删掉了」）。\n         * 记下发出时的数组引用，响应里按长度前缀切掉即可。\n         */\n        const sentRemovals = removedHostKeysRef.current\n        const payload = toPayload(form)\n        api.saveConfig(payload).then((response) => {\n          /*\n           * 只清「已经发出」的那批（D82）：按发出时的长度切掉前缀，飞行期间新入队的\n           * 删除留着给下一次保存。无条件清空会把它们一起吞掉——服务端钉扎删不掉，\n           * 界面却显示记录已消失、回执写着「已保存并热生效」，属安全相关的静默失败。\n           */\n          removedHostKeysRef.current = removedHostKeysRef.current.slice(sentRemovals.length)\n          primeTargetsCache(response.config)\n          publishConfig(response.config)\n          loadedCountRef.current = Array.isArray(response.config?.targets) ? response.config.targets.length : 0\n          cleanPayloadRef.current = JSON.stringify(toPayload(toCardForm(response.config)))\n          // 请求飞行期间的编辑不能被服务端快照整表回滚（D22）：只在表单没有新改动时同步\n          if (JSON.stringify(formRef.current) === formSnapshot) setForm(toCardForm(response.config))\n          // 目标增删会影响 tty 连接栏按钮：刷新解析后的目标列表\n          void refreshTargetsCache()\n          setMessage(response.warning === undefined\n            ? { kind: 'ok', text: JSON.stringify(formRef.current) === formSnapshot ? t('msg.saved') : t('msg.savedDirty') }\n            : { kind: 'error', text: response.warning })\n        }).catch((error) => {\n          setMessage({ kind: 'error', text: t('error.saveFailed') + error.message })\n        }).finally(() => setSaving(false))\n      }\n\n      /* ---------------- 就地提权（capability elevation） ---------------- */\n\n      /**\n       * 快照 → 表单：能力开关在表单里存**配置值**（用户写下的那个），不是快照里的有效值。\n       *\n       * 为什么必须换：有效值 = 配置 && 已授权。配置开着但没授权时有效值是 false，若拿它当表单值，\n       * 用户一按保存就把配置关掉了——而界面还显示着「未生效」，用户完全看不出发生了什么。\n       */\n      const toCardForm = (config) => ({\n        ...config,\n        allowMutations: config.allowMutationsConfigured === true,\n        allowExec: config.allowExecConfigured === true,\n      })\n\n      /** 只刷新与授权有关的那几个只读字段（**不动**用户正在编辑的字段）。 */\n      const refreshGrantState = () => {\n        api.config().then((payload) => {\n          primeTargetsCache(payload.config)\n          publishConfig(payload.config)\n          setForm((current) => (current === null ? current : {\n            ...current,\n            allowMutationsGranted: payload.config.allowMutationsGranted === true,\n            allowMutationsGrantSource: payload.config.allowMutationsGrantSource ?? null,\n            allowMutationsGrantedAt: Number.isFinite(payload.config.allowMutationsGrantedAt) ? payload.config.allowMutationsGrantedAt : null,\n            allowExecGranted: payload.config.allowExecGranted === true,\n            allowExecGrantSource: payload.config.allowExecGrantSource ?? null,\n            allowExecGrantedAt: Number.isFinite(payload.config.allowExecGrantedAt) ? payload.config.allowExecGrantedAt : null,\n          }))\n        }).catch(() => {\n          /* 刷新失败静默：卡片本身照旧可用，下一次加载会同步 */\n        })\n      }\n\n      /**\n       * 授权到了：把开关写进表单、刷新授权状态，并在「表单本来是干净的」时顺手保存。\n       *\n       * 自动保存只在干净表单下做：保存是**整表**提交，脏表单下自动保存会把用户没打算提交的编辑\n       * 一起写进去。脏的时候只把开关置上并提示「点保存生效」——不替用户做决定。\n       */\n      const finishElevation = (capability) => {\n        /*\n         * **不删记录**，只把它标成已授权并把命令清掉（面板据此消失）。为什么留着这条痕迹：\n         * 合并按钮的存续跟着「面板组里有过几个能力」，不是跟着当前还剩几条命令——两个能力\n         * 都点过之后，其中一个先解锁，按钮要留着把**剩下那条**交给用户（此时再让他回单条面板\n         * 里找命令，等于把刚刚那次「一次粘贴」的动作拆回去）。两个都解锁后组里没有可复制命令，\n         * 按钮自然消失（见 shouldOfferMerge）。\n         *\n         * 反向也成立：「单个 pending → 无合并按钮」——只动过一个开关时组里只有一条记录，\n         * 那条命令就在它自己的面板里，不需要一个「复制全部（1 条）」的按钮。\n         */\n        setElevations((current) => markElevationGranted(current, capability))\n        setCopiedKey('')\n        const clean = JSON.stringify(toPayload(formRef.current)) === cleanPayloadRef.current\n        setForm((current) => (current === null ? current : { ...current, [capability]: true }))\n        setElevationNotice(clean ? t('elev.granted') : t('elev.grantedNeedSave'))\n        if (clean) setAutoSavePending(true)\n        refreshGrantState()\n      }\n\n      const beginElevation = (capability) => {\n        setElevationNotice('')\n        setCopiedKey('')\n        // 只增改**这一个**能力的记录，别的 pending 原样留着（面板不再被替换）\n        setElevations((current) => upsertElevationRecord(current, capability, {\n          capability,\n          command: undefined,\n          expiresAt: undefined,\n          error: undefined,\n          // 清掉上一轮的「已授权」痕迹：撤销授权后再点这个开关要能重新出面板\n          granted: false,\n        }))\n        api.elevateBegin(capability).then((result) => {\n          if (result !== null && result.status === 'granted') {\n            finishElevation(capability)\n            return\n          }\n          if (result !== null && result.status === 'pending') {\n            setElevations((current) => upsertElevationRecord(current, capability, {\n              capability,\n              command: String(result.command),\n              expiresAt: Number(result.expiresAt),\n            }))\n            return\n          }\n          setElevations((current) => upsertElevationRecord(current, capability, {\n            capability,\n            error: String((result && result.error) ?? ''),\n          }))\n        }).catch((error) => setElevations((current) => upsertElevationRecord(current, capability, {\n          capability,\n          error: String(error.message),\n        })))\n      }\n\n      const revokeElevation = (capability) => {\n        setElevationNotice('')\n        api.elevateRevoke(capability).then(() => {\n          setElevationNotice(t('elev.revoked'))\n          refreshGrantState()\n        }).catch((error) => setElevationNotice(t('elev.error') + String(error.message)))\n      }\n\n      /**\n       * 复制命令：拿不到剪贴板（老宿主 / 非安全上下文）时退回「请手动复制」。\n       *\n       * `key` 是反馈的归属：单条按钮传能力名，合并按钮传 `ELEVATION_COPY_ALL`——\n       * 于是「复制了 A」不会让 B 的按钮也显示「已复制」（早先是一个全局 `copied`）。\n       */\n      const copyCommand = (key, command) => {\n        const clipboard = typeof navigator === 'undefined' ? undefined : navigator.clipboard\n        if (clipboard === undefined || typeof clipboard.writeText !== 'function') {\n          setElevationNotice(t('elev.copyManual'))\n          return\n        }\n        clipboard.writeText(command).then(() => setCopiedKey(key)).catch(() => setElevationNotice(t('elev.copyManual')))\n      }\n\n      /**\n       * 合并复制：把所有**仍 pending**（未过期、已拿到命令）的命令按发起顺序用换行连接后一次复制。\n       *\n       * 命令的取用 / 排序 / 连接全在纯函数里（`client-src/elevation.js` 的 `buildMergedElevationText`\n       * 与 `joinElevationCommands`），这里只负责把它交给剪贴板。连接方式为什么是换行而不是 `&&` / `;`：\n       * bash / zsh / PowerShell / cmd 粘贴多行都逐行执行，平台无关；`&&` 在 PS 5.1 上不认，`;` 在 cmd\n       * 上不认。文案只说「执行后全部开关自动解锁」，不承诺同一时刻：两个 challenge 的 TTL 与探测\n       * 周期各自独立（逐面板倒计时照旧显示）。\n       */\n      const copyAllElevations = (text) => {\n        if (text === '') {\n          setElevationNotice(t('elev.copyManual'))\n          return\n        }\n        copyCommand(ELEVATION_COPY_ALL, text)\n      }\n\n      /*\n       * 授权成功后的自动保存：必须等表单提交一次再保存——`save()` 读的是表单镜像\n       * （`formRef.current`，在渲染期同步），在同一个 tick 里调它写的是**改之前**的表单。\n       */\n      saveRef.current = save\n      useEffect(() => {\n        if (!autoSavePending) return\n        setAutoSavePending(false)\n        if (saveRef.current !== null) saveRef.current()\n      }, [autoSavePending])\n\n      /*\n       * 面板开着时轮询授权状态（1.5s）并顺带推进倒计时。轮询而不是等推送：这条通道本来就是\n       * 「用户在别的终端里做了一件事」，宿主没有可订阅的事件面。\n       *\n       * **轮询全部 pending 能力**（不再只盯单槽那一个）：两个 challenge 是各自独立开始的，\n       * 各自的授权时刻可以差十几秒；只轮询一个会让另一个停在「宿主已授权、开关没开」。\n       * deps 用**能力名的拼接串**而不是数组：数组每次渲染都是新引用，effect 会被反复拆装，\n       * 1.5s 的节拍随之漂成「每渲染一次就重建定时器」。内容不变时它一字不变，effect 就不动。\n       */\n      const elevationPendingKey = elevations\n        // 已授权的那条只是「留痕」（面板已消失），不再轮询——否则每 1.5s 又会走一遍 finishElevation\n        .filter((item) => item.granted !== true)\n        .map((item) => String(item.capability))\n        .sort()\n        .join(',')\n      useEffect(() => {\n        if (elevationPendingKey === '') return undefined\n        const capabilities = elevationPendingKey.split(',')\n        const timer = setInterval(() => {\n          setNowTick((value) => value + 1)\n          for (const capability of capabilities) {\n            api.elevateStatus(capability).then((status) => {\n              if (status !== null && status.status === 'granted') finishElevation(capability)\n            }).catch(() => {\n              /* 轮询失败静默：宿主可能在重启，下一次再试 */\n            })\n          }\n        }, 1500)\n        return () => clearInterval(timer)\n      }, [elevationPendingKey])\n\n      /* ---------------- 能力开关那一段的渲染 ---------------- */\n\n      /**\n       * 一个能力开关 + 「未生效」徽标。返回**两个**节点：复选框与文字标签。\n       *\n       * 未获授权时点它 = **发起就地授权**（展开面板给出确认命令），不是「点一下弹一句」的循环，\n       * 也**不是**把「看着开着」的配置关掉——用户点它是想说「我要它真的生效」。要关掉配置，\n       * 面板里有单独的「先关掉这个配置开关」。\n       *\n       * 复选框与文字拆成两格（见 `capabilityRow` 的网格）：授权状态行要落在**文字**下面，而不是\n       * 落在复选框下面——那需要一个「文字左边缘」的参照，用 `padding` 猜一个像素值会随字号与平台\n       * 漂，两列网格是同一件事的确定写法（`htmlFor` 保住「点文字也能勾」）。\n       */\n      const capabilityCheck = (capability, label, id) => {\n        const configured = form[capability] === true\n        const granted = form[`${capability}Granted`] === true\n        return [\n          jsx('input', {\n            id,\n            type: 'checkbox',\n            checked: configured,\n            onChange: (event) => {\n              if (granted !== true) {\n                beginElevation(capability)\n                return\n              }\n              patch({ [capability]: event.target.checked })\n            },\n          }, 'box'),\n          jsxs('label', { className: 'dk_capLabel', htmlFor: id, children: [\n            label,\n            configured && !granted\n              ? jsx('span', { className: 'dk_badge', 'data-state': 'paused', children: t('badge.notEffective') })\n              : null,\n          ] }, 'label'),\n        ]\n      }\n\n      /**\n       * 授权时刻 → **固定格式** `YYYY-MM-DD HH:mm:ss`（本地时区）。\n       *\n       * 为什么不用 `toLocaleString()`：它给的是 `2026/9/26 22:37:30` 这种斜杠 + 不补零的形状，\n       * 两个能力的时刻并排时既不好扫读、也不跟宿主日志里的 ISO 时刻对得上（审计要能对照）。\n       * 秒保留：与日志的 `grantedAt=` 逐字段对得上，比省两个字符值。\n       */\n      const formatGrantedAt = (seconds) => {\n        const date = new Date(Number(seconds) * 1000)\n        if (Number.isNaN(date.getTime())) return String(seconds)\n        const pad = (value) => String(value).padStart(2, '0')\n        return `${String(date.getFullYear())}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`\n      }\n\n      /**\n       * 一个能力**自己的**授权状态行（跟在这个能力的开关后面，而不是两个能力合排一行）。\n       *\n       * 为什么必须贴着各自的开关：`file` 通道的授权是**逐能力**的，两个「撤销宿主授权」并排放在\n       * 一行里时，没人能看出哪个按钮撤的是哪个能力——那是「界面说了但没说清」的典型。\n       *\n       * 顺带带上**授权时刻**（kit D09）：授权是持久的，重启后它直接生效、不再有任何确认，用户至少\n       * 该看得出它是什么时候来的。`*GrantSource === 'env'` 没有时刻（启动环境没有「授权时刻」），\n       * 那一档给的是「去改启动环境」的说明，不给按钮——环境变量授权撤不了。\n       */\n      const grantState = (capability) => {\n        if (form[`${capability}Granted`] !== true) return null\n        if (form[`${capability}GrantSource`] === 'env') {\n          return jsx('span', { className: 'dk_capState', children: t('elev.viaEnv') })\n        }\n        const grantedAt = form[`${capability}GrantedAt`]\n        return jsxs('span', { className: 'dk_capState', children: [\n          Number.isFinite(grantedAt)\n            ? jsx('span', { children: t('elev.grantedAt', { time: formatGrantedAt(grantedAt) }) }, 'at')\n            : null,\n          /*\n           * 危险色（`dk_btnDanger`，D148）：与同一个卡片里的「删除目标 / 删除指纹」同色——\n           * 三者都是「按下去就少一条记录、要重新配回来」的动作，红/灰混用会让人以为撤销可随手点。\n           * tty 卡片那份（`tt_capRevoke`）本来就是危险色，两处必须一致（用户反馈：为什么风格不统一）。\n           */\n          jsx('button', {\n            type: 'button',\n            className: 'dk_btn dk_btnDanger dk_capRevoke',\n            onClick: () => revokeElevation(capability),\n            children: t('elev.revoke'),\n          }, 'revoke'),\n        ] })\n      }\n\n      /**\n       * 一个能力一块：`[复选框] [开关文字]` 一行，授权状态**另起一行、与文字左对齐**。\n       *\n       * 为什么不做成「一行内右对齐」（试过，实测不合格）：标签长度随语言变（中文「允许变更操作\n       * （容器启停删、镜像拉取 / 删除 / 清理）」313px、英文更长），一行里塞「文字 + 状态 + 按钮」\n       * 必然有的行换行、有的不换行——实测：短标签那行按钮右缘 1020，长标签那行整组被挤到下一行、\n       * 右缘只有 812（按钮的 `margin-left:auto` 生效在状态 span **内部**，推不到行右缘）。\n       * 状态另起一行后，换行不再取决于标签长度；按钮落在第二列上（状态撑满该列 + 按钮自动右推），\n       * 两个能力的按钮天然在同一竖线上。\n       */\n      const capabilityRow = (capability, label) => {\n        const id = `dk-cap-${capability}`\n        return jsxs('div', { className: 'dk_capRow', children: [\n          ...capabilityCheck(capability, label, id),\n          grantState(capability),\n        ] })\n      }\n\n      /**\n       * 一块能力的面板（✕）与整个面板组都渲染自 `elevationPanelsView`（factory 级纯函数，\n       * 见那段注释）：组件这边只提供**状态与回调**，界面结构留在纯函数里，冒烟才驱动得动。\n       *\n       * 逐个能力的动作语义：\n       * - ✕ 只收起**这一个**能力的面板；别的 pending 原样留着（也不撤销宿主侧 challenge，\n       *   与改造前 close 的语义一致——challenge 仍在 pending，重新点开关即复用同一条命令）。\n       * - 「重新生成」= 再走一次 `beginElevation`（逐能力幂等，不动别的能力）。\n       * - 「先关掉这个配置开关」= 关配置 + 收起自己那块面板。\n       */\n      const closeElevationPanel = (capability) => {\n        setElevations((current) => pruneElevationRecords(removeElevationRecord(current, capability)))\n        setCopiedKey('')\n      }\n\n      const elevationPanels = () => elevationPanelsView(elevations, {\n        now: Date.now(),\n        copiedKey,\n        configured: (capability) => form[capability] === true,\n        onCopy: (capability, command) => copyCommand(capability, command),\n        onCopyAll: (text) => copyAllElevations(text),\n        onRegenerate: (capability) => beginElevation(capability),\n        onClose: (capability) => closeElevationPanel(capability),\n        onDisableFirst: (capability) => {\n          patch({ [capability]: false })\n          closeElevationPanel(capability)\n        },\n      })\n\n      const sectionTitle = (text) => jsx('div', { className: 'dk_cardSection', children: text })\n\n      const field = (label, control, hint, span) => jsxs('div', {\n        className: 'dk_field',\n        'data-span': span === undefined ? undefined : String(span),\n        children: [\n          jsx('span', { className: 'dk_label', children: label }),\n          control,\n          hint === undefined ? null : jsx('span', { className: 'dk_hint', children: hint }),\n        ],\n      })\n\n      const numberInput = (key, min, max, hint) => jsx('input', {\n        className: 'dk_input',\n        type: 'number',\n        min,\n        max,\n        // 有草稿就显示草稿（哪怕是空串 / 非法中间态），没有则回显表单里的有效值（D113）\n        value: numberDrafts[key] ?? form[key],\n        onChange: (event) => {\n          const raw = event.target.value\n          // 先无条件落草稿：受控 input 必须把用户敲的中间态**原样显示回去**，否则退格\n          // 删最后一位会立刻回弹旧值、`-` / `1e` 这种半截输入也打不出来（D113）。\n          setNumberDrafts((drafts) => ({ ...drafts, [key]: raw }))\n          // 只有合法整数才进表单（D69）：空串 / `-` / `1e` 这些中间态留在草稿里，\n          // 不写表单——写进去会被后端 clampInt 判为非法并静默退回默认值，用户却以为改上了\n          if (!/^-?\\d+$/.test(raw)) return\n          patch({ [key]: Number(raw) })\n        },\n        // 失焦收掉草稿（D113）：半截输入不留在框里，回显表单里那个有效值——\n        // 于是「清空后不管它」不会被当成 0，也不会留在非法中间态上。\n        onBlur: () => setNumberDrafts((drafts) => {\n          if (!Object.prototype.hasOwnProperty.call(drafts, key)) return drafts\n          const next = { ...drafts }\n          delete next[key]\n          return next\n        }),\n      })\n\n      if (view === 'summary') {\n        return t('card.desc')\n      }\n\n      /*\n       * 卡片外壳：整条 li 就是卡片（标题行 + 展开体在同一张卡里），\n       * 与 DSH 内置卡片 / 其他插件卡片（pM_pluginCard、tt_card）用同一套度量，\n       * 别再用内联样式自己捏一个「看起来是另一套」的头部。\n       * page 视图（DSH ≥0.1.6 的插件配置页）不渲染卡片头：新页面自己画标题/图标/面包屑。\n       */\n      const card = (body) => pageView\n        ? jsx('div', { className: 'dk_pageHost', children: body })\n        : jsxs('li', {\n        className: 'dk_settingsCard' + (open ? ' dk_settingsCardOpen' : ''),\n        children: [\n          jsxs('button', {\n            type: 'button',\n            className: 'dk_settingsHead',\n            'aria-expanded': open,\n            onClick: () => setOpen((value) => !value),\n            children: [\n              jsxs('span', { className: 'dk_settingsHeadText', children: [\n                jsx('span', { className: 'dk_settingsName', children: t('card.name') }),\n                jsx('span', { className: 'dk_settingsDesc', children: t('card.summary') }),\n              ] }),\n              jsx('span', { className: 'dshkit_badge', children: 'Kit' }),\n              jsx('span', { className: 'dk_settingsChevron', dangerouslySetInnerHTML: { __html: ICON_CHEVRON } }),\n            ],\n          }),\n          open ? jsx('div', { className: 'dk_settingsBody', children: body }) : null,\n        ],\n      })\n\n      if (!open) return card(null)\n      if (!loaded || form === null) {\n        return card(jsxs('div', { className: 'dk_row', children: [jsx('span', { className: 'dk_spin' }), t('list.loadingConfig')] }))\n      }\n\n      return card([\n        sectionTitle(t('section.basic')),\n        jsxs('div', { className: 'dk_row', children: [\n          jsx('label', { className: 'dk_check', children: [jsx('input', { type: 'checkbox', checked: form.enabled, onChange: (event) => patch({ enabled: event.target.checked }) }), t('check.enabled')] }),\n          jsx('label', { className: 'dk_check', children: [jsx('input', { type: 'checkbox', checked: form.announceToAgent, onChange: (event) => patch({ announceToAgent: event.target.checked }) }), t('check.announce')] }),\n        ] }),\n        // 字段用栅格而不是 flex 换行：标签 + 控件按列对齐，数字框宽度一致\n        jsxs('div', { className: 'dk_fieldGrid', children: [\n          field('docker CLI', jsx('input', { className: 'dk_input', value: form.dockerBin, onChange: (event) => patch({ dockerBin: event.target.value }) }), t('hint.dockerBin')),\n          field(t('field.pollInterval'), numberInput('pollIntervalSec', 1, 60)),\n          field(t('field.logTailDefault'), numberInput('logTailDefault', 1, 5000), t('hint.logTailDefault')),\n          field(t('field.maxOutput'), numberInput('maxOutputKb', 1, 8192), t('hint.maxOutput')),\n          field(t('field.execTimeout'), numberInput('execTimeoutSec', 1, 120)),\n        ] }),\n\n        sectionTitle(t('section.capabilities')),\n        /*\n         * 两个开关**不再 disabled**。未获宿主授权时点它就地发起授权（见 capabilityCheck）；\n         * 已授权时它就是普通开关，关掉随时可用（宿主侧不拦降权：紧急刹车不能依赖重启）。\n         *\n         * **一个能力一行**（不是两个开关并排 + 底下一行授权状态）：授权是逐能力的，并排时两个\n         * 「撤销宿主授权」谁管谁全靠猜。行内是「开关 … 状态 …（右）撤销按钮」，扫一眼就对上。\n         */\n        jsxs('div', { className: 'dk_capList', children: [\n          capabilityRow('allowMutations', t('check.allowMutations')),\n          capabilityRow('allowExec', t('check.allowExec')),\n        ] }),\n        jsx('span', { className: 'dk_hint', children: t('hint.socketRoot') }),\n        form.allowMutationsGranted === true && form.allowExecGranted === true\n          ? null\n          : jsx('span', { className: 'dk_hint dk_hintWarn', children: t('hint.capabilityNotGranted') }),\n        elevationNotice === ''\n          ? null\n          : jsx('span', { className: 'dk_hint', children: elevationNotice }),\n        elevations.length === 0 ? null : elevationPanels(),\n\n        sectionTitle(t('field.target')),\n        ...form.targets.map((item, index) => {\n          /*\n           * 失效引用（引用的条目名不在 tty 连接簿里）：下拉会**渲染成空白**——没有任何\n           * option 与 item.book 匹配，界面上看不出\"这里引用错了\"，要等真去连才报错。\n           * 这里两件事一起做：给那一行标记 data-stale（标黄），并把失效的名字补成一个\n           * 显式 option，免得用户看到一个空白下拉、以为是\"没选\"。\n           */\n          const stale = staleBookRef(item, form.ttyBooks)\n          return jsxs('div', { className: 'dk_targetRow', 'data-stale': stale !== undefined ? '1' : undefined, children: [\n          jsx('input', { className: 'dk_input', value: item.name, placeholder: t('placeholder.targetName'), onChange: (event) => patchTarget(index, { name: event.target.value }) }),\n          jsx('select', { className: 'dk_select', value: item.kind, onChange: (event) => patchTarget(index, { kind: event.target.value }), children: [\n            jsx('option', { value: 'local', children: t('option.local') }),\n            jsx('option', { value: 'ssh', children: t('option.sshHost') }),\n          ] }),\n          item.kind === 'local'\n            ? jsx('span', { className: 'dk_hint', children: t('hint.localTarget') })\n            : jsxs('div', { className: 'dk_row', style: { gridColumn: 'span 1' }, children: [\n              jsx('select', {\n                className: 'dk_select',\n                value: item.book ?? '',\n                onChange: (event) => patchTarget(index, { book: event.target.value }),\n                title: stale !== undefined ? t('hint.staleBook', { book: stale }) : undefined,\n                children: [\n                  jsx('option', { value: '', children: form.ttyBooks.length === 0 ? t('option.noTtyBooks') : t('option.inlineConnection') }),\n                  // 失效的名字排在最前并显式标注：否则它没有对应 option，下拉显示空白\n                  ...(stale !== undefined ? [jsx('option', { value: stale, children: t('option.staleBook') + stale }, stale)] : []),\n                  ...form.ttyBooks.map((name) => jsx('option', { value: name, children: t('option.bookNamed', { name }) }, name)),\n                ],\n              }),\n              stale !== undefined\n                ? jsx('span', { className: 'dk_hint dk_hintWarn', children: t('hint.staleInline', { book: stale }) })\n                : null,\n            ] }),\n          jsx('button', { type: 'button', className: 'dk_btn dk_btnDanger', onClick: () => removeTarget(index), children: t('btn.delete') }),\n          /*\n           * 内联 SSH 字段：栅格而不是 flex 换行——host / port / username / auth 与上方\n           * 目标名那行上下对齐，凭据（私钥或密码）单独占一行，复选框固定在行尾列。\n           */\n          item.kind === 'ssh' && (item.book ?? '') === '' ? jsxs('div', { className: 'dk_targetInline', children: [\n            jsx('input', { className: 'dk_input', placeholder: 'host', value: item.host ?? '', onChange: (event) => patchTarget(index, { host: event.target.value }) }),\n            jsx('input', { className: 'dk_input', placeholder: '22', title: t('field.ports'), value: item.port ?? 22, onChange: (event) => patchTarget(index, { port: Number(event.target.value) || 22 }) }),\n            jsx('input', { className: 'dk_input', placeholder: 'username', value: item.username ?? '', onChange: (event) => patchTarget(index, { username: event.target.value }) }),\n            jsx('select', { className: 'dk_select', value: item.auth ?? 'agent', onChange: (event) => patchTarget(index, { auth: event.target.value }), children: [\n              jsx('option', { value: 'agent', children: 'ssh-agent' }),\n              jsx('option', { value: 'key', children: t('option.authKey') }),\n              jsx('option', { value: 'password', children: t('option.authPassword') }),\n            ] }),\n            (item.auth ?? 'agent') === 'key' ? jsx('input', { className: 'dk_input dk_credential', placeholder: '~/.ssh/id_ed25519', title: t('hint.keyPath'), value: item.