onst [shellOptions, setShellOptions] = React.useState([])\n  const [shellListOpen, setShellListOpen] = React.useState(false)\n  /*\n   * 模型候选目录（/api/dsh-tty/model-catalog）：**渠道 + 模型一张表**（groups = 按 provider 分组）。\n   * 失败要与「目录是空的」分开记：前者要说「拿不到」（多半是宿主没重启），后者才叫「没有候选」。\n   */\n  const [modelCatalog, setModelCatalog] = React.useState({ groups: [], loading: false, failed: false })\n  const [routeListOpen, setRouteListOpen] = React.useState(false)\n  /** 候选浮层的锚点（定位用）；列表本身是 position:fixed，不进卡片布局。 */\n  const routeInputRef = React.useRef(null)\n  /** Shell 路径候选浮层的锚点（同上：列表 fixed，只是宽度与位置对齐这个输入框）。 */\n  const shellInputRef = React.useRef(null)\n  /** 候选请求的序号（见 loadModelCatalog）：迟到的响应不许覆盖新结果。 */\n  const catalogSeqRef = React.useRef(0)\n\n  /** 设置卡片分组小标题：字段多了以后靠它把卡片切成可扫读的几段。 */\n  const sectionTitle = (text) => jsx('div', { className: 'tt_cardSection', children: text })\n\n  const load = async () => {\n    try {\n      const res = await fetch('/api/dsh-tty/config', { cache: 'no-store' })\n      const data = await res.json()\n      if (data.ok && typeof data.config === 'object' && data.config !== null) {\n        formRef.current = data.config\n        cleanPayloadRef.current = JSON.stringify(toPayload(data.config))\n        setForm(data.config)\n        syncSshHostsCache(data.config) // 连接簿缓存与设置保持一致（「+」菜单共用）\n      } else setMessage({ kind: 'error', text: String(data.error || t('error.configLoadFailed')) })\n    } catch (error) {\n      setMessage({ kind: 'error', text: String(error && error.message ? error.message : error) })\n    }\n  }\n  const loadShellOptions = async () => {\n    try {\n      const res = await fetch('/api/dsh-tty/shells', { cache: 'no-store' })\n      const data = await res.json()\n      if (data.ok && Array.isArray(data.shells)) setShellOptions(data.shells)\n    } catch {\n      /* 网络失败：候选保持为空，输入框照常可用 */\n    }\n  }\n  /*\n   * 卡片里两张候选表（模型路由 / Shell 路径）的浮层定位。**必须**在 layout 阶段做：列表是\n   * position:fixed，渲染完才知道多高、placePopover 要按高度决定往上翻还是往下放（同「+」菜单）。\n   * 依赖里带上