oredKeys.length > 0) startup.hostKeys = storedKeys\n        const storedTunnels = sanitizeTunnels(stored.tunnels)\n        if (storedTunnels !== undefined && storedTunnels.length > 0) startup.tunnels = storedTunnels\n        if (Object.keys(startup).length > 0) applyPatch(startup)\n        /*\n         * 连接簿名字的**别名来源**（D104 补）：docker 卡片上显示给用户的是「目标名」，\n         * 而 `book` 认的是连接簿条目名——两者常常完全不同（现场：`kb-target` / `KB_APP`）。\n         * 这里把 docker 命名空间里的「目标名 → 它引用的条目名」读一份当别名，于是\n         * `book=kb-target` 直接解析到 `KB_APP`，agent 不必先绕一次 docker_targets。\n         *\n         * 只在设置服务就绪时装配；本命名空间外的读取**只取拓扑**（name / book），\n         * 不碰任何凭据字段。docker 没装 / 未配置时读到空表，退化回「只有条目名」的旧行为。\n         */\n        setBookAliasSource(() => readDockerBookAliases(settingsCtx))\n        const off = scope.onChanged(() => applyPatch(scope.get()))\n        return () => {\n          off()\n          offAutoPage()\n          settingsScope = undefined\n          setBookAliasSource(undefined)\n        }\n      }, 'dsh-tty: settings')\n    })\n\n    // agent 工具集（P1）：tty_list / tty_open / tty_close / tty_stats / tty_capture / tty_send …\n    // 信任模型（2026-10-07 起，档位闸落地）：注册仍只受 enabled 门控，但**每次调用**受会话权限\n    // 档位约束——受限档（仅可查看 / 工作区内修改）下 write/exec 类要经宿主 approval 服务逐次\n    // 确认，完全权限档零询问（机制见 kit 的 tier-gate.ts，方案见 docs/permission-tier-plan.md）。\n    // 「agent 对终端的操作实时出现在面板里」的可见性仍然成立，但不再是唯一的监督手段——\n    // 旧注释「与 bash 工具同权、不额外加确认层」描述的是档位闸落地前的模型，已作废。\n    const toolsHost = (ctx as unknown as { get(name: string): { register(definition: unknown): () => void } | undefined }).get('tools')\n    if (toolsHost !== undefined) {\n      ctx.effect(() => {\n        const tools = toolsHost\n        const tailLines = (session: TtySession, lines: number): string => {\n          const parts = session.buffer.split('\\n')\n          return parts.slice(-(lines + 1)).join('\\n').replace(/^\\n+/, '')\n        }\n        let activeDisposers: Array<() => void> = []\n        /** 本次真注册的工具名（启动日志的「实际注册集」；能力全集是文件末尾那行 registered）。 */\n        let registeredNames: string[] = []\n        /** 幂等重注册：撤下现有工具后按 enabled 决定是否重挂（禁用热生效的入口；由 applyPatch 经 refreshToolsHook 触发）。 */\n        const registerAll = (): void => {\n          for (const dispose of activeDisposers) {\n            try {\n              dispose()\n            } catch {\n              /* 工具已注销 */\n            }\n          }\n          activeDisposers = []\n          registeredNames = []\n          if (!stateRef.enabled) {\n            stateRef.toolsRegistered = false\n            console.log('[dsh-tty] agent tools skipped (disabled)')\n            return\n          }\n          /**\n           * 注册一个工具并**记下它的名字**（active 日志用；返回值照旧进 activeDisposers，push 顺序不变）。\n           * 所有工具都必须经这里注册——绕过它 = 日志里的「实际注册集」少一个名字。\n           */\n          const registerTool = (definition: ReturnType<typeof defineTool>): (() => void) => {\n            registeredNames.push(definition.name)\n            return tools.register(definition)\n          }\n          activeDisposers.push(registerTool(defineTool({\n            name: 'tty_list',\n            // 只读工具：与同轮其它工具并发执行（宿主默认把未声明的工具当独占，见项目级 ROADMAP 第 4 项）\n            isConcurrencySafe: () => true,\n            description: '列出当前终端面板会话（sid / kind(local|ssh) / target / pid / cwd / 创建与最后活动时间），**含进程已退出但仍只读保留着的会话**（带 exited:true + 退出码/信号；按时间释放时另带 retainMs）。**running** 说明这个会话有没有命令在跑（true = 在跑，现在别往里发命令，那些字节会被正在跑的程序当输入吃掉；false = 命令已结束；**省略 = 无法判断**，**不是**「没在跑」——此时看 `runningUnknown`：ssh（远端 shell 不受控，永久未知）/ tmux-attach（接回后还没跑过命令，跑完一条即恢复）/ no-integration（fish·csh·cmd 等不受支持的 shell，或「shell 集成」被关））；同源的 lastExitCode / lastExitAt 是「上一条已完成命令」的退出码与结束时刻。用户开了终端面板后，用 tty_capture 读某个 sid 的输出。**写侧（发按键 / 开新会话）工具是否可用以你的工具表为准**——「仅可查看」档会把它们整批裁掉（请让用户切「工作区内修改」档，那档可用但**每次调用要用户确认**），「工作区内修改」及以上的档位里它们都在。已退出的会话只能读（写会报错），要接着操作请新开一条。',\n            parameters: {},\n            output: {\n              schema: {\n                type: 'object',\n                additionalProperties: false,\n                properties: {\n                  sessions: {\n                    type: 'array',\n                    required: true,\n                    items: {\n                      type: 'object',\n                      additionalProperties: false,\n                      properties: {\n                        sid: { type: 'string', required: true },\n                        kind: { type: 'string', required: true },\n                        target: { type: 'string', required: true },\n                        pid: { type: 'number' },\n                        cwd: { type: 'string', required: true },\n                        startedAt: { type: 'number', required: true },\n                        lastOutputAt: { type: 'number', required: true },\n                        persist: { type: 'boolean' },\n                        owner: { type: 'string', required: true },\n                        exited: { type: 'boolean' },\n                        exitCode: { type: 'number' },\n                        signal: { type: 'string' },\n                        retainMs: { type: 'number', description: '只读保留的剩余毫秒；省略 = 不按时间释放' },\n                        running: { type: 'boolean', description: '有命令正在执行；**省略 = 无法判断**（该会话没有 shell 集成标记），不等于「没在跑」' },\n                        runningUnknown: { type: 'string', description: 'running 省略时的成因：ssh（远端 shell 不受控，永久未知）/ tmux-attach（接回后还没跑过命令，跑完一条即恢复）/ no-integration（shell 不受支持或集成被关）' },\n                        lastExitCode: { type: 'number', description: '上一条已完成命令的退出码' },\n                        lastExitAt: { type: 'number', description: '上一条已完成命令的结束时刻（epoch ms）' },\n                      },\n                    },\n                  },\n                },\n              },\n              render: (_args: unknown, value: unknown) => {\n                // 局部名用 `list`：`sessions` 在这个作用域里是**宿主的 SessionManager**\n                // （下面要问它 hiddenCount），叫 sessions 会把它遮住。\n                const list = (value as { sessions?: SessionSnapshot[] })?.sessions ?? []\n                // 隐藏标签（0.30.0）：列表里没有它们，但**得让 agent 知道「没有」不等于\n                // 「用户没开终端」**——否则它会把这句话原样转述给正盯着自己标签的用户。\n                // 只报条数；文案与每轮 prompt 块**共用** hiddenSessionsNote（一处口径）。\n                const hiddenNote = hiddenSessionsNote(sessions.hiddenCount())\n                const text = list.length === 0\n                  ? '当前没有可用的终端面板会话（若工具表里有 tty_open 可自己开一个，否则引导用户打开终端面板）。'\n                  : '终端面板会话：' + list.map((s) => {\n                      const where = s.kind === 'ssh' ? `ssh ${s.target}` : `pid=${String(s.pid ?? '?')} cwd=${s.cwd}`\n                      const persist = s.persist === true ? ' [tmux 持久]' : ''\n                      const owner = s.owner === 'agent' ? ' [agent 开的]' : ''\n                      // D88：三态必须在**渲染文本**里就分得开——agent 只看得到这段文本，\n                      // 而「无法判断」与「空闲」在旧写法里都渲染成「没有标记」，正好把新加的\n                      // 第三态糊掉了（用户验收现场：自己那条会话与既有的两条长得一模一样）。\n                      // 正在跑的会话尤其要显眼：往里发命令会被那个程序当输入吃掉。\n                      const runMark = s.exited === true\n                        ? ''\n                        : s.running === true\n                          ? ' [运行中——现在别往里发命令]'\n                          : s.running === false\n                            ? ' [空闲]'\n                            : ` [命令状态未知——${runningUnknownNote(s.runningUnknown ?? 'no-integration')}]`\n                      // 已退出会话的退出码由 gone 那条统管，这里只标活会话的「上一条」\n                      const lastExit = s.exited === true || s.lastExitCode === undefined ? '' : ` [上一条命令 exitCode=${String(s.lastExitCode)}]`\n                      // D77：只读保留态必须显眼——否则 AI 会对着一个已经死掉的会话发命令\n                      const detail = s.signal !== undefined && s.signal !== '' ? `signal=${s.signal}` : s.exitCode === undefined ? '退出码未知' : `exitCode=${String(s.exitCode)}`\n                      const left = s.retainMs === undefined ? '（显式关闭前一直都在）' : ` ${String(Math.ceil(s.retainMs / 60000))} 分钟`\n                      const gone = s.exited === true ? ` [已退出 ${detail}·只读保留${left}——只能读，写会报错]` : ''\n                      return `\\n- sid=${s.